#include <bits/stdc++.h>
using namespace std;

int main() {
  int N,M;
  cin >> N >> M;
  vector<vector<int>> mp(N,vector<int> (M));
  vector<bool> use(M,true);
  vector<vector<bool>> ok(M,vector<bool> (N,true));
  for (int i=0; i<N; i++) {
    for (int j=0; j<M; j++) {
      cin >> mp[i][j];
    }
  }

  vector<bool> skip(M,false);
  vector<vector<int>> ans1(N,vector<int> (M));
  int term = N*M+1;
  int rep = N*M+1;
  int rep2;

  for (int i=0; i<M; i++) {
    ans1[0][i] = mp[0][i];
    ok[i][(ans1[0][i]-1)/M] = false;
  }
  for (int i=1; i<N; i++) {
    for (int j=0; j<M; j++) {
      use[j] = true;
      skip[j] = false;
    }
    for (int j=0; j<M; j++) {
      if (skip[j]) {
        continue;
      }
      term = N*M+1;
      rep = N*M+1;
      for (int k=0; k<M; k++) {
        if (use[k]) {
          if (ok[j][(mp[i][k]-1)/M]) {
            term = (mp[i][k] - ans1[i-1][j] + N*M) % (N*M);
            if (term < rep) {
              rep2 = k;
              rep = term;
            }
          }
        }
      }
      use[rep2] = false;
      ans1[i][j] = mp[i][rep2];
      ok[j][(ans1[i][j]-1)/M] = false;
      if (j != 0) {
        if (ans1[i][j] == ans1[i][j-1]) {
          skip[j] = true;
          skip[j-1] = false;
          ok[j-1][(ans1[i][j]-1)/M] = true;
          j = j-2;
        }
      }
    }
  }
  for (int i=0; i<N; i++) {
    for (int j=0; j<M; j++) {
      cout << ans1[i][j];
      if (j != M-1) {
        cout << " ";
      }
    }
    cout << endl;
  }

  vector<int> sss(N);
  vector<vector<int>> ans2(N,vector<int> (M));
  for (int i=0; i<M; i++) {
    for (int j=0; j<N; j++) {
      sss[j] = ans1[j][i];
    }
    sort(sss.begin(),sss.end());
    for (int j=0; j<N; j++) {
      ans2[j][i] = sss[j];
    }
  }

  for (int i=0; i<N; i++) {
    for (int j=0; j<M; j++) {
      cout << ans2[i][j];
      if (j != M-1) {
        cout << " ";
      }
    }
    cout << endl;
  }

}

