	int N,M;
	cin>>N>>M;

	vector<vector<int>> A(N,vector<int>(M));

	for(int i=0;i<N;i++){
		for(int j=0;j<M;j++){
			cin>>A[i][j];
			A[i][j]--;
		}
	}

	vector<vector<int>> B(N,vector<int>());

	for(int i=0;i<M;i++){
		vector<vector<pair<int,int>>> E(2*N+2,vector<pair<int,int>>());
		int S = 2*N;
		int T = S+1;

		for(int j=0;j<N;j++){
			E[S].emplace_back(j,1);
			E[N+j].emplace_back(T,1);
			for(int k=0;k<A[j].size();k++){
				int a = j;
				int b = A[j][k]/M;
				E[a].emplace_back(N+b,1);
			}
		}

		Dinic<int> D(E);
		D.maximum_flow(S,T);
		vector<int> era(N);
		for(int j=0;j<N;j++){
