bool dfs(int i)
{
	if (vis[i])
		return 0;
	vis[i] = 1;
	for (int j = 1;j <= n;j++)
		if (cnt[j][i] && (!match[j] || dfs(match[j])))
		{
			match[j] = i;
			vis[i] = 0;
			return 1;
		}
	return 0;
}

int main()
{
	scanf("%d%d",&n,&m);
	for (int i = 1;i <= n;i++)
		for (int j = 1;j <= m;j++)
		{
			scanf("%d",&a[i][j].first);
			a[i][j].second = (a[i][j].first - 1) % m + 1;
			a[i][j].first = (a[i][j].first - 1) / m + 1;
			cnt[i][a[i][j].first]++;
		}
	for (int i = 1;i <= m;i++)
	{
		memset(vis,0,sizeof(vis));
		memset(match,0,sizeof(match));
		for (int j = 1;j <= n;j++)
			dfs(j);
		for (int j = 1;j <= n;j++)
		{
			cnt[j][match[j]]--;
			for (int k = i;k <= m;k++)
				if (a[j][k].first == match[j])
				{
					swap(a[j][k],a[j][i]);
					break;
				}
		}
	}
	for (int i = 1;i <= n;i++,printf("\n"))
