	for (int i = 1;i <= m;i++)
		for (int j = 1;j <= n;j++)
			for (int k = j + 1;k <= n;k++)
				if (a[j][i].first > a[k][i].first)
					swap(a[j][i],a[k][i]);
	for (int i = 1;i <= n;i++,printf("\n"))
		for (int j = 1;j <= m;j++)
			printf("%d ",(a[i][j].first - 1) * m + a[i][j].second);
	return 0;
}

