bool check(int cur)
{
    for (int i = 1; i <= n; ++i) {
        if (!sum[cur][i] || vis[i]) continue;
        vis[i] = 1;
        if (!co[i] || check(co[i])) {
            co[i] = cur;
            return true;
        }
    }
    return false;
}

int main()
{
    cin >> n >> m;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            cin >> a[i][j];
            int group = (a[i][j]-1)/m+1;
            ++sum[i][group];
        }
    }
    for (int j = 1; j <= m; ++j) {
        memset(co, 0, sizeof co);
        for (int i = 1; i <= n; ++i) {
            memset(vis, 0, sizeof vis);
            check(i);
        }
        for (int i = 1; i <= n; ++i) {
            --sum[i][co[i]];
            for (int k = j; k <= m; ++k) {
                int group = (a[i][k]-1)/m+1;
                if (group == co[i]) {
                    swap(a[i][j], a[i][k]);
