        E[u][v] = 1;
        E[v][u] = 0;
    }
    bool BFS() {
        for (int i = 0; i < n; i++)
            level[i] = -1;
        queue<int> que;
        que.push(s);
        level[s] = 0;
        while(!que.empty()) {
            int u = que.front();
            que.pop();
            for (int v = 0; v < n; v++) {
                if (E[u][v] == 1 && level[v] == -1) {
                    level[v] = level[u] + 1;
                    que.push(v);
                }
            }
        }
        return level[t] != -1;
    }
    int DFS(int u, int nf) {
        if (u == t)
            return nf;
        int res = 0;
        for (int v = 0; v < n; v++) {
            if (E[u][v] == 1 && level[v] == level[u] + 1) {
                int tf = DFS(v, min(nf, 1));
                res += tf;
                nf -= tf;
                E[u][v] -= tf;
                E[v][u] += tf;
                if (nf == 0)
                    return res;
            }
        }
        if (!res)
            level[u] = -1;
        return res;
    }
    int flow(int res = 0) {
        while (BFS())
            res += DFS(s, 87878787);
        return res;
    }
