namespace Flow{
	int S,T,V,tot;
	int head[maxn*2],nxt[maxm*2],to[maxm*2],cap[maxm*2];
	int lvl[maxn*2],cur[maxn*2],q[maxn*2];
	void init(){
		tot=0;
		memset(head,-1,sizeof(head));
	}
	int addedge(int u,int v,int c){
		nxt[tot]=head[u];to[tot]=v;cap[tot]=c;head[u]=tot++;
		nxt[tot]=head[v];to[tot]=u;cap[tot]=0;head[v]=tot++;
		return tot-2;
	}
	void bfs(){
		rep(i,V)lvl[i]=-1;
		lvl[S]=0;
		int l=0,r=0;
		q[r++]=S;
		while(l<r){
			int x=q[l++];
			for(int i=head[x];~i;i=nxt[i]){
				if(cap[i]&&lvl[to[i]]<0){
					lvl[to[i]]=lvl[x]+1;
					q[r++]=to[i];
				}
			}
		}
	}
	int dfs(int x,int f){
		if(x==T)return f;
		for(int &i=cur[x];~i;i=nxt[i]){
			if(cap[i]&&lvl[to[i]]==lvl[x]+1){
				int d=dfs(to[i],min(f,cap[i]));
				if(d>0){
					cap[i]-=d;
					cap[i^1]+=d;
					return d;
				}
			}
		}
		return 0;
	}
	int work(){
		int res=0;
		for(;;){
			bfs();
			if(lvl[T]<0)break;
			rep(i,V)cur[i]=head[i];
			for(;;){
				int f=dfs(S,INF);
				if(!f)break;
				res+=f;
			}
		}
		return res;
	}
}

