const int MX = 100;

namespace bipartite_matching {
	const int LEFT = 100, RIGHT = 100;

	vector<int> G[LEFT];
	int paired[LEFT], parent[RIGHT];
	bool used[LEFT];

	bool dfs(int v) {
		if (used[v]) return false;
		used[v] = true;
		for (int u : G[v])
			if (parent[u] == -1 || dfs(parent[u])) {
				paired[v] = u;
				parent[u] = v;
				return true;
			}
		return false;
	}

	int find(int left, int right) {
		memset(paired, -1, sizeof(int) * left);
		memset(parent, -1, sizeof(int) * right);
		bool run = true;
		int size = 0;
		while (run) {
			memset(used, 0, sizeof(bool) * left);
			run = false;
			for (int i = 0; i < left; i++)
				if (paired[i] == -1 && dfs(i)) {
					size++;
					run = true;
				}
		}
		return size;
	}
}

