using namespace std;

template <class T> struct ford_fulkerson {
  struct Edge { int to, rev; T cap; };
  const T inf = numeric_limits<T>::max();
  const int n;
  vector<vector<Edge>> g;
  vector<bool> used;
  ford_fulkerson(int _n) : n(_n), g(n), used(n) {}
  void add_edge(int from, int to, T cap) {
    assert(from != to);
    assert(cap >= 0);
    if (!cap) return;
    g[from].emplace_back(Edge{to, (int)g[to].size(), cap});
    g[to].emplace_back(Edge{from, (int)g[from].size() - 1, 0});
  }
  T dfs(int v, int t, T f) {
    if (v == t) return f;
    used[v] = true;
    for (auto&& e : g[v]) {
      if (used[e.to] or !e.cap) continue;
      T d = dfs(e.to, t, min(f, e.cap));
      if (d > 0) {
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
      }
    }
    return 0;
  }
  T max_flow(int s, int t) {
    assert(s != t);
    T res = 0;
    while (true) {
      fill(begin(used), end(used), false);
      T f = dfs(s, t, inf);
      if (f == 0) return res;
      res += f;
    }
  }
};

