	cin >> N >> M;

	vector<vector<ll>> A(N + 1, vector<ll>(M + 1));
	repn(i, N)repn(j, M) cin >> A[i][j];

	vector<ll> fr(N*M + 1), to(N*M + 1);
	repn(i, N)repn(j, M) {
		ll x = A[i][j];
		to[x] = (x - 1) / M + 1;
		fr[x] = i;
	}

	//repn(x, N*M) {
	//	cout << x << " " << fr[x] << " " << to[x] << endl;
	//}

	vector<ll> gr(N*M + 1, 0);

	repn(i, M) {
		vector<vector<edge>> g(2 * N + 3);
		repn(i, N) {
			g[2 * N + 1].push_back({ 0,2 * N + 1,i,1 });
			g[N + i].push_back({ 0,N + i,2 * N + 2,1 });
		}

		repn(x, N*M) {
			if (gr[x] != 0) { continue; }
			g[fr[x]].push_back({ x,fr[x],N + to[x],1 });
		}

		Ford_Fulkerson gmatch(2 * N + 2, g, 2 * N + 1, 2 * N + 2);

		repn(v, N) {
			for (auto e : gmatch.flow[v]) {
				if (e.to==2*N+1) { continue; }
				//cout << e.ind << " " << v << " " << e.to << " " << e.fl << endl;
				if (e.fl == 1) { gr[e.ind] = i; }
			}
		}
		//cout << endl;
	}

	vector <vector<ll>> B(N + 1, vector<ll>(M + 1)), C(N + 1, vector<ll>(M + 1));
	repn(x, M*N) {
		B[fr[x]][gr[x]] = x;
		C[to[x]][gr[x]] = x;
	}



	repn(i, N) {
