}
int s,t,dep[N*N];
bool bfs ()
{
	memcpy (cur,top,sizeof (int)*(t+1));
	memset (dep,0,sizeof (int)*(t+1));
	queue <int> q;
	dep[s]=1,q.push (s);
	while (q.size ())
	{
		int u=q.front (); q.pop ();
		for (int kb=top[u]; kb; kb=lb[kb].nx)
		{
			int v=lb[kb].v,w=lb[kb].w;
			if (w&&!dep[v]) dep[v]=dep[u]+1,q.push (v);
		}
	}
	return dep[t];
}
int dinic (int u,int flow)
{
	if (u==t) return flow;
	int rest=flow;
	for (int &kb=cur[u]; kb; kb=lb[kb].nx)
	{
		int v=lb[kb].v,w=lb[kb].w;
		if (w&&dep[v]==dep[u]+1)
		{
			int k=dinic (v,min (rest,w));
			if (!k) dep[v]=1;
			rest-=k;
			lb[kb].w-=k,lb[kb^1].w+=k;
			if (!rest) break;
		}
	}
	return flow-rest;
}
