const int maxN = 103;

int n, m, col;
int a[maxN][maxN];

vector< pair<int, int> > adj[maxN];
int le[maxN], ri[maxN];
bool used[maxN];

bool pairUp(int node) {
    if (used[node]) return false;
    used[node] = true;

    for (auto to: adj[node]) {
        if (ri[to.first] == 0) {
            le[node] = to.first;
            ri[to.first] = node;
            return true;
        }
    }

    for (auto to: adj[node]) {
        if (pairUp(ri[to.first])) {
            le[node] = to.first;
            ri[to.first] = node;
            return true;
        }
    }

    return false;
}

int findEdge(int node, int dest) {
    for (int i = 0; i < adj[node].size(); i++) {
        auto to = adj[node][i];

        if (to.first == dest) {
            adj[node][i] = adj[node].back();
            adj[node].pop_back();
            return to.second;
        }
    }

    cerr << "Error";
    exit(-1);
}

void findColumn() {
    memset(le, 0, sizeof(le));
    memset(ri, 0, sizeof(ri));

    bool need = true;
    while (need) {
        need = false;
        memset(used, 0, sizeof(used));

        for (int i = 1; i <= n; i++)
            if (!le[i])
                need |= pairUp(i);
    }

    col++;
    for (int i = 1; i <= n; i++) 
        a[col][i] = findEdge(i, le[i]);
}

