namespace flow {

template <template <typename> typename Solver, 
          typename FlowGraph = graph::FlowGraph<true>,
          bool Restore = false>
class BipartiteMatching {
    using matching = std::pair<Node, Node>;
    ssize_t asz, bsz;
    FlowGraph fg, res;
    Node src, sink;
    std::set<std::tuple<Node, Node, ll>> edges;

    vec<matching> extract_() {
        vec<matching> ret;
        for (auto &&e : edges) {
            Node f, t;
            ll idx;
            std::tie(f, t, idx) = e;
            auto c = res[f][idx].cap();
            if (c == 0) ret.emplace_back(f, t - asz);
        }
        return ret;
    }

public:
    BipartiteMatching(ssize_t asz, ssize_t bsz)
        : asz(asz), bsz(bsz), fg(asz + bsz + 2), src(asz + bsz), sink(asz + bsz + 1)
    {
        for (ll i = 0; i < asz; i++) fg.add_edge(src, i, 1);
        for (ll i = 0; i < bsz; i++) fg.add_edge(i + asz, sink, 1);
    }

    void add_edge(Node f, Node t) {
        fg.add_edge(f, t + asz, 1);
        if (Restore) edges.emplace(f, t + asz, fg[f].size() - 1);
    }

    ll solve() {
        Solver<FlowGraph> solver(fg);
        auto ret = solver.max_flow(src, sink);
        if (Restore) res = std::move(solver.graph());
        return ret;
    }

    vec<matching> extract() {
        if constexpr (Restore) {
            return extract_();
        } else {
            assert(false);
        }
    }

};

}

namespace flow {

template <typename FlowGraph = graph::FlowGraph<true>>
class Dinic {
    FlowGraph flow_graph;
    vec<ll> dists;
    vec<ssize_t> used;
    Node src, sink;

    void bfs(Node start) {
        vec<ll> dists(flow_graph.size(), dinf);
        dists[start] = 0;
        std::queue<std::pair<ll, Node>> que;
        que.emplace(0, start);
        while (que.size()) {
            ll d;
            Node cur;
            std::tie(d, cur) = que.front();
            que.pop();
            for (const auto &e : flow_graph[cur]) {
                Node nxt;
                Capacity cap;
                tie(nxt, cap, std::ignore, std::ignore) = e;
                if (cap <= Capacity()) continue;
                if (dists[nxt] <= d + 1) continue;
                dists[nxt] = d + 1;
                que.emplace(d + 1, nxt);
            }
        }
        this->dists = move(dists);
    }

    Capacity dfs(Node cur, Node pre, Capacity flow) {
        if (cur == sink) return flow;
        for (auto idx = used[cur] + 1; idx < flow_graph[cur].size(); idx++) {
            used[cur]++;
            auto &e = flow_graph[cur][idx];
            if (dists[e.to()] <= dists[cur]) continue;
            if (e.cap() <= Capacity()) continue;
            if (e.to() == pre) continue;
            auto f = dfs(e.to(), cur, std::min(flow, e.cap()));
            e.cap() -= f;
            flow_graph[e.to()][e.rev_idx()].cap() += f;
            if (Capacity() < f) return f;
        }
        return Capacity();
    }

public:
    Dinic(const FlowGraph &flow_graph) :
        flow_graph(flow_graph), used(flow_graph.size()) { }

    Capacity max_flow(Node src, Node sink) {
        this->src = src;
        this->sink = sink;
        auto ret = Capacity();
        while (true) {
            bfs(src);
            if (dists[sink] == dinf) break;
            std::fill(ALL(used), -1);
            while (true) {
                auto tmp = dfs(src, -1, cinf);
                if (tmp == Capacity()) break;
                ret += tmp;
            }
        }
        return ret;
    }

    FlowGraph graph() {
        return flow_graph;
    }
};

}

int main() {
    ll n, m;
    std::cin >> n >> m;
    auto am = make_v<ll>(0, n, m);
    for (auto &&v : am) for (auto &&e : v) {
        std::cin >> e;
        e--;
    }
    auto bm = am;

    std::map<pll, std::set<ll>> edges;
    for (ll i = 0; i < n; i++) for (ll j = 0; j < m; j++) {
        ll v = am[i][j];
        edges[pll(i, v / m)].insert(v);
    }
    for (ll i = 0; i < m; i++) {
        flow::BipartiteMatching<flow::Dinic, graph::FlowGraph<true>, true> bim(n, n);
        for (auto &&e : edges) {
            ll a, b;
            std::tie(a, b) = e.first;
            bim.add_edge(a, b);
        }
        bim.solve();
        auto res = std::move(bim.extract());
        for (auto &&e : res) {
            ll a, b;
            std::tie(a, b) = e;
            auto &st = edges[pll(a, b)];
            bm[a][i] = *st.begin();
