const int MAXN = 230;
const int INF = 1<<29;
const int NIL = 0;

// A enumerado de 1 a A
// B enumerado de A+1 a A+B < MAXN
vi G[MAXN];
int A, B, match[MAXN], dist[MAXN];

bool bfs() {
	queue<int> q;
	for(int i=1; i<A+1; i++){
		if(match[i]==NIL) {
			dist[i]=0;
			q.push(i);
		} else dist[i]=INF;
	}
	dist[NIL] = INF;
	while(!q.empty()) {
		int u = q.front(); q.pop();
		if(u!=NIL) {
			for(int v : G[u]){
				if(dist[match[v]]==INF) {
					dist[match[v]] = dist[u] + 1;
					q.push(match[v]);
				}
			}
		}
	}
	return (dist[NIL]!=INF);
}

bool dfs(int u) {
	if(u!=NIL) {
		for(int v : G[u]){
			if(dist[match[v]]==dist[u]+1) {
				if(dfs(match[v])) {
					match[v] = u;
					match[u] = v;
					return true;
				}
			}
		}
		dist[u] = INF;
		return false;
	}
	return true;
}

int HK(){
	ms(match, 0);
	int MBM = 0;
	while(bfs())
		for(int i=1; i<A+1; i++)
			if(match[i]==NIL && dfs(i)) MBM++;
	return MBM;
}

