    for(int i=0; i<N; i++) {
        for(int j=0; j<M; j++) {
            cin >> board[i][j];
        }
    }

    vector< vector<int> > ans(N, vector<int>(M));
    for(int col=0; col<M; col++) {
        Dinic<int> fl(N*N + 2);
        int source = N*N, sink = source + 1;
        for(int i=0; i<N; i++) {
            fl.add_edge(source, i, 1);
            fl.add_edge(N+i, sink, 1);
        }

        vector< vector<int> > edges(N);
        for(int i=0; i<N; i++) {
            for(int j=0; j<M; j++) {
                if(used[i][j]) continue;
                edges[i].emplace_back(fl.G[i].size());
                fl.add_edge(i, N + (board[i][j] - 1) / M, 1);
            }
        }

        fl.max_flow(source, sink);
        vector<int> to(N);
        for(int i=0; i<N; i++) {
            for(auto x : edges[i]) {
                auto &e = fl.G[i][x];
                if(e.cap > 0) continue;
                to[i] = e.to % N;
                break;
            }
        }

        for(int i=0; i<N; i++) {
            for(int j=0; j<M; j++) {
                int id = (board[i][j] - 1) / M;
                if(to[i] == id and !used[i][j]) {
                    used[i][j] = true;
                    ans[i][col] = board[i][j];
