  for (int col = 0; col < w; col++) {
    matching mat(h, h);
    vector<vector<int>> go(h, vector<int>(h, -1));
    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        if (!used[a[i][j]]) {
          mat.add(i, a[i][j] / w);
          go[i][a[i][j] / w] = a[i][j];
        }
      }
    }
    assert(mat.solve() == h);
    for (int i = 0; i < h; i++) {
