			if(cnt[i][deg]==0){
				se[deg].insert(i);
			}
			cnt[p.first][deg]++;
			if(cnt[p.first][deg]>=2){
				que.push(P(p.first,deg));
			}
			swap(b[pos][i],b[pos][p.first]);
		}
		if(cnt[p.first][p.second]>=2){
			que.push(p);
		}
	}
	for(int i=0;i<n;i++){
		for(int j=0;j<m;j++){
			printf("%d%c",b[i][j],(j+1)==m?'\n':' ');
			int deg=(b[i][j]-1)/m;
			c[deg][j]=b[i][j];
		}
	}
	for(int i=0;i<n;i++){
		for(int j=0;j<m;j++){
			printf("%d%c",c[i][j],(j+1)==m?'\n':' ');
		}
	}
	return 0;
}

