	int lv[maxn],q[maxn],qn;
	void bfs(int S,int N)
	{
		for(int i=0;i<=N;i++)lv[i]=-1;
		qn=0;
		q[qn++]=S;lv[S]=0;
		for(int i=0;i<qn;i++)
		{
			int u=q[i];
			for(int j=head[u];j;j=nxt[j])
			{
				if(cap[j]&&lv[to[j]]==-1)
				{
					lv[to[j]]=lv[u]+1;
					q[qn++]=to[j];
				}
			}
		}
	}
