	int dfs(int x,int T,int f)
	{
		if(x==T)return f;
		int of=f;
		for(int &i=it[x];i&&f;i=nxt[i])
		{
			int u=to[i];
			if(cap[i]&&lv[u]==lv[x]+1)
			{
				int d=dfs(u,T,min(f,cap[i]));
				if(d)
				{
					cap[i]-=d;
					cap[i^1]+=d;
					f-=d;
					if(f==0)return of;
				}
			}
		}
		return of-f;
	}
	int max_flow(int S,int T,int N=-1)
	{
