void box_const(togasat::Solver& solver, Box& A)
{
    //各マスにM枚中ちょうど1枚が入る
    rep(i, N * M)
    {
        vector<int> box;
        rep(j, M) {box.emplace_back(id(i, j));}
        solver.addClause(box);
        rep(j, M)repi(k, j + 1, M)
        {
            vector<int> twice = {-box[j], -box[k]};
            solver.addClause(twice);
        }
    }
    rep(i, N)rep(j, M)
    {
      vector<int> ca;
      rep(k, M)
    {
        int x = boxid(i, k);
        ca.emplace_back(id(x,j));
    }
      solver.addClause(ca);
    }
}
void vert_const(togasat::Solver& solver, Box& A)
{
    //縦には同じに系列中ちょうど1枚が入る

    //y行におけるp行系列の存在場所
    vector<pi> G[N];
    rep(i, N)rep(j, M)
    {
        int p = A[i][j] / M;
        G[p].push_back(make_pair(i, j));
    }

    rep(p, N)rep(s, G[p].size())repi(t, s + 1, G[p].size())rep(j, M)
    {
        int a = G[p][s].first;
        int b = G[p][t].first;
        int x = boxid(a, j);
        int y = boxid(b, j);
        vector<int> twice = {-id(x, G[p][s].second), -id(y, G[p][t].second)};
        solver.addClause(twice);
    }

}
