struct Edge { int to; long long cap; int rev; long long cost; };
typedef std::vector<Edge> Edges;
typedef std::vector<Edges> Graph;


struct MaxFlow {
	Graph g;
	std::vector<int> level, iter;
	MaxFlow(int n) {
		level.resize(n);
		iter.resize(n);
		g.resize(n);
	}
	void add_edge(int from, int to, int cap, int cost = 0) {
		g[from].push_back(Edge{ to, cap, (int)g[to].size(),cost });
		g[to].push_back(Edge{ from,0,(int)g[from].size() - 1,-cost });
	}

	void bfs(int s) {
		std::fill(level.begin(), level.end(), -1);
		std::queue<int> q;
		level[s] = 0;
		q.push(s);
		while (!q.empty()) {
			int v = q.front(); q.pop();
			for (int i = 0; i < (int)g[v].size(); i++) {
				Edge& e = g[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}
	long long dfs(int v, int t, long long f) {
		if (v == t)return f;
		for (int& i = iter[v]; i < (int)g[v].size(); i++) {
			Edge& e = g[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				long long d = dfs(e.to, t, std::min(f, (long long)e.cap));
				if (d > 0) {
					e.cap -= d;
					g[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
	long long max_flow(int s, int t) {
		long long flow = 0;
		for (;;) {
			bfs(s);
			if (level[t] < 0)return flow;
			std::fill(iter.begin(), iter.end(), 0);
			long long f;
			while ((f = dfs(s, t, std::numeric_limits<long long> ::max())) > 0) {
				flow += f;
			}
		}
	}
};


