	scan v;
	for (int i = 0; i < n; i++)
		for (int j = 0; j < m; j++)
			v[i][j]--;
	for (int j = 0; j < m; j++)	{
		g.clear();
		g.resize(n);
		match.resize(n, -1);
		used.resize(n, false);
		for (int i = 0; i < n; i++)
			for (int k = j; k < m; k++)
				g[i].pb(v[i][k] / m);
		for (int i = 0; i < n; i++)
			if (ktun(i))
				used = vector<bool>(n, false);
		vector<int> elem(n);
		for (int i = 0; i < n; i++) {
			assert(match[i] != -1);
			elem[match[i]] = i;	
		}
		for (int i = 0; i < n; i++) 
			for (int k = j; k < m; k++)
				if (v[i][k] / m == elem[i])
					swap(v[i][k], v[i][j]);	
