using namespace std;

const int MAX_N = 205;
int H, W, A[MAX_N][MAX_N], B[MAX_N][MAX_N], C[MAX_N][MAX_N];
bool used[MAX_N][MAX_N];

struct edge {
	int to, cap, rev;
};

class MaxFlow {
public:
	vector<edge> G[MAX_N * 2 + 4];
	bool used[MAX_N * 2 + 4];

	void add_edge(int u, int v, int c) {
		G[u].push_back(edge{ v, c, (int)G[v].size() });
		G[v].push_back(edge{ u, 0, (int)G[u].size() - 1 });
	}
	int dfs(int pos, int to, int f) {
		if (pos == to) return f;
		used[pos] = true;

		for (int i = 0; i < G[pos].size(); i++) {
			if (used[G[pos][i].to] == true || G[pos][i].cap == 0) continue;

			int Z = dfs(G[pos][i].to, to, min(f, G[pos][i].cap));
			if (Z == 0) continue;

			G[pos][i].cap -= Z;
			G[G[pos][i].to][G[pos][i].rev].cap += Z;
			return Z;
		}
		return 0;
	}
	vector<pair<int, int>> max_flow(int u, int v) {
		while (true) {
			for (int i = 0; i < MAX_N * 2 + 4; i++) used[i] = false;
			int F = dfs(u, v, (1 << 30));
			if (F == 0) break;
		}

		vector<pair<int, int>> L;
		for (int i = 0; i < H; i++) {
			for (int j = 0; j < G[i].size(); j++) {
				if (G[i][j].to < H || G[i][j].to >= 2 * H) continue;
				if (G[i][j].cap == 0) L.push_back(make_pair(i, G[i][j].to - H));
			}
		}
		return L;
	}
};

int main() {
	cin >> H >> W;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) { cin >> A[i][j]; A[i][j]--; }
	}
	for (int i = 0; i < W; i++) {
		MaxFlow V;
		for (int j = 0; j < H; j++) {
			for (int k = 0; k < W; k++) {
				if (used[j][k] == false) V.add_edge(j, H + (A[j][k] / W), 1);
			}
		}
		for (int i = 0; i < H; i++) {
			V.add_edge(2 * H, i, 1);
			V.add_edge(H + i, 2 * H + 1, 1);
		}
		vector<pair<int, int>> E = V.max_flow(2 * H, 2 * H + 1);
		for (int j = 0; j < E.size(); j++) {
			for (int k = 0; k < W; k++) {
				if (used[E[j].first][k] == false && (A[E[j].first][k] / W) == E[j].second) {
					used[E[j].first][k] = true;
					B[E[j].first][i] = A[E[j].first][k];
					break;
				}
			}
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) C[i][j] = B[i][j];
	}
	for (int i = 0; i < W; i++) {
		vector<int> I;
		for (int j = 0; j < H; j++) I.push_back(C[j][i]);
		sort(I.begin(), I.end());
		for (int j = 0; j < H; j++) C[j][i] = I[j];
	}

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) { if (j) cout << " "; cout << B[i][j] + 1; } cout << endl;
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) { if (j) cout << " "; cout << C[i][j] + 1; } cout << endl;
	}
	return 0;
}

