class BipartiteMatch
{
	public:
	BipartiteMatch(int s)
	{
		matchedTo.resize(s,-1);
		edge.resize(s);
	}
	vector<vector<int> > edge;

	void add(int a, int b)
	{
		edge[a].push_back(b);
		edge[b].push_back(a);
		//cout << a << ", " << b << endl;
	}
	vector<int> matchedTo;
	bool augment(int s)
	{
		visited.clear();
		visited.resize(edge.size());
		return aug(s);
	}
	private:
	vector<bool> visited;
	bool aug(int s)
	{
		if(s<0){
			return true;
		}
		for(int i=0;i<edge[s].size();i++){
			int t=edge[s][i];
			if(!visited[t]){
				visited[t]=true;
				if (aug(matchedTo[t])){
					matchedTo[t]=s;
					matchedTo[s]=t;// matchedTo[s] を外から参照しないなら不要
					return true;
				}
			}
		}
		return false;
	}
};

