void solve(long long N, long long M, std::vector<std::vector<long long>> A){
	for(int i=0;i<N;i++){
		BipartiteMatch bp(2*M);
		for(int j=0;j<M;j++){
			int a=(A[i][j]-1)/M;
			for(int k=0;k<M;k++){
				if(c[a][k])continue;
				bp.add(j,M+k);
			}
		}
		for(int j=0;j<M;j++){
			bp.augment(j);
		}
		for(int j=0;j<M;j++){
			int k=bp.matchedTo[j]-M;
			int a=(A[i][j]-1)/M;
			c[a][k]=b[i][k]=A[i][j];
		}
	}
