#define MAX_N 3030303
long long extgcd(long long a, long long b, long long& x, long long& y) {
    long long d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1; y = 0;
    }
    return d;
}
long long mod_inverse(long long a, long long m) {
    long long x, y;
    if(extgcd(a, m, x, y) == 1) return (m + x % m) % m;
    else return -1;
}
vector<long long> fact(MAX_N+1, inf);
long long mod_fact(long long n, long long& e) {
    if(fact[0] == inf) {
        fact[0]=1;
        if(MAX_N != 0) fact[1]=1;
        for(ll i = 2; i <= MAX_N; ++i) {
            fact[i] = (fact[i-1] * i) % mod;
        }
    }
    e = 0;
    if(n == 0) return 1;
    long long res = mod_fact(n / mod, e);
    e += n / mod;
    if((n / mod) % 2 != 0) return (res * (mod - fact[n % mod])) % mod;
    return (res * fact[n % mod]) % mod;
}
// return nCk
long long mod_comb(long long n, long long k) {
    if(n < 0 || k < 0 || n < k) return 0;
    long long e1, e2, e3;
    long long a1 = mod_fact(n, e1), a2 = mod_fact(k, e2), a3 = mod_fact(n - k, e3);
    if(e1 > e2 + e3) return 0;
    return (a1 * mod_inverse((a2 * a3) % mod, mod)) % mod;
}

struct HopcroftKarp {
    vector< vector< int > > graph;
    vector< int > dist, match;
    vector< bool > used, vv;

    HopcroftKarp(int n, int m) : graph(n), match(m, -1), used(n) {}

    void add_edge(int u, int v) {
        graph[u].push_back(v);
    }

    void bfs() {
        dist.assign(graph.size(), -1);
        queue< int > que;
        for(int i = 0; i < graph.size(); i++) {
            if(!used[i]) {
                que.emplace(i);
                dist[i] = 0;
            }
        }

        while(!que.empty()) {
            int a = que.front();
            que.pop();
            for(auto &b : graph[a]) {
                int c = match[b];
                if(c >= 0 && dist[c] == -1) {
                    dist[c] = dist[a] + 1;
                    que.emplace(c);
                }
            }
        }
    }

    bool dfs(int a) {
        vv[a] = true;
        for(auto &b : graph[a]) {
            int c = match[b];
            if(c < 0 || (!vv[c] && dist[c] == dist[a] + 1 && dfs(c))) {
                match[b] = a;
                used[a] = true;
                return (true);
            }
        }
        return (false);
    }

    int bipartite_matching() {
        int ret = 0;
        while(true) {
            bfs();
            vv.assign(graph.size(), false);
            int flow = 0;
            for(int i = 0; i < graph.size(); i++) {
                if(!used[i] && dfs(i)) ++flow;
            }
            if(flow == 0) return (ret);
            ret += flow;
        }
    }

    void output() {
        for(int i = 0; i < match.size(); i++) {
            if(~match[i]) {
                cout << match[i] << "-" << i << endl;
            }
        }
    }
};

using mi = modint;
int n, m;
void output(vector<vector<int>>& v) {
    REP(i, n) {
        REP(j, m) {
            if(j) cout << " ";
            cout << v[i][j];
        }
        cout << endl;
    }
}

vector<vector<int>> func1(vector<vector<int>>& a) {
    vector<vector<int>> b(n, vector<int>(m, -1));
    REP(i, n) {
        HopcroftKarp hk(m, m);
        vector<int> rev(m);
        REP(j, n) {
            vector<int> v;
            REP(k, m) {
                if(b[j][k] == -1) v.pb(k);
            }
            REP(k, m) {
                if((a[j][k] - 1) / m == i) {
                    rev[(a[j][k] - 1) % m] = j;
                    REP(l, v.size()) {
                        hk.add_edge((a[j][k] - 1) % m, v[l]);
                    }
                }
            }
        }
        hk.bipartite_matching();
        REP(j, m) {
            b[rev[j]][hk.match[j]] = i * m + j + 1;
        }
    }
    return b;
}

vector<vector<int>> func2(vector<vector<int>>& b) {
    vector<vector<int>> c(n, vector<int>(m));
    REP(i, m) {
        REP(j, n) {
            c[(b[j][i] - 1) / m][i] = b[j][i];
        }
    }
    return c;
}

