void is_valid(int N, int M, vector< vector<int> > board) {
    auto find_id = [&](int val) {
        return (val - 1) / M;
    };

    vector<int> ids(N);
    for(int i=0; i<N; i++) {
        for(int j=0; j<M; j++) {
            int id = find_id(board[i][j]);
            assert(id == i);
            ids[id]++;
        }
    }

    for(int i=0; i<N; i++) {
        assert(ids[i] == M);
    }
}

