#include <bits/stdc++.h>
using namespace std;

template <class T> struct ford_fulkerson {
  struct edge {
    int to, rev;
    T cap;
  };
  static constexpr T inf = numeric_limits<T>::max();
  vector<vector<edge>> g;
  vector<int> vis;
  int time;
  ford_fulkerson(int n) : g(n), vis(n), time(0) {}
  void add_edge(int from, int to, T cap) {
    assert(from != to);
    assert(cap >= 0);
    if (cap == 0) return;
    g[from].push_back({to, (int)g[to].size(), cap});
    g[to].push_back({from, (int)g[from].size() - 1, 0});
  }
  T dfs(int v, int t, T f) {
    if (v == t) return f;
    vis[v] = time;
    for (auto&& e : g[v]) {
      if (vis[e.to] == time or e.cap == 0) continue;
      T d = dfs(e.to, t, min(f, e.cap));
      if (d > 0) {
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
      }
    }
    return 0;
  }
  T max_flow(int s, int t) {
    assert(s != t);
    T res = 0;
    while (true) {
      ++time;
      T f = dfs(s, t, inf);
      if (f == 0) return res;
      res += f;
    }
  }
};

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  int n, m;
  cin >> n >> m;
