using namespace std;

int n, m, A[105][105], tot, nxt[200 * 105], fst[205], cur[205], to[200 * 105], f[200 * 105], h[205];

void addedge(int u, int v, int w) {
	nxt[++tot] = fst[u]; fst[u] = tot; to[tot] = v; f[tot] = w;
	nxt[++tot] = fst[v]; fst[v] = tot; to[tot] = u; f[tot] = 0;
}
bool bfs() {
	static int q[205];
	int st = 0, ed = 0;
	for (int i = 1; i <= 2 * n + 2; ++i) cur[i] = fst[i], h[i] = -1;
	h[2 * n + 1] = 0;
	q[ed++] = 2 * n + 1;
	while (st < ed) {
		int u = q[st++];
		for (int i = fst[u]; i; i = nxt[i])
			if (f[i] > 0 && h[to[i]] == -1) {
				h[to[i]] = h[u] + 1;
				if (to[i] == 2 * n + 2) return true;
				q[ed++] = to[i];
			}
	}
	return false;
}
int dfs(int u, int fl) {
	if (u == 2 * n + 2 || !fl) return fl;
	int left = fl;
	for (int &i = cur[u], t; i; i = nxt[i])
		if (h[to[i]] == h[u] + 1 && (t = dfs(to[i], min(left, f[i]))) > 0) {
			f[i] -= t, f[i ^ 1] += t, left -= t;
			if (!left) break;
		}
	return fl - left;
}

int main() {
