			for (int k = i; k <= m; ++k)
				s[j][(A[j][k] - 1) / m + 1] = k;
			for (int k = 1; k <= n; ++k)
				if (s[j][k]) addedge(j, n + k, 1);
			addedge(n * 2 + 1, j, 1);
			addedge(n + j, n * 2 + 2, 1);
		}
		int res = 0;
		while (bfs()) res += dfs(2 * n + 1, 1 << 30);
		for (int j = 2; j <= tot; j += 2) {
			int u = to[j ^ 1], v = to[j];
			if (u >= 1 && u <= n && v > n && v <= 2 * n && !f[j])
				swap(A[u][i], A[u][s[u][v - n]]);
		}
	}
	static int B[105][105];
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
			printf("%d%c", A[i][j], " \n"[j == m]), B[j][i] = A[i][j];
	for (int i = 1; i <= m; ++i) {
