		for (int j = 1; j <= n; ++j)
			A[j][i] = B[i][j];
	}
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
			printf("%d%c", A[i][j], " \n"[j == m]);
	return 0;
}

