		int x=q[hd++];
		if(x==fin)break;
		for(int pos=p[x];pos;pos=e[pos].xt){
			if(!e[pos].rem)continue;
			int cur=e[pos].to;
			if(h[cur]<std){
				h[cur]=h[x]+1;
				q[tl++]=cur;
			}
		}
	}
	return h[fin]>std;
}
int dfs(int x,int f){
	if(x==fin)return f;
	int res=0;
	for(int &pos=g[x];pos;pos=e[pos].xt){
