		int tp=dfs(cur,min(e[pos].rem,f));
		if(tp){
			f-=tp,res+=tp;
			e[pos].rem-=tp;
			e[pos^1].rem+=tp;
		}
		if(!f){
			break;
		}
	}
	return res;
}
