int main()
{
    int N;
    cin >> N;
    int M;
    cin >> M;
    vector<vector<int>> A(N, vector<int>(M));
    cin >> A;

    REP(i, N) REP(j, M) A[i][j]--;

    vector<int> Ainv(N * M);
    REP(i, N) REP(j, M) Ainv[A[i][j]] = i;

    vector<set<int>> edges(N);

    int n_bad = 0;
    REP(i, N) REP(j, M)
    {
        int t = A[i][j] / M;
        if (t != i)
        {
            edges[i].insert(A[i][j]);
            n_bad++;
        }
    }
    // dbg(edges);

    int l_now = 0;
    vector<vector<int>> loops;
    while (l_now < N)
    {
        if (edges[l_now].size() == 0)
        {
            l_now++;
            continue;
        }

        vector<int> loop;
        int x = *edges[l_now].begin();

        vector<int> visited(N);
        loop.push_back(x);
        edges[l_now].erase(x);
        n_bad--;
        visited[x / M] = 1;

        int l = x / M;
        bool flg = true;
        while (l != l_now or flg)
        {
            flg = false;
            int xx = -1;
            for (auto nx : edges[l])
            {
                if (visited[nx / M] == 0)
                {
                    xx = nx;
                    break;
                }
            }
            edges[l].erase(xx);
            visited[xx / M] = 1;
            n_bad--;
            loop.emplace_back(xx);
            l = loop.back() / M;
        }
        reverse(ALL(loop));

        flg = true;
        FOR(i, 1, loop.size()) if (Ainv[loop[i]] == Ainv[loop[0]]) flg = false;
        if (!flg)
        {
            int x = loop.back();
            loop.pop_back();
            edges[Ainv[x]].insert(x);
            n_bad++;
            if (Ainv[x] == Ainv[loop[0]]) break;
        }
        loops.emplace_back(loop);
    }
    // dbg(loops);

    vector<vector<int>> shuffles;
    vector<bitset<100>> info;
    // sort(loops.rbegin(), loops.rend(), [](vector<int> a, vector<int> b) { return a.size() < b.size(); });

    for (auto loop : loops)
    {
        bitset<100> bs_loop;
        for (auto v : loop) bs_loop.set(v / M);
        int tgt = -1;
        REP(i, shuffles.size())
        {
            if ((info[i] & bs_loop).any()) continue;
            else
            {
                tgt = i;
                break;
            }
        }
        if (tgt >= 0)
        {
            for (auto v : loop) shuffles[tgt].emplace_back(v);
            info[tgt] = info[tgt] | bs_loop;
        }
        else
        {
            shuffles.push_back(loop);
            info.push_back(bs_loop);
        }
    }

    // if ((int)shuffles.size() > M) exit(8);

    // dbg(shuffles);
    vector<vector<int>> B, C;
    ndarray(B, N, M);
    ndarray(C, N, M);
    REP(i, N) REP(j, M) B[i][j] = C[i][j] = -1;

    REP(i, shuffles.size())
    {
        int K = shuffles[i].size();
        REP(j, K)
        {
            B[Ainv[shuffles[i][j]]][i] = shuffles[i][j];
            C[shuffles[i][j] / M][i] = shuffles[i][j];
        }
    }

    REP(i, N)
    {
        set<int> AS;
        REP(j, M) AS.insert(A[i][j]);
        REP(j, M) AS.erase(B[i][j]);
        REP(j, M)
        {
            if (B[i][j] == -1)
            {
                B[i][j] = *AS.begin();
                AS.erase(AS.begin());
            }
        }
    }

    REP(i, N) REP(j, M) if (C[i][j] == -1) C[i][j] = B[i][j];

    REP(i, N)
    {
        REP(j, M) printf("%d ", 1 + B[i][j]);
        puts("");
    }
    REP(i, N)
    {
        REP(j, M) printf("%d ", 1 + C[i][j]);
        puts("");
    }
}

#include <cstdio>
#include <algorithm>
const int N = 101;
int a[N][N];
int r[N * N]; // r[x] = row of element x
int p[N][N]; // p[x][y] = row of element y in column x

int next(int row)
{
	int col = 0;
	while (a[row][col] != -1)
		++col;
	return col;
}

int main()
{
	int n, m; scanf("%d%d", &n, &m);
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j)
		{
			int x; scanf("%d", &x);
			r[x - 1] = i;
			a[i][j] = -1;
		}

	for (int i = 0; i < n * m; ++i)
	{
		int row = r[i];
		int col1 = i % m;
		int col2 = next(row);
		int val = i / m;
		if (col1 == col2)
		{
			a[row][col1] = val;
			p[col1][val] = row;
		} 
		else 
			while (val != -1)
			{
				p[col1][val] = row;
				std::swap(val, a[row][col1]);
				a[row][col2] = val;
				if (val != -1)
					std::swap(row, p[col2][val]);
			}
	}

	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j)
		{
			int val = a[i][j] * m;
			for (int k = 0; k < m; ++k)
				if (r[val + k] == i)
				{
					a[i][j] = val + k;
					r[val + k] = -1;
					break;
				}
		}

	for (int i = 0; i < n; ++i, puts(""))
		for (int j = 0; j < m; ++j)
			printf("%d ", a[i][j] + 1);

	for (int i = 0; i < m; ++i)
		for (int j = 1; j < n; ++j)
			for (int k = 0; k < n - j; ++k)
				if (a[k][i] > a[k + 1][i])
					std::swap(a[k][i], a[k + 1][i]);

	for (int i = 0; i < n; ++i, puts(""))
		for (int j = 0; j < m; ++j)
			printf("%d ", a[i][j] + 1);
}

