void tenchi(vector <vector <int>>& vs)
{
	const int H = SZ(vs);
	const int W = SZ(vs[0]);

	vector <vector <int>> ret(W, vector <int>(H));
	for (int y = 0; y < W; y++)
	{
		for (int x = 0; x < H; x++)
		{
			ret[y][x] = vs[x][y];
		}
	}

	vs = ret;
}

