int dfs(int v, int t, int f) {
	if (v == t)return f;
	used[v] = true;
	for (int i = 0; i < (int)G[v].size(); i++) {
		edge &e = G[v][i];
		if (!used[e.to] && e.cap > 0) {

			int d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				if (e.isrev) {
					int pastid = e.id;
					vector<P> memo = keiro[pastid];
					vector<P> ad;
					per(j, (int)memo.size()) {
						if (memo[j].first == v) {
							for (int k = j; k < memo.size(); k++) {
								ad.push_back(memo[k]);
							}
							keiro[pastid].resize(j - 1);
							per(k, (int)cur.size()) {
								keiro[pastid].push_back(cur[k]);
								edge &ee = G[cur[k].first][cur[k].second];
								ee.id = pastid;
								G[ee.to][ee.rev].id = pastid;
							}

							break;
						}
					}
					cur = ad;
					rep(j, cur.size()) {
						edge &ee = G[cur[j].first][cur[j].second];
						ee.id = keiro.size();
						G[ee.to][ee.rev].id = keiro.size();
					}
				}
				else {
					cur.push_back({ v,i });
					e.id = keiro.size();
					G[e.to][e.rev].id = keiro.size();
				}
				return d;
			}
		}
	}
	return 0;
}
int max_flow(int s, int t) {
	int flow = 0;
	for (;;) {
		memset(used, 0, sizeof(used));
		cur.clear();
		int f = dfs(s, t, mod);
		reverse(cur.begin(), cur.end());
		keiro.push_back(cur);
		if (f == 0)return flow;
		flow += f;
	}
}

