        for (int i = 0; i < size; i++) level[i] = -1;
        level[s] = 0;

        std::deque<int> q { s };

        while (!q.empty()) {
            auto curr = q.front();
            q.pop_front();
            for (auto & e : g[curr]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[curr] + 1;
                    q.push_back(e.to);
                }
            }
        }
    }

    auto dfs(int v, int t, int f) {
        if (v == t) return f;

        for (unsigned i = 0; i < g[v].size(); i++) {
            iter[v] = i;
            auto &e = g[v][i];

            if (e.cap > 0 && level[v] < level[e.to]) {
                auto d = dfs(e.to, t, std::min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }

        return 0;
    }

    explicit Dinic(int s) :
        g(s),
        level(s),
        iter(s),
        size(s) {}

    void add_edge(int from, int to, int cap, int id) {
        g[from].emplace_back(to, cap, g[to].size(), id);
        g[to].emplace_back(from, 0, g[from].size() - 1, id);
    }

    auto calc(int s, int t) {
        int flow = 0;
        while (true) {
            bfs(s);
            if (level[t] < 0) return flow;

            for (auto &el : iter) el = 0;

            auto f = dfs(s, t, inf);
            while (f > 0) {
                flow += f;
                f = dfs(s, t, inf);
            }
        }
    }
};

