class Bigraph {
    const int N, M;
    vector<vector<int> > adj;
    int idl(int i) { return i; }
    int idr(int j) { return N + j; }
public:
    Bigraph(int n, int m) : N(n), M(m), adj(n+m) {}
    void add_edge(int i, int j) {
        assert(0 <= i);
        assert(i < N);
        assert(0 <= j);
        assert(j < M);
        const int iid = idl(i), jid = idr(j);
        adj[iid].push_back(jid);
        adj[jid].push_back(iid);
    }
    vector<pair<int, int> > max_matching() {
        int match[N+M];
        bool visited[N+M];
        fill(match, match+N+M, -1);
        function<bool(int)> dfs = [&](int i) {
            visited[i] = true;
            for (int j : adj[i]) {
                if (visited[j]) continue;
                visited[j] = true;
                const int k = match[j];
                if (k == -1 || dfs(k)) {
                    match[j] = i;
                    match [i] = j;
                    return true;
                }
            }
            return false;
        };
        for (;;) {
            fill(visited, visited+N+M, false);
            bool found = false;
            for (int i = 0; i < N; i++) {
                if (visited[i] || match[i] >= 0) continue;
                if (dfs(i)) { found = true; break; }
            }
            if (!found) break;
        }
        vector<pair<int, int> > result;
        for (int i = 0; i < N; i++)
            if (match[i] >= 0) result.push_back({i, match[i]-N});
        return result;
    }
};

