		Part part;
		int index;
		Vertex() = default;
		Vertex(Part part, int index);
	};

	using Edge = BipartiteGraph::Edge;

private:
	BipartiteGraph graph_m;
	std::vector<Edge> matching_m;
	std::vector<bool> marked_source_m;
	std::vector<bool> marked_sink_m;

