	: graph_m(graph) {
}

BipartiteSolver::Vertex::Vertex(Part part, int index)
	: part(part), index(index) {
}

void BipartiteSolver::Solve() {
	HopcroftKarp solver(graph_m.Source_size(), graph_m.Sink_size());
	for (const auto& edge : graph_m.Edges()) {
		solver.add_edge(edge.from, edge.to);
	}

	solver.bipartite_matching();
	auto res = solver.output();

	std::vector<Edge> matching;
	for (const auto& pair : res) {
		matching.push_back(Edge(pair.first, pair.second));
	}

	matching_m = matching;

	/*------- ここから点被覆とかの計算 -------*/
	const int M = graph_m.Source_size();
	const int N = graph_m.Sink_size();

	std::vector<std::vector<int>> source_to_sink(M);
	std::vector<std::vector<int>> sink_to_source(N);
	for (const auto& edge : matching_m) {
		int from = edge.from;
		int to = edge.to;

		sink_to_source[to].push_back(from);
	}

	/* もう少し考えよう */
	for (const auto& edge : graph_m.Edges()) {
		int from = edge.from;
		int to = edge.to;

		int destination = sink_to_source[to].empty() ? -1 : sink_to_source[to].front();
		if (from == destination) continue;
		source_to_sink[from].push_back(to);
	}

	std::vector<bool> used_source(M, false);
	std::vector<bool> used_sink(N, false);

	// (part, index)
	std::stack<Vertex> stack;
	std::vector<bool> start_source(M, true);
	for (const auto& edge : matching_m) {
		start_source[edge.from] = false;
	}

	for (int i = 0; i < start_source.size(); ++i) {
		if (start_source[i]) {
			stack.push(Vertex(Part::Source, i));
		}
	}

	while (!stack.empty()) {
		auto vertex = stack.top(); stack.pop();
		Part part = vertex.part;
		int index = vertex.index;

		if (part == Part::Source) {
			if (used_source[index]) continue;
			used_source[index] = true;

			for (int to : source_to_sink[index]) {
				stack.push(Vertex(Part::Sink, to));
			}
		}

		if (part == Part::Sink) {
			if (used_sink[index]) continue;
			used_sink[index] = true;

			for (int to : sink_to_source[index]) {
				stack.push(Vertex(Part::Source, to));
			}
		}
	}

	marked_source_m = used_source;
	marked_sink_m = used_sink;
}

std::vector<BipartiteSolver::Edge> BipartiteSolver::Maximum_matching() const {
	return matching_m;
}

std::vector<BipartiteSolver::Vertex> BipartiteSolver::Minimum_vertex_cover() const {
	std::vector<Vertex> vertices;
	for (int i = 0; i < marked_source_m.size(); ++i) {
		if (!marked_source_m[i]) {
			vertices.push_back(Vertex(Part::Source, i));
		}
	}

	for (int i = 0; i < marked_sink_m.size(); ++i) {
		if (marked_sink_m[i]) {
			vertices.push_back(Vertex(Part::Sink, i));
		}
	}
	return vertices;
}

std::vector<BipartiteSolver::Vertex> BipartiteSolver::Maximum_stable_set() const {
	std::vector<Vertex> vertices;
	for (int i = 0; i < marked_source_m.size(); ++i) {
		if (marked_source_m[i]) {
			vertices.push_back(Vertex(Part::Source, i));
		}
	}

	for (int i = 0; i < marked_sink_m.size(); ++i) {
		if (!marked_sink_m[i]) {
			vertices.push_back(Vertex(Part::Sink, i));
		}
	}
	return vertices;
}
