int S, T, tot = 1, fir[N], nxt[N * N],  to[N * N], val[N * N];

inline void addE(int u, int v, int w) {
    nxt[++tot] = fir[u], fir[u] = tot, to[tot] = v, val[tot] = w;
    nxt[++tot] = fir[v], fir[v] = tot, to[tot] = u, val[tot] = 0;
}

int dep[N], cur[N];

inline bool bfs() {
    memset(dep, -1, sizeof dep);
    memcpy(cur, fir, sizeof fir);
    queue<int> q;
    while (!q.empty()) q.pop();
    dep[S] = 1, q.push(S);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = fir[u], v; i; i = nxt[i]) {
            v = to[i];
            if (dep[v] != -1 || !val[i]) continue;
            dep[v] = dep[u] + 1, q.push(v);
        }
    } return dep[T] != -1;
}

int dfs(int u, int now) {
    if (u == T || !now) return now;
    int res = 0;
    for (int &i = cur[u], v; i && now; i = nxt[i]) {
        v = to[i];
        if (dep[v] != dep[u] + 1 || !val[i]) continue;
        int tmp = dfs(v, min(now, val[i]));
        if (!tmp) continue;
        val[i] -= tmp, val[i ^ 1] += tmp;
        now -= tmp, res += tmp;
    } return res;
}

inline int dinic() {
    int res = 0, tmp;
    while (bfs()) {
        while ((tmp = dfs(S, INF)))
            res += tmp;
    } return res;
}

inline void erase(int u, int e) {
    if (fir[u] == e) return fir[u] = nxt[e], void();
    for (int i = fir[u]; i; i = nxt[i])
        if (nxt[i] == e) return nxt[i] = nxt[e], void();
    assert(0);
}

