            q[i][col].push(a[i][j]);
        }

    for (int i = 1; i <= n; ++i)
        addE(S, i, 1), addE(i + n, T, 1);

    for (int k = 1; k <= m; ++k) {
        for (int i = fir[S]; i; i = nxt[i])
            val[i] = 1, val[i ^ 1] = 0;
        for (int i = fir[T]; i; i = nxt[i])
            val[i] = 0, val[i ^ 1] = 1;
        int tmp = dinic();
        assert(tmp == n);
        for (int u = 1; u <= n; ++u) {
            for (int i = fir[u]; i; i = nxt[i]) {
                if (val[i]) continue;
                b[u][k] = to[i] - n;
                erase(u, i), erase(to[i], i ^ 1);
                break;
            }
        }
    }

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            c[i][j] = q[i][b[i][j]].front(), q[i][b[i][j]].pop();

    write(c);

    for (int j = 1; j <= m; ++j) {
        for (int i = 1; i <= n; ++i)
            d[i] = c[i][j];
        sort(d + 1, d + n + 1);
        for (int i = 1; i <= n; ++i)
            c[i][j] = d[i];
    }

    write(c);

    return 0;
}

