  inline void init() {
    s = 0, t = n * 2 + 1, cnt = -1;
    for (ri i = s; i <= t; ++i) fst[i] = -1;
  }
  inline void addedge(int u, int v, int c) { e[++cnt] = (E) { v, c, fst[u] }, fst[u] = cnt; }
  inline void _add(int u, int v, int c) { addedge(u, v, c), addedge(v, u, 0); }
  inline bool bfs() {
    for (ri i = s; i <= t; ++i) cur[i] = fst[i], d[i] = -1;
    queue <int> q;
    d[s] = 0, q.push(s);
    while (q.size()) {
      int x = q.front();
      q.pop();
      for (ri i = fst[x]; ~i; i = e[i].nxt) if (e[i].c && d[e[i].v] == -1) {
        d[e[i].v] = d[x] + 1;
        q.push(e[i].v);
      }
    }
    return ~d[t];
  }
  inline int dfs(int x, int f) {
    if (x == t || !f) return f;
    int fl = f;
    for (ri &i = cur[x], tp, v; ~i; i = e[i].nxt) {
      if (!fl) return f;
      if (e[i].c && d[v = e[i].v] == d[x] + 1) {
        tp = dfs(v, min(fl, e[i].c));
        if (!tp) d[v] = -1;
        e[i].c -= tp, e[i ^ 1].c += tp, fl -= tp;
      } 
    }
    return f - fl;
  }
  inline void solve() {
    int tp, ss = 0;
    while (bfs()) while ((tp = dfs(s, inf)) > 0) ss += tp;
    for (ri i = 1; i <= n; ++i) for (ri j = fst[i]; ~j; j = e[j].nxt) if (!e[j].c) {
      mch[i] = e[j].v - n;
