		T[T1].U=hang[a+1],T[T2].U=hang[b+1],T[T3].U=hang[c+1];
		T[T1].D=a+1,T[T2].D=b+1,T[T3].D=c+1;
		hang[a+1]=T[a+1].U=T1,hang[b+1]=T[b+1].U=T2,hang[c+1]=T[c+1].U=T3;
		T[T[T1].R=T2].L=T1,T[T[T2].R=T3].L=T2,T[T[T3].R=T1].L=T3;
		T[T1].number=T[T2].number=T[T3].number=c;
		T[T1].position=T[T2].position=T[T3].position=a;
		T[T1].col=a+1,T[T2].col=b+1,T[T3].col=c+1;
		size[a+1]++,size[b+1]++,size[c+1]++;
	}
	void split(int now){
		T[T[now].L].R=T[now].R;
		T[T[now].R].L=T[now].L;
		for (int i=T[now].D;i!=now;i=T[i].D){
			for (int j=T[i].R;j!=i;j=T[j].R){
				T[T[j].U].D=T[j].D;
				T[T[j].D].U=T[j].U;
				size[T[j].col]--;
			}
		}
	}
	void recover(int now){
		for (int i=T[now].D;i!=now;i=T[i].D){
			for (int j=T[i].R;j!=i;j=T[j].R){
				T[T[j].U].D=j;
				T[T[j].D].U=j;
				size[T[j].col]++;
			}
		}
		T[T[now].L].R=now;
		T[T[now].R].L=now;
	}

	bool main(){
		if (T[1].R==1) return true;
		int dothis=T[1].R;
		for (int i=T[1].R;i!=1;i=T[i].R){
			if (T[i].D==i) return false;
			if (size[i]<size[dothis]) dothis=i;
		}
		split(dothis);
		for (int i=T[dothis].D;i!=dothis;i=T[i].D){
			for (int j=T[i].R;j!=i;j=T[j].R) split(T[j].col);
			B[(T[i].position-1)/m+1][(T[i].position-1)%m+1]=T[i].number-2*n*m;
			if (main()) return true;
			B[(T[i].position-1)/m+1][(T[i].position-1)%m+1]=0;
			for (int j=T[i].R;j!=i;j=T[j].R) recover(T[j].col);
		}
		recover(dothis);
		return false;
	}
}

