bool try_kuhn (int v) {
  if (used[v])  return false;
  used[v] = true;
  for (size_t i=0; i<gr[v].size(); ++i) {
    int to = gr[v][i];
    if (mt[to] == -1 || try_kuhn (mt[to])) {
      mt[to] = v;
      mt[v] = to;
      return true;
    }
  }
  return false;
}

int main() {
  std::ios::sync_with_stdio(false); std::cin.tie(0);
  int n, m;
  cin >> n >> m;
  vvi a(n, vi(m));
  vector<vvi> ra(n, vvi(n));
  for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) {
    cin >> a[i][j];
    --a[i][j];
    ra[i][a[i][j] / m].push_back(a[i][j]);
  }
  vvi b(n, vi(m));
  vvi c = b;
  for (int col = 0; col < m; ++col) {
    gr.assign(2 * n, vi());
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) if (!ra[i][j].empty()) {
        gr[i].push_back(n + j);
      }
    }
    mt.assign (gr.size(), -1);
    for (int run = 1; run;) {
      run = 0;
      used.assign(gr.size(), false);
      for (int v=0; v<n; ++v) if (mt[v] == -1 && try_kuhn(v)) {
        run = 1;
      }
    }
    for (int i = 0; i < n; ++i) {
      assert(mt[i] != -1);
      int j = mt[i] - n;
      b[i][col] = ra[i][j].back();
      ra[i][j].pop_back();
    }
  }
  for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) {
    c[b[i][j] / m][j] = b[i][j];
  }
  out(b);
  out(c);
  return 0;
}

