using namespace std;

bool used[10001];

struct Dinic{
    struct edge {
        int64_t to, cap, rev, id;
        edge(int64_t to, int64_t cap, int64_t rev, int64_t id):to(to), cap(cap), rev(rev), id(id){}
    };

    int N, S, T;
    int64_t flow = 0;
    const int64_t INF = 1e18;
    vector<int> level, iter;
    vector<vector<edge>> G;

    Dinic(int N, int S, int T):N(N), S(S), T(T){
        flow = 0;
        level.resize(N);
        iter.resize(N);
        G.resize(N);
    }

    void add_edge(int from, int to, int64_t cap, int id){
        G[from].emplace_back(to, cap, G[to].size(), id);
        G[to].emplace_back(from, 0, G[from].size()-1, -id);
    }

    void bfs(int s){
        fill(level.begin(), level.end(), -1);
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while(que.size()){
            int v = que.front(); que.pop();
            for(auto& e : G[v]){
                if(e.cap > 0 && level[e.to] < 0){
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    int64_t dfs(int v, int t, int64_t f){
        if(v == t) return f;
        for(int& i=iter[v]; i<G[v].size(); i++){
            auto& e = G[v][i];
            if(e.cap > 0 && level[v] < level[e.to]){
                int64_t d = dfs(e.to, t, min(f, e.cap));
                if(d > 0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    vector<int> matching(){
        while(true){
            bfs(S);
            if(level[T] < 0) break;
            fill(iter.begin(), iter.end(), 0);
            while(true){
                int64_t f = dfs(S, T, INF);
                if(f == 0) break;
                flow += f;
            }
        }
        cerr << flow << endl;
        vector<int> ret;
        for(int i=0; i<100; i++) for(auto& e : G[i]) if(e.id > 0 && !used[e.id] && e.cap == 0){
            used[e.id] = true;
            G[e.to][e.rev].cap = 0;
            ret.push_back(e.id);
        }
        return ret;
    }
};

int main(){
    int N, M;
    cin >> N >> M;
    int A[100][100];
    int S = 200, T = 201;
    Dinic solver(T+1, S, T);
    for(int i=0; i<N; i++) for(int j=0; j<M; j++){
        cin >> A[i][j];
        solver.add_edge(i, 100 + (A[i][j]-1)/M, 1, A[i][j]);
    }

    for(int j=0; j<M; j++){
        for(int i=0; i<N; i++){
            solver.add_edge(S, i, 1, -S);
            solver.add_edge(100+i, T, 1, -T);
        }
        auto v = solver.matching();
        for(int i=0; i<N; i++) A[j][i] = v[i];
    }
    for(int i=0; i<N; i++) for(int j=0; j<M; j++) cout << A[j][i] << " \n"[j==M-1];
    for(int j=0; j<M; j++) sort(A[j], A[j]+N);
    for(int i=0; i<N; i++) for(int j=0; j<M; j++) cout << A[j][i] << " \n"[j==M-1];
    return 0;
}

