inline void addedge(int a,int b,int c,int v)
{
	nxt[++tot]=head[a];ver[tot]=b;flow[tot]=c;num[tot]=v;head[a]=tot;
	nxt[++tot]=head[b];ver[tot]=a;flow[tot]=0;num[tot]=v;head[b]=tot;
}
int d[maxn],s,t,q[maxn],he,ta;
inline bool bfs()
{
	for(int i=1;i<=t;i++) d[i]=0;d[q[he=ta=1]=s]=1;
	while(he<=ta)
	{
		int x=q[he++];
		for(int i=head[x];i;i=nxt[i])
		{
			int y=ver[i];if(flow[i]==0||d[y]) continue;
			d[y]=d[x]+1;q[++ta]=y;if(y==t) return 1;
		}
	}
	return 0;
}
inline int dinic(int x,int Flow)
{
	if(x==t) return Flow;
	int ans=0;
	for(int i=head[x];i;i=nxt[i])
	{
		int y=ver[i];if(flow[i]==0||d[y]!=d[x]+1) continue;
		int t=dinic(y,min(flow[i],Flow));
		flow[i]-=t;Flow-=t;flow[i^1]+=t;ans+=t;
		if(!Flow) break;
	}
	return ans;
}
