bool khun(int i)
{
    //cout<<i<<" ";
    if(tused[i])return false;
    tused[i]=true;
    int j,sz=v[i].size();
    for(j=0;j<sz;j++)
    {
        int t=v[i][j];
        if(match[t]==-1||khun(match[t]))
        {
            match[t]=i;
            match[i]=t;
            return true;
        }
    }
    return false;
}

int ans[maxn][maxn];
void solve()
{
    int i,j,k;
    for(i=0;i<m;i++)
    {
        clearr();
        for(j=0;j<n;j++)
            for(k=0;k<m;k++)
                if(!used[a[j][k]])
                {
                    v[j].push_back((a[j][k]-1)/m+n);
                    v[(a[j][k]-1)/m+n].push_back(j);
                }
        memset(match,-1,sizeof(match));
        for (j=0;j<n;j++)
        {
            memset(tused,0,sizeof(tused));
            khun(j);
        }

        for(j=0;j<n;j++)
        {
            if(match[j]!=-1)
            {
                for(k=0;k<m;k++)
                {
                    if((a[j][k]-1)/m+n==match[j]&&!used[a[j][k]])
                    {
                        used[a[j][k]]=true;
                        ans[j][i]=a[j][k];
                        break;
                    }
                }
            }
        }
    }

    for(i=0;i<n;i++)
    {
        for(j=0;j<m;j++)
            cout<<ans[i][j]<<" ";
        cout<<endl;
    }
}

