using namespace std;
#define N_ 20100
#define M_ 101000
struct Edge {
	int b, e, f;
};
struct MaxFlow {
	Edge E[M_];
	vector<int>G[N_];
	int EC, flow, PV[N_], Q[N_], Level[N_], n, source, sink, INF = 1e9;
	void init(int N, int S, int T) {
		source = S, sink = T, flow = EC = 0;
		n = N;
		for (int i = 0; i <= n; i++)G[i].clear();
	}
	void Add_Edge(int a, int b, int f) {
		G[a].push_back(EC);
		G[b].push_back(EC + 1);
		E[EC++] = { a,b,f };
		E[EC++] = { b,a,0 };
	}
	int BlockFlow(int a, int f) {
		if (a == sink)return f;
		for (int &i = PV[a]; i >= 0; i--) {
			int t = G[a][i];
			if (E[t].f && Level[E[t].e] == Level[a] + 1) {
				int ff = BlockFlow(E[t].e, min(E[t].f, f));
				if (ff) {
					E[t].f -= ff;
					E[t ^ 1].f += ff;
					return ff;
				}
			}
		}
		return 0;
	}
	bool GetLevel() {
		int head = 0, tail = 0, i;
		for (i = 1; i <= n; i++)Level[i] = -1;
		Q[++tail] = source; Level[source] = 0;
		while (head < tail) {
			int x = Q[++head];
			for (auto &t : G[x]) {
				if (E[t].f && Level[E[t].e] == -1) {
					Level[E[t].e] = Level[x] + 1;
					Q[++tail] = E[t].e;
				}
			}
		}
		return Level[sink] != -1;
	}
	void Dinic() {
		int i, t;
		flow = 0;
		while (GetLevel()) {
			for (i = 1; i <= n; i++)PV[i] = G[i].size() - 1;
			while (t = BlockFlow(source, INF)) {
				flow += t;
			}
		}
	}
}G1;
int w[110][110], n, m, vis[110][110], T[110][110], R[110][110];
int main() {
	int i, j, k;
	scanf("%d%d", &n, &m);
	for (i = 1; i <= n; i++) {
		G1.init(m + m + 2, m + m + 1, m + m + 2);
		for (j = 1; j <= m; j++) {
			G1.Add_Edge(G1.source, j, 1);
			G1.Add_Edge(m + j, G1.sink, 1);
			scanf("%d", &w[i][j]);
			int t = (w[i][j] - 1) / m;
			for (k = 1; k <= m; k++) {
				if (!vis[k][t]) {
					G1.Add_Edge(j, m + k, 1);
				}
			}
		}
		G1.Dinic();
		for (j = 1; j <= m; j++) {
			for (auto &t : G1.G[j]) {
				Edge tp = G1.E[t];
				if (tp.e >= m + 1 && tp.e <= m + m && !tp.f) {
					T[i][tp.e - m] = w[i][j];
					vis[tp.e - m][(w[i][j] - 1) / m] = 1;
					break;
				}
			}
		}
	}
	for (i = 1; i <= n; i++)for (j = 1; j <= m; j++)vis[i][j] = 0;
	for (i = 1; i <= m; i++) {
		for (j = 1; j <= n; j++) {
			int Mn = 1e9, pv = 0;
			for (k = 1; k <= n; k++) {
				if (!vis[k][i] && Mn > T[k][i]) {
					Mn = T[k][i];
					pv = k;
				}
			}
			vis[pv][i] = 1;
			R[j][i] = T[pv][i];
		}
	}
	for (i = 1; i <= n; i++) {
		for (j = 1; j <= m; j++) {
			printf("%d ", T[i][j]);
		}
		puts("");
	}
	for (i = 1; i <= n; i++) {
		for (j = 1; j <= m; j++) {
			printf("%d ", R[i][j]);
		}
		puts("");
	}
}

