using namespace std;

namespace flow{
	const int MAXN = 403 , MAXM = 1e6 + 7;
	struct Edge{int end , upEd , f , c;}Ed[MAXM];
	int head[MAXN] , S , T , cntEd = 1;	queue < int > q;

	void addEd(int a , int b , int c , int d = 0){
		Ed[++cntEd].end = b;
		Ed[cntEd].upEd = head[a];
		Ed[cntEd].f = c;
		Ed[cntEd].c = d;
		head[a] = cntEd;
	}

	void addE(int a , int b , int c , int d = 0 , bool f = 0){
		addEd(a , b , c , d); addEd(b , a , c * f , -d);
	}

	int cur[MAXN] , dep[MAXN];

	bool bfs(){
		while(!q.empty()) q.pop();
		q.push(S);
		memset(dep , 0 , sizeof(dep));
		dep[S] = 1;
		while(!q.empty()){
			int t = q.front(); q.pop();
			for(int i = head[t] ; i ; i = Ed[i].upEd)
				if(Ed[i].f && !dep[Ed[i].end]){
					dep[Ed[i].end] = dep[t] + 1;
					if(Ed[i].end == T){
						memcpy(cur , head , sizeof(head));
						return 1;
					}
					q.push(Ed[i].end);
				}
		}
		return 0;
	}

	int dfs(int x , int mF){
		if(x == T)
			return mF;
		int sum = 0;
		for(int &i = cur[x] ; i ; i = Ed[i].upEd)
			if(Ed[i].f && dep[Ed[i].end] == dep[x] + 1){
				int t = dfs(Ed[i].end , min(mF - sum , Ed[i].f));
				if(t){
					Ed[i].f -= t;
					Ed[i ^ 1].f += t;
					sum += t;
					if(sum == mF)
						break;
				}
			}
		return sum;
	}

	int Dinic(int s , int t){
		int ans = 0;
		S = s; T = t;
		while(bfs())
			ans += dfs(S , INF);
		return ans;
	}

	void clear(){memset(head , 0 , sizeof(int) * (T + 1)); cntEd = 1;};
}using flow::addE;

