		for(int j = 1 ; j <= M ; ++j)
			cin >> arr[i][j];
	for(int i = 1 ; i <= M ; ++i){
		flow::clear();
		for(int j = 1 ; j <= N ; ++j){
			flow::addE(0 , j , 1);
			bool vis[103] = {};
			for(int k = i ; k <= M ; ++k)
				if(!vis[(arr[j][k] - 1) / M]){
					vis[(arr[j][k] - 1) / M] = 1;
					flow::addE(j , N + (arr[j][k] - 1) / M + 1 , 1);
				}
		}
		for(int j = 1 ; j <= N ; ++j) flow::addE(N + j , N + N + 1 , 1);
		assert(flow::Dinic(0 , N + N + 1) == N);
		for(int j = 1 ; j <= N ; ++j)
			for(int k = flow::head[j] ; k ; k = flow::Ed[k].upEd)
				if(flow::Ed[k].end > N && !flow::Ed[k].f){
					int pos = flow::Ed[k].end - N;
					for(int l = i ; l <= M ; ++l)
						if((arr[j][l] - 1) / M + 1 == pos){
