bool rematch(int now)
{
    isusedl[now]=1;
    for(int k:e[now])
        if(!isusedr[k])
        {
            isusedr[k] = 1;
            int g = matchy[k];
            if (!g || (rematch(g)))
            {
                matchx[now] = k;
                matchy[k] = now;
                return 1;
            }
        }
    return 0;
}
int getmatch()
{
    int res = 0;
    memset(matchx, 0, sizeof(matchx));
    memset(matchy, 0, sizeof(matchy));
    for (int i = 1; i <= n; i++)
    {
        if (matchx[i])
            continue;
        memset(isusedr, 0, sizeof(isusedr));
        res += rematch(i);
    }
    return res;
}
