const int N = 100 * 100 + 100;

int n, m, a[105][105]; 
int c[N], r[N], col[105], b[105];

int main() {
  scanf("%d %d", &n, &m); 
  for(int i = 1; i <= n; i++) {
    for(int j = 1; j <= m; j++) {
      scanf("%d", &a[i][j]); 
      c[a[i][j]] = j;  
      r[a[i][j]] = i; 
    }
  }
  for(int i = 1; i <= n; i++) {
    for(int j = 1; j <= m; j++) col[j] = 0; 
    for(int j = 1; j <= m; j++) {
      int id = (i - 1) * m + j;
      if(!col[c[id]]) {
        col[c[id]] = 1; 
        continue ;
      }  
      else {
        int R = r[id], C = c[id]; 
        for(int k = 1; k <= m; k++) {
          if(!col[k] && a[R][k] > id) {
            swap(a[R][k], a[R][C]); 
            c[a[R][C]] = C, c[a[R][k]] = k; 
            col[k] = 1; break ; 
          }
        }
      }
    }
  }
  for(int i = 1; i <= n; i++) {
    for(int j = 1; j <= m; j++) {
      printf("%d ", a[i][j]); 
    }
    printf("\n"); 
  }
  for(int j = 1; j <= m; j++) {
    int cnt = 0; 
    for(int i = 1; i <= n; i++) 
      b[++cnt] = a[i][j]; 
    sort(b + 1, b + cnt + 1); 
    for(int i = 1; i <= n; i++) {
      a[i][j] = b[i]; 
    }
  }
  for(int i = 1; i <= n; i++) {
    for(int j = 1; j <= m; j++) {
      printf("%d ", a[i][j]); 
    }
    printf("\n"); 
  }
  return 0; 
}

