class Kuhn {
	public:

		// Invoke clear() before this to reset all the vectors.
    void init(int _nLeft, int _nRight) {
      nLeft = _nLeft;
			nRight = _nRight;
      g.resize(nLeft);
      matchedTo.assign(nRight, -1);
    }

    void add_edge(int i, int j) {
      g[i].push_back(j);
    }

    int run() {
      int ans = 0;
      for (int v = 0; v < nLeft; ++v) {
        used.assign(nLeft, false);
        if (dfs(v))
					ans++;
      }
      return ans;
    }

    void clear() {
      g.clear();
      matchedTo.clear();
      used.clear();
    }

  vector<int> matchedTo;
	private:
		int nLeft, nRight;
    vector<vector<int> > g;

    vector<bool> used;

    bool dfs(int v) {
      if (used[v])
        return false;
      used[v] = true;
      for (int i = 0; i < (int)g[v].size(); i++) {
        int to = g[v][i];
        if (matchedTo[to] == -1 || dfs(matchedTo[to])) {
            matchedTo[to] = v;
            return true;
        }
			}
      return false;
    }
};



