                q.push(e[i].to);
            }
    }return 0;
}

int dfs(int x,int f) {
    if(x==t) return f;
    int used=0;
    for(int i=head[x];i;i=e[i].nxt)
        if(e[i].w&&dis[e[i].to]==dis[x]+e[i].w) {
            int d=dfs(e[i].to,min(f,e[i].w));
            e[i].w-=d,e[i^1].w+=d,f-=d,used+=d;
            if(!f) break;
        }
    if(!used) dis[x]=-1;
    return used;
}

int dinic() {
    int flow=0;
    while(bfs()) flow+=dfs(s,inf);
    return flow;
}

