class BipartiteMatching {
	int m, n;
	vector<int> root, pre;
	vector<vector<int>> to;

public:
	vector<int> matchL, matchR;
	BipartiteMatching(int m, int n)
			: m(m), n(n), root(vector<int>(m, -1)), pre(vector<int>(m, -1)), matchL(vector<int>(m, -1)), matchR(vector<int>(n, -1)), to(vector<vector<int>>(m)) {}
	void addedge(int from, int to) { this->to[from].emplace_back(to); }
	int solve() {
		int ret = 0;
		bool flag = true;
		while (flag) {
			flag = false;
			queue<int> q;
			for (int i = 0; i < m; i++) {
				if (matchL[i] == -1) {
					root[i] = i;
					q.push(i);
				}
			}
			while (!q.empty()) {
				int u = q.front();
				q.pop();
				if (matchL[root[u]] != -1) continue;
				for (auto v : to[u]) {
					if (matchR[v] == -1) {
						while (v != -1) {
							matchR[v] = u;
							swap(matchL[u], v);
							u = pre[u];
						}
						flag = true;
						ret++;
						break;
					}
					v = matchR[v];
					if (pre[v] != -1) continue;
					pre[v] = u;
					root[v] = root[u];
					q.push(v);
				}
			}
			if (flag) {
				fill(pre.begin(), pre.end(), -1);
				fill(root.begin(), root.end(), -1);
			}
		}
		return ret;
	}
};

