const int MAX_V = 500;
struct edge { int to, cap, rev,num; };
vector<edge>G[MAX_V];
bool used[MAX_V];

void add_edge(int from, int to, int cap,int num) {
	G[from].push_back({ to, cap, G[to].size(),num });
	G[to].push_back({ from,0,G[from].size() - 1,num });
}
int dfs(int v, int t, int f) {
	if (v == t)return f;
	used[v] = true;
	for (int i = 0; i < G[v].size(); i++) {
		edge &e = G[v][i];
		if (!used[e.to] && e.cap > 0) {
			int d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}
int max_flow(int s, int t) {
	int flow = 0;
	for (;;) {
		memset(used, 0, sizeof(used));
		int f = dfs(s, t, INF);
		if (f == 0) {
			return flow;
		}
		flow += f;
	}
}

