using namespace std;

struct MaximumFlow
{
	struct Edge
	{
		int to, cap, rev;
		Edge(int to, int cap) : to(to), cap(cap) {}
	};
	int N, src, sink;
	vector<vector<Edge>> G;
	vector<int> dist, work;
	MaximumFlow(int N, int src, int sink) : N(N), src(src), sink(sink) {
		G.resize(N);
		dist.resize(N);
		work.resize(N);
	}
	void add_edge(int f, int t, int cap) {
		G[f].emplace_back(t,cap);
		G[t].emplace_back(f,0);
		G[f].back().rev=G[t].size()-1;
		G[t].back().rev=G[f].size()-1;
	}
	void add_edge_from_source(int t, int cap) {add_edge(src,t,cap);}
	void add_edge_to_sink(int f, int cap) {add_edge(f,sink,cap);}
	int dfs(int c, int MF=0x7fffffff) {
		int flow;
		if(c==sink) return MF;
		for(int &i=work[c];i<G[c].size();i++) {
			auto &e=G[c][i];
			if(e.cap>0 && dist[e.to]==dist[c]+1 && (flow=dfs(e.to,min(e.cap,MF)))) {
				e.cap-=flow;
				G[e.to][e.rev].cap+=flow;
				return flow;
			}
		}
		return 0;
	}
	int flow() {
		int ret=0;
		queue<int> Q;
		for(;;) {
			int flow=0;
			fill(dist.begin(),dist.end(),0x7fffffff);
			dist[src]=0;
			Q.push(src);
			while(!Q.empty()) {
				int c=Q.front();
				Q.pop();
				for(auto &e: G[c]) if(e.cap>0 && dist[e.to]>dist[c]+1) {
					dist[e.to]=dist[c]+1;
					Q.push(e.to);
				}
			}
			fill(work.begin(),work.end(),0);
			while(int temp=dfs(src)) flow+=temp;
			if(flow==0) break;
			ret+=flow;
		}
		return ret;
	}
};

