struct Matching {
  vector <int> v[MAXN * 10];
  vector <int> par, bio;
  int n, m;

  void init(int _n, int _m) {
    n = _n;
    m = _m;
    bio.clear();
    par.clear();
    REP(i, 2 * max(n, m)) {
      v[i].clear();
    }
  }

  int upari(int cvor) {
    bio[cvor] = 1;

    REP(i, (int)v[cvor].size()) {
      int ncvor = v[cvor][i];
      if (par[ncvor] == -1) {par[ncvor] = cvor; return 1;}
      if (bio[par[ncvor]]) continue;
      if (upari(par[ncvor])) {par[ncvor] = cvor; return 1;}
    }
    return 0;
  }

  void edge(int a, int b) {
    v[a].pb(b + n);
    v[b + n].pb(a);
  }

  vector <int> run() {
    int sol = 0;
    par.clear();
    par.resize(2 * max(n, m), -1);
    REP(i, n) {
      bio.clear();
      bio.resize(2 * max(n, m), 0);
      sol += upari(i);
    }
    REP(i, 2 * max(n, m)) v[i].clear();
    return par;
  }
}M;

