struct edge{
    int to, cap, rev;
};

int N;
vector<int> g[502];
bool used[502];
int c[502][502];
bool nuo[502][502];
void init(){
	for(int i=0; i<N; i++){
		for(int j=0; j<N; j++){
			c[i][j]=0;
			nuo[i][j]=0;
		}
		used[i]=0;
		g[i].clear();
	}
}
void add_edge(int from, int to, int cap){
    g[from].push_back(to);
    g[to].push_back(from);
    c[from][to]+=cap;
}
int dfs(int v, int t, int f){
    if(v==t) return f;
    used[v]=1;
    for(int i=0; i<g[v].size(); i++){
        int y=g[v][i];
        if(!used[y] && c[v][y]>0){
            int d=dfs(y, t, min(f, c[v][y]));
            if(d>0){
                c[v][y]-=d;
				if(c[v][y]==0) nuo[v][y]=0;
                c[y][v]+=d;
				nuo[v][y]=1;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t){
    int flow=0;
    while(1){
        fill(used, used+N, 0);
        int f=dfs(s, t, INF);
        if(f==0) return flow;
        flow+=f;
    }
}
