typedef long long ll;
const int N = 100 + 10;
vector<int> g[N];
int vis[N],match[N];
bool dfs(int u){
    if(vis[u]) return false;
    vis[u] = 1;
    for(int v: g[u]) if(!match[v]||dfs(match[v])){
        match[v] = u;
        return true;
    }
    return false;
}
int a[N][N],b[N][N],c[N][N],ok[N][N],n,m;
int main(){
    cin>>n>>m;
    for(int i=1;i<=n;i++) for(int j=1;j<=m;j++) cin>>a[i][j], ok[i][j] = 1;
    for(int col=1;col<=m;col++){
        for(int i=1;i<=n;i++) g[i].clear();
        for(int i=1;i<=n;i++) for(int j=1;j<=m;j++) if(ok[i][j]){
            g[i].push_back((a[i][j]-1)/m+1);
        }
        memset(match,0,sizeof(match));
        for(int i=1;i<=n;i++) memset(vis,0,sizeof(vis)), dfs(i);
        for(int i=1;i<=n;i++){
            int x;
            for(int j=1;j<=n;j++) if(match[j]==i) x = j;
            for(int j=1;j<=m;j++) if(ok[i][j]){
                if((a[i][j]-1)/m+1==x){
                    b[i][col] = a[i][j];
                    ok[i][j] = 0;
                    break;
                }
            }
        }
    }
    for(int i=1;i<=n;i++) for(int j=1;j<=m;j++) c[(b[i][j]-1)/m+1][j] = b[i][j];
    for(int i=1;i<=n;i++) for(int j=1;j<=m;j++) printf("%d%c",b[i][j]," \n"[j==m]);
    for(int i=1;i<=n;i++) for(int j=1;j<=m;j++) printf("%d%c",c[i][j]," \n"[j==m]);
}

