namespace Dinic {
  struct Edge {
    int to, flow, id;
    Edge(): to(0), flow(0), id(0) {}
    Edge(int _t, int _f, int _i): to(_t), flow(_f), id(_i) {}
  };
  vector<Edge> edges;
  vector<int> G[818];
  int S, T, dep[818], cur[818];
  queue<int> que;
  void add(int u, int v, int flow, int num) {
    G[u].push_back(edges.size());
    edges.push_back(Edge(v, flow, num));
    G[v].push_back(edges.size());
    edges.push_back(Edge(u, 0, num));
  }
  bool bfs() {
    memset(dep, 0, sizeof(dep));
    while(!que.empty()) que.pop();
    dep[S] = 1, que.push(S);
    while(!que.empty()) {
      int now = que.front(); que.pop();
      int sz = G[now].size();
      for(int i = 0; i < sz; i++) {
        Edge e = edges[G[now][i]];
        if(!dep[e.to] && e.flow) {
          dep[e.to] = dep[now] + 1;
          que.push(e.to);
        }
      }
    }
    return dep[T] > 0;
  }
  int dfs(int x, int limit) {
    if(!limit || x == T) return limit;
    int res = 0, sz = G[x].size();
    for(int &i = cur[x]; i < sz && limit; i++) {
      Edge &e = edges[G[x][i]];
      if(dep[e.to] != dep[x] + 1) continue;
      int new_flow = dfs(e.to, min(e.flow, limit));
      if(!new_flow) continue;
      Edge &ie = edges[G[x][i] ^ 1];
      e.flow -= new_flow, ie.flow += new_flow;
      limit -= new_flow, res += new_flow;
    }
    return res;
  }
  int dinic() {
    int Max_flow = 0;
    while(bfs()) {
      memset(cur, 0, sizeof(cur));
      Max_flow += dfs(S, 0x3f3f3f3f);
    }
    return Max_flow;
  }
} using namespace Dinic;

