#include <bits/stdc++.h>
using namespace std;

struct BipartiteMatching{
    int n,time;
    vector<vector<int>> G;
    vector<int> match,used,dead;
    BipartiteMatching(int n):n(n),time(0),G(n),
        match(n,-1),used(n,-1),dead(n,0){}
    void add_edge(int u,int v){
        G[u].emplace_back(v);
        G[v].emplace_back(u);
    }
    int dfs(int v){
        used[v]=time;
        for (int u:G[v]){
            if (dead[u]) continue;
            int w=match[u];
            if (w<0||(used[w]<time&&dfs(w))){
                match[v]=u;
                match[u]=v;
                return 1;
            }
        }
        return 0;
    }
    int build(){
        int res=0;
        for (int v=0;v<n;++v){
            if (dead[v]) continue;
            if (match[v]<0){
                ++time;
                res+=dfs(v);
            }
        }
        return res;
    }
    vector<int> matching(){return match;}
    int disable(int v){
        int u=match[v];
        if (u>=0) match[u]=-1;
        match[v]=-1; dead[v]=1;
        ++time;
        return u>=0?dfs(u)-1:0;
    }
    int enable(int v){
        dead[v]=0;
        ++time;
        return dfs(v);
    }
};

const int MAX_N=110;

int N,M;
int A[MAX_N][MAX_N],B[MAX_N][MAX_N];

void solve1(){
    vector<vector<bool>> used(N,vector<bool>(M,false));
    for (int j=0;j<M;++j){
        BipartiteMatching BM(2*N);
        for (int i=0;i<N;++i){
            for (int jj=0;jj<M;++jj){
                if (!used[i][jj]){
                    BM.add_edge((A[i][jj]-1)/M,N+i);
                }
            }
        }
        BM.build();
        vector<int> arrange=BM.matching();
        for (int i=0;i<N;++i){
            for (int jj=0;jj<M;++jj){
                if (used[i][jj]) continue;
                if ((A[i][jj]-1)/M==arrange[N+i]){
                    used[i][jj]=true;
                    B[i][j]=A[i][jj];
                    break;
                }
            }
        }
    }
    for (int i=0;i<N;++i)
        for (int j=0;j<M;++j)
            cout << B[i][j] << (j==M-1?'\n':' ');
}

void solve2(){
    for (int j=0;j<M;++j){
        vector<int> col(N);
        for (int i=0;i<N;++i) col[i]=B[i][j];
        sort(col.begin(),col.end());
        for (int i=0;i<N;++i) A[i][j]=col[i];
    }
    for (int i=0;i<N;++i)
        for (int j=0;j<M;++j)
            cout << A[i][j] << (j==M-1?'\n':' ');
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N >> M;
    for (int i=0;i<N;++i)
        for (int j=0;j<M;++j)
            cin >> A[i][j];
    solve1(); solve2();
}

