int n,m,col[1011010],x[1010][1010];
int vis[101010],mat[101010];
vector<int> e[10101]; 
int check(int u,int tim){
    for (auto v:e[u]){
        if (tim^vis[v]){
            vis[v]=tim;  
            if (!mat[v]||check(mat[v],tim)){
                mat[v]=u;return 1;
            }
        }
    }
    return 0;
}
int num[1010][1010];
void solve(int i){
	if (i>m) return;
	for (int j=1;j<=n;j++){
		e[j].clear();
		mat[j]=vis[j]=0;
		for (int k=i;k<=m;k++){
			e[j].push_back(x[j][k]);
		}
	}
	for (int j=1;j<=n;j++) check(j,j);
	for (int j=1;j<=n;j++){
		if (mat[j]==x[j][i]) continue;
		for (int k=i;k<=m;k++){
			if (mat[j]==x[j][k]){
				swap(x[j][i],x[j][k]),swap(num[j][i],num[j][k]);break;
			}
		}
	}
	solve(i+1);
}
inline void mysort(int k){
	for (int i=1;i<=n;i++){
		for (int j=1;j<n;j++){
			if (num[j][k]>num[j+1][k]) swap(num[j][k],num[j+1][k]);
		}
	}
}
inline void print(){
	for (int i=1;i<=n;i++){
		for (int j=1;j<=m;j++){
			printf("%d ",num[i][j]);
		}
		puts("");
	}
}
