vector<int> al[2*MX_N];

struct graph {
    vector<int> al[2*MX_N];
    bool vis[2*MX_N];
    int match[2*MX_N];
    void reset() {
        FOR(i,1,2*N) al[i].clear();
    }
    int aug(int u) {
        if (vis[u]) return 0;
        vis[u] = 1;
        for (int v : al[u]) if (match[v] == -1 || aug(match[v])) {
            match[u] = v;
            match[v] = u;
            return 1;
        }
        return 0;
    }
    int mcbm() {
        memset(match,-1,sizeof match);
        int res = 0;
        FOR(i,1,N) if (match[i] == -1) {
            memset(vis,0,sizeof vis);
            res += aug(i);
        }
        return res;
    }
} g;

