struct edge { int to, cap, rev; int isrev; int bid; };
vector<edge> G[100000];
bool used[100000];
void add_edge(int from, int to, int cap) {
	G[from].push_back(edge{ to, cap, (int)G[to].size(),0,-1 });
	G[to].push_back(edge{ from, 0, (int)G[from].size() - 1,1,-1 });
}
vector<vector<P>> keiro;
bool valid[5000];
vector<P> cur;
int dfs(int v, int t, int f) {
	if (v == t)return f;
	used[v] = true;
	for (int i = 0; i < (int)G[v].size(); i++) {
		edge &e = G[v][i];
		if (e.to == sta)continue;
		if (!used[e.to] && e.cap > 0) {

			int d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				if (e.isrev) {
					int pastid = e.bid;
					vector<P> memo = keiro[pastid];
					vector<P> ad;
					per(j, (int)memo.size()) {
						if (memo[j].first == v) {
							for (int k = j; k < memo.size();k++) {
								ad.push_back(memo[k]);
							}
							keiro[pastid].resize(j - 1);
							per(k, (int)cur.size()) {
								keiro[pastid].push_back(cur[k]);
								edge &ee = G[cur[k].first][cur[k].second];
								ee.bid = pastid;
								G[ee.to][ee.rev].bid = pastid;
							}

							break;
						}
					}
					cur = ad;
					rep(j, cur.size()) {
						edge &ee = G[cur[j].first][cur[j].second];
						ee.bid = keiro.size();
						G[ee.to][ee.rev].bid = keiro.size();
					}
				}
				else {
					cur.push_back({ v,i });
					e.bid = keiro.size();
					G[e.to][e.rev].bid = keiro.size();
				}
				return d;
			}
		}
	}
	return 0;
}
int max_flow(int s, int t) {
	int flow = 0;
	for (;;) {
		memset(used, 0, sizeof(used));
		cur.clear();
		int f = dfs(s, t, mod);
		reverse(cur.begin(), cur.end());
		keiro.push_back(cur);
		if (f == 0)return flow;
		flow += f;
	}
}

