int n,m,s,now,w[M],v[M],cr[N],dis[N],nex[M],head[N];
void addedges(int x,int y,int z){
	nex[++now]=head[x],w[now]=z;
	head[x]=now,v[now]=y;
}
queue<int>que;
void add(int x,int y){
	addedges(x,y,1);
	addedges(y,x,0);
}
bool bfs(){
	for(int i=0;i<=s;i++)	cr[i]=head[i],dis[i]=0;
	que.push(s),dis[s]=1;
	while(!que.empty()){
		int x=que.front();	que.pop();
		for(int i=head[x];i;i=nex[i])
			if(w[i]&&!dis[v[i]]){
				dis[v[i]]=dis[x]+1;
				que.push(v[i]);
			}
	}
	return dis[0];
}
int dfs(int x,int f){
	int ans=0;
	if(!x||!f)	return f;
	for(int &i=cr[x];i;i=nex[i])
		if(w[i]&&dis[v[i]]==dis[x]+1){
			int d=dfs(v[i],min(f,w[i]));
			if(!d)	continue;
			ans+=d,w[i]-=d;
			w[i^1]+=d,f-=d;
			if(!f)	break;
		}
	if(!ans)	dis[x]=-1;
	return ans;
}
