int Aug(int l) {
	if (vis[l])
		return 0;
	vis[l] = 1;
	for (int j = 0; j < adjList[l].size(); j++) {
		int r = adjList[l][j];
		if (match[r] == -1 or Aug(match[r])) {
			match[r] = l;
			return 1;
		}
	}
	return 0;
}

void matching() {
	match.assign(m, -1);
	for (int l = 0; l < m; l++) {
		vis.assign(m, 0);
		int res = Aug(l);
	}
}

