            REP(k, m) {
                if(b[j][k] == -1) v.pb(k);
            }
            REP(k, m) {
                if((a[j][k] - 1) / m == i) {
                    rev[(a[j][k] - 1) % m] = j;
                    REP(l, v.size()) {
                        hk.add_edge((a[j][k] - 1) % m, v[l]);
                    }
                }
            }
        }
        hk.bipartite_matching();
        REP(j, m) {
            b[rev[j]][hk.match[j]] = i * m + j + 1;
