			int ret=dfs(y,min(Maxflow,e[p].v));
			Maxflow-=ret;flow+=ret;
			e[p].v-=ret;e[e[p].pair].v+=ret;
		}
		return flow;
	}
	int Maxflow(int s,int t){
		int ans=0;
		S=s,T=t;
		while(bfs()){
			memcpy(cur,h,sizeof(h));
			ans+=dfs(S,INT_MAX);
		}
		return ans;
	}
	void solve(){
		for(int p=h[S];p;p=e[p].next){
			int x=e[p].to;
			for(int q=h[x];q;q=e[q].next){
				int y=e[q].to;
				if(y!=S&&!e[q].v)bl[x]=y;
			}
		}
	}
}
