template <class T> struct ford_fulkerson {
  struct edge {
    int to;
    T cap;
  };
  static constexpr T inf = numeric_limits<T>::max();
  vector<edge> es;
  vector<vector<int>> g;
  vector<int> vis;
  int time;
  ford_fulkerson(int n) : g(n), vis(n), time(0) {}
  void add_edge(int from, int to, T cap) {
    assert(from != to);
    assert(cap >= 0);
    if (cap == 0) return;
    g[from].push_back(es.size()), es.push_back({to, cap});
    g[to].push_back(es.size()), es.push_back({from, 0});
  }
  T dfs(int v, int t, T f) {
    if (v == t) return f;
    vis[v] = time;
    for (int id : g[v]) {
      if (vis[es[id].to] == time or es[id].cap == 0) continue;
      T d = dfs(es[id].to, t, min(f, es[id].cap));
      if (d > 0) {
        es[id].cap -= d;
        es[id ^ 1].cap += d;
        return d;
      }
    }
    return 0;
  }
  T max_flow(int s, int t) {
    assert(s != t);
    T res = 0;
    while (true) {
      ++time;
      T f = dfs(s, t, inf);
      if (f == 0) return res;
      res += f;
    }
  }
};

