      --e;
    }
  }
  for (int c = 0; c < m; ++c) {
    int s = 2 * n, t = s + 1;
    ford_fulkerson<int> ff(t + 1);
    for (int i = 0; i < n; ++i) {
      ff.add_edge(s, i, 1);
      ff.add_edge(n + i, t, 1);
    }
    for (int i = 0; i < n; ++i) {
      vector<bool> be(n);
      for (int j = c; j < m; ++j) {
        be[a[i][j] / m] = true;
      }
      for (int x = 0; x < n; ++x) {
        if (be[x]) {
          ff.add_edge(i, n + x, 1);
        }
      }
    }
    int f = ff.max_flow(s, t);
