template<int n>
struct BG {
    vector<int> adj[n];
    bool vis[n];
    int match[n];

    void clear() {
        for (int u = 0; u < n; ++u) {
            adj[u].clear();
        }
    }

    void add_edge(int x, int y) {
        adj[x].push_back(y);
    }

    bool dfs(int x) {
        for (auto y : adj[x]) {
            if (vis[y]) continue;
            vis[y] = true;
            if (!~match[y] || dfs(match[y])) {
                match[y] = x;
                return true;
            }
        }
        return false;
    }

    int max_match() {
        int cnt = 0;
        for (int u = 0; u < n; ++u) match[u] = -1;
        for (int u = 0; u < n; ++u) {
            for (int v = 0; v < n; ++v) vis[v] = false;
            cnt += dfs(u);
        }
    }
};

