    }
    rep(i, M) {
        rep(j, N) {
            for (int k = j + 1; k < N; k++) {
                if (A[j][i] > A[k][i]) { swap(A[j][i], A[k][i]); }
            }
        }
    }
    rep(i, N) {
        rep(j, M) { cout << A[i][j] + 1 << " "; }
        cout << endl;
    }
}

