bool make_ans(int n, int m, vector<int> &used) {
	if (n == N) return true;

	bool can_change = false;
	for (int i = 0; i < N; ++i) {
		if (used[i] == 1) continue;

		auto it = mat[n].lower_bound(M*i+1);
		if (it == mat[n].end()) continue;
		if ((*it-1)/M > i) continue;
		int num = *it;
		mat[n].erase(num);
		used[i] = 1;
		if (make_ans(n+1, m, used) == true) {
			ans[n][m] = num;
			can_change = true;
			break;
		} else {
			mat[n].insert(num);
			used[i] = 0;
		}
	}

	return can_change;
}

