int getcl(int v) {
	return v / m;
}

vi e[MAX];

void buildg(int c) {
	fi(0, MAX - 1) e[i].clear();
	fi(0, n - 1) {
		vi v;
		fj(c, m - 1) {
			v.pb(getcl(a[i][j]));
		}
		sort(v.begin(), v.end());
		v.resize(unique(v.begin(), v.end()) - v.begin());
		for (int z : v) e[i].pb(z);
	}
}

int C;
int u[MAX];
int mt[MAX];
int f[MAX];

bool dfs(int x) {
	u[x] = C;
	for (int y : e[x]) {
		if (mt[y] == -1) {
			mt[y] = x;
			return true;
		}
	}
	for (int y : e[x]) {
		if (u[mt[y]] != C && dfs(mt[y])) {
			mt[y] = x;
			return true;
		}
	}
	return false;
}

void findmatching() {
	memset(mt, -1, sizeof(mt));
	memset(f, 0, sizeof(f));
	fi(0, n - 1) {
		for (int z : e[i]) {
			if (mt[z] == -1) {
				f[i] = 1;
				mt[z] = i;
				break;
			}
		}
	}
	fi(0, n - 1) {		
		if (f[i] == 0) {
			C++;
			dfs(i);
		}
	}		
	/*
	fi(0, n - 1) err("i = %d mt = %d\n", i, mt[i]);
