}

void refresh(int c) {
	fi(0, n - 1) {
		int r = mt[i];
		assert(r != -1);
		bool f = false;
		fj(c, m - 1) {
			if (getcl(a[r][j]) == i) {
				f = true;
				swap(a[r][j], a[r][c]);
				break;
			}
		}
		assert(f);
	}
}

