	fi(0, m - 1) {
		fj(0, n - 1) {
			fo(j + 1, n - 1) {
				if (a[o][i] < a[j][i]) {
					swap(a[o][i], a[j][i]);
					assert(getcl(a[o][i]) != getcl(a[j][i]));
				}
			}
		}
	}
}

