int Rr,Cc,Ps,Pt,Emat[N+3][N+3],Edep[N*3],Eans[N+3][N+3];
bool Bb[N+3][N+3];
vector<int> Vec[N+3];

struct GGRAPH{
	struct GNODE{
		int to,cap,Vx,Vy;
		GNODE *nxt,*rev;
	}Gnod[N*N];
	GNODE *Gtop[N*3],*Gcnt;
	void Init(int Nn){
		Gcnt=Gnod;
		fill(Gtop,Gtop+1+Nn,Gcnt);
	}
	void AddEdge(int u,int v,int ca1,int ca2,int Vx,int Vy){
		GNODE *p=++Gcnt,*q=++Gcnt;
		*p=(GNODE){v,ca1,Vx,Vy,Gtop[u],q};Gtop[u]=p;
		*q=(GNODE){u,ca2,Vx,Vy,Gtop[v],p};Gtop[v]=q;
	}
}Gflw;

GGRAPH::GNODE *Cop[N*3];

int Aug(int u,int flwin){
	if(u==Pt) return flwin;
	int flwout=0;
	for(auto &it=Cop[u];it;it=it->nxt){
		int v=it->to;
		if(!it->cap || Edep[v]!=Edep[u]+1) continue;
		int flwv=min(flwin-flwout,it->cap);
		flwv=Aug(v,flwv);
		flwout+=flwv;
		it->cap-=flwv;
		it->rev->cap+=flwv;
		if(flwout==flwin) break;
	}
	return flwout;
}
bool BFS(){
	for(int i=1;i<=Rr*2+2;i++)
		Cop[i]=Gflw.Gtop[i],Edep[i]=inf;
	queue<int> que;
	Edep[Ps]=0;
	que.push(Ps);
	while(!que.empty()){
		int u=que.front();que.pop();
		for(auto it=Cop[u];it;it=it->nxt){
			int v=it->to;
			if(!it->cap || Edep[v]!=inf) continue;
			Edep[v]=Edep[u]+1;
			if(v==Pt) return true;
			que.push(v);
		}
	}
	return false;
}
int Dinic(){
	int mxflw=0;
	while(BFS()) mxflw+=Aug(Ps,inf);
	return mxflw;
}
