struct HopcroftKarp {
  vector<int> match;

  HopcroftKarp(int left, int right) : left(left), graph(left), match(left + right, -1), level(left) {}

  void add_edge(int u, int v) { graph[u].emplace_back(left + v); }

  int solve() {
    int res = 0;
    while (true) {
      bfs();
      int tmp = 0;
      REP(i, left) {
        if (match[i] == -1 && dfs(i)) ++tmp;
      }
      if (tmp == 0) return res;
      res += tmp;
    }
  }

private:
  int left;
  vector<vector<int> > graph;
  vector<int> level;

  void bfs() {
    fill(ALL(level), -1);
    queue<int> que;
    REP(i, left) {
      if (match[i] == -1) {
        que.emplace(i);
        level[i] = 0;
      }
    }
    while (!que.empty()) {
      int ver = que.front(); que.pop();
      for (int e : graph[ver]) if (match[e] != -1 && level[match[e]] == -1) {
        level[match[e]] = level[ver] + 1;
        que.emplace(match[e]);
      }
    }
  }

  bool dfs(int ver) {
    for (int e : graph[ver]) {
      int tmp = match[e];
      if (tmp == -1 || (level[tmp] == level[ver] + 1 && dfs(tmp))) {
        match[e] = ver;
        match[ver] = e;
        return true;
      }
    }
    return false;
  }
};

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int n, m; cin >> n >> m;
  vector<vector<int> > a(n, vector<int>(m)); REP(i, n) REP(j, m) cin >> a[i][j];
  vector<vector<vector<int> > > type(n, vector<vector<int> >(n));
  REP(i, n) REP(j, m) type[i][(a[i][j] + m - 1) / m - 1].emplace_back(a[i][j]);
  REP(j, m) {
    HopcroftKarp hk(n, n);
    REP(x, n) REP(y, n) {
      if (type[x][y].size() > 0) hk.add_edge(x, y);
    }
    hk.solve();
    REP(i, n) {
      int match = hk.match[i] - n;
      a[i][j] = type[i][match].back();
      type[i][match].pop_back();
    }
  }
  REP(i, n) {
    REP(j, m) cout << a[i][j] << (j == m - 1 ? '\n' : ' ');
  }
  vector<vector<int> > s(m);
  REP(i, n) REP(j, m) s[j].emplace_back(a[i][j]);
  REP(j, m) {
    sort(ALL(s[j]));
    REP(i, n) a[i][j] = s[j][i];
  }
  REP(i, n) {
    REP(j, m) cout << a[i][j] << (j == m - 1 ? '\n' : ' ');
  }
  return 0;
}

