int find(int u)
{
    for (int i=0;i<(int)e[u].size();i++)
    {
        int v=e[u][i];
        if (!vis[v])
        {
            vis[v]=true;
            if (l[v]==0||find(l[v]))
            {
                l[v]=u;
                return true;
            }
        }
    }
    return false;
}
int hungary()
{
    int ans=0;
    memset(l,0,sizeof(l));
    for (int i=n+1;i<=2*n;i++)
    {
        memset(vis,false,sizeof(vis));
        if (find(i)) ++ans;
    }
    return ans;
}
