V<int> bipartite_edge_coloring(int N, V<pair<int,int>> es){
	using P = pair<int,int>;
	int M = es.size();
	int D = 0;
	{
		V<int> d(N);
		for(P e:es) d[e.fs]++,d[e.sc]++;
		rep(i,N) chmax(D,d[i]);
	}
	VV<int> vc2e(N,V<int>(D,-1));
	V<int> col(M,-1);
	auto color = [&](int e,int c){
		int x = es[e].fs, y = es[e].sc;
		if(col[e] != -1){
			vc2e[x][col[e]] = -1;
			vc2e[y][col[e]] = -1;
		}
		col[e] = c;
		vc2e[x][c] = e, vc2e[y][c] = e;
	};
	V<int> buf(M);
	rep(t,M){
		int x = es[t].fs, y = es[t].sc;
		int c0 = 0, c1 = 0;
		while(vc2e[x][c0] != -1) c0++;
		while(vc2e[y][c1] != -1) c1++;
		if(c0 == c1){
			color(t,c0);
			continue;
		}
		int v = x, c = c1, I = 0;
		while(vc2e[v][c] != -1){
			int e = vc2e[v][c];
			v ^= es[e].fs^es[e].sc;
			c ^= c0^c1;
			buf[I++] = e;
		}
		v = x;
		rep(i,I){
			int e = buf[i];
			col[e] ^= c0^c1;
			swap(vc2e[v][c0],vc2e[v][c1]);
			v ^= es[e].fs^es[e].sc;
		}
		swap(vc2e[v][c0],vc2e[v][c1]);
		color(t,c1);
	}
	return col;
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);		//DON'T USE scanf/printf/puts !!
	cout << fixed << setprecision(20);

	int H,W; cin >> H >> W;
	VV<int> A(H,V<int>(W));
	rep(i,H) rep(j,W) cin >> A[i][j],A[i][j]--;

	using P = pair<int,int>;
	V<P> es;
	V<P> v2xy(H*W);
	rep(i,H) rep(j,W) v2xy[A[i][j]] = P(i,j);
	rep(i,H*W){
		int x,y;tie(x,y) = v2xy[i];
		es.pb(x,H+i/W);
	}
	auto col = bipartite_edge_coloring(H+H,es);
	VV<int> B(H,V<int>(W,-1));
	rep(v,H*W){
		int x,y;tie(x,y) = v2xy[v];
		B[x][col[v]] = v;
	}
	VV<int> C(H,V<int>(W,-1));
	rep(w,W){
		V<int> v(H);
		rep(i,H) v[i] = B[i][w];
		sort(all(v));
		rep(i,H) C[i][w] = v[i];
	}
	rep(i,H){
		rep(j,W) cout << B[i][j] + 1 <<" ";
		cout << endl;
	}
	rep(i,H){
		rep(j,W) cout << C[i][j] + 1 <<" ";
		cout << endl;
	}
}

