vector<vector<i64>> G;
vector<i64> want;
vector<i64> res;

bool END = false;
void dfs(i64 v, vector<i64>& ans, i64 f = -1) {
  if(f == -1) f = v;
  for(auto n: G[v]) {
    if(END) return;
    i64 w = want[n];
    if(w == f) {
      ans[v] = n;
      want[n] = -1;
      END = true;
      return;
    }
    if(w == -1 || ans[w] != -1) continue;
    ans[v] = n;
    dfs(w, ans, f);
    if(END) want[n] = -1;
  }
}

