vector<vector<i64>> G;
vector<i64> want;
vector<i64> res;

bool END = false;
void dfs(i64 v, vector<i64>& ans, i64 f = -1) {
  if(f == -1) f = v;
  for(auto n: G[v]) {
    if(END) return;
    i64 w = want[n];
    if(w == f) {
      ans[v] = n;
      want[n] = -1;
      END = true;
      return;
    }
    if(w == -1 || ans[w] != -1) continue;
    ans[v] = n;
    dfs(w, ans, f);
    if(END) want[n] = -1;
  }
}

int main() {
  i64 N, M;
  cin >> N >> M;
  vector<vector<i64>> A(N, vector<i64>(M));
  vector<i64> Nn(N * M);
  rep(i,0,N) {
    rep(j, 0, M) {
      cin >> A[i][j];
      A[i][j]--;
      Nn[A[i][j]] = i;
    }
  }
  G.resize(N);
  want.resize(N * M, -1);
  vector<vector<i64>> md(N);

  rep(i,0,N){
    rep(j,0,M)
    {
      i64 n = A[i][j];
      i64 a = A[i][j] / M;
      if(a == i) {
        md[i].push_back(n);
        continue;
      }
      want[n] = a;
      G[i].push_back(n);
    }
  }

  vector<vector<i64>> ans(N, vector<i64>(M, -1));
  i64 ai = 0;

  rep(i,0,N) rep(j,0,N) {
    i64 n = M * i + j;
    if(want[n] != -1) {
      vector<i64> res(N, -1);
      END = false;
      dfs(i, res);
      rep(k,0,N) {
        if(res[k] != -1) {
          ans[Nn[res[k]]][ai] = res[k];
        }
      }
      ai++;
    }
  }

  rep(i,0,N) {
    rep(j,0,M) {
      if(ans[i][j] == -1) {
        if(md[i].empty()) {
          ans[i][j] = 0;
          continue;
        }
        ans[i][j] = md[i].back();
        md[i].pop_back();
      }
    }
  }

  rep(i,0,N) rep(j,0,M) cout << ans[i][j] + 1 << " \n"[j + 1 == M];

  rep(i,0,M) {
    vector<i64> tmp(N);
    rep(j,0,N) tmp[j] = ans[j][i];
    sort(all(tmp));
    rep(j,0,N) ans[j][i] = tmp[j];
  }

  rep(i,0,N) rep(j,0,M) cout << ans[i][j] + 1 << " \n"[j + 1 == M];
}

