struct Turbo {
    int n, value = 0;

    vector <vector<int>> G;
    vector <int> mate;
    vector <bool> vis;

    Turbo(int n): n(n), G(n), mate(n, -1), vis(n, 0) {}

    void addEdge(int u, int v) {
        G[u].push_back(v);
        G[v].push_back(u);
    }

    bool findPath(int v) {
        if (vis[v]) return false;
        vis[v] = true;

        for (int u : G[v]) if (mate[u] == -1 || findPath(mate[u])) {
            mate[v] = u;
            mate[u] = v;
            return true;
        }

        return false;
    }

    pair <int,vector<int>> runMatching() {
        while (true) {
            bool found = false;
            fill(vis.begin(), vis.end(), false);

            for (int v = 0; v < n; v++) if (mate[v] == -1 && findPath(v)) {
                found = true;
                value++;
            }

            if (!found) break;
        }

        return {value, mate};
    }
};

void makeStepOne(int n, int m, VVI &tab) {
    VVI tabRes(n, VI(m, -1));

    vector <set<int>> inRow(n);
    FOR(i,0,n-1) FOR(j,0,m-1) {
        inRow[i].insert(tab[i][j]);
    }

    FOR(j,0,m-1) {
        Turbo matching(2 * n);

        FOR(i1,0,n-1) for (int val : inRow[i1]) {
            int i2 = (val - 1) / m;
            assert(i2 >= 0 && i2 < n);

            matching.addEdge(i1, n + i2);
        }

        int value; VI mate;
        tie(value, mate) = matching.runMatching();

        assert(value == n);

        FOR(i,0,n-1) {
            auto it = inRow[i].begin();
            while (it != inRow[i].end() && (*it - 1) / m != mate[i] - n) {
                it++;
            }

            assert(it != inRow[i].end());

            tabRes[i][j] = *it;
            inRow[i].erase(it);
        }
    }

    tab = tabRes;
}

void makeStepTwo(int n, int m, VVI &tab) {
    FOR(j,0,m-1) {
        VI values(n);
        FOR(i,0,n-1) {
            values[i] = tab[i][j];
        }

        sort(values.begin(), values.end());

        FOR(i,0,n-1) {
            tab[i][j] = values[i];
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;

    VVI tab(n, VI(m));
    FOR(i,0,n-1) FOR(j,0,m-1) {
        cin >> tab[i][j];
    }

    makeStepOne(n, m, tab);

    FOR(i,0,n-1) FOR(j,0,m-1) {
        cout << tab[i][j] << " \n"[j == m-1];
    }

    makeStepTwo(n, m, tab);

    FOR(i,0,n-1) FOR(j,0,m-1) {
        cout << tab[i][j] << " \n"[j == m-1];
    }

    return 0;
}

