#define sz(v) ((int)(v).size())
#define all(v) (v).begin(), (v).end()
const int MAXN = 105;
const int MAXM = 10005;

struct edge_color{
	int n, m;
	int deg[2][MAXN];
	pi has[2][MAXN][MAXN];
	int color[MAXM];
	int c[2];

	void dfs(int x, int p) {
		auto i = has[p][x][c[!p]];
		if (has[!p][i.first][c[p]].second) dfs(i.first,!p);
		else has[!p][i.first][c[!p]] = pi(0,0);
		has[p][x][c[p]] = i;
		has[!p][i.first][c[p]] = pi(x,i.second);
		color[i.second] = c[p];
	}

	int solve(vector<pi> v, vector<int> &cv){
		m = sz(v);
		int ans = 0;
		for (int i=1;i<=m;i++) {
			int x[2];
			x[0] = v[i-1].first;
			x[1] = v[i-1].second;
			for (int d=0;d<2;d++) {
				deg[d][x[d]]+=1;
				ans = max(ans,deg[d][x[d]]);
				for (c[d]=1;has[d][x[d]][c[d]].second;c[d]++);
			}
			if (c[0]!=c[1]) dfs(x[1],1);
			for (int d=0;d<2;d++) has[d][x[d]][c[0]] = pi(x[!d],i);
			color[i] = c[0];
		}
		cv.resize(m);
		for(int i=1; i<=m; i++) cv[i-1] = color[i];
		return ans;
	}
}EC;

int n, m, a[MAXN][MAXN], b[MAXN][MAXN], idx[MAXN*MAXN];

int main(){
	auto print_grid = [&](int v[MAXN][MAXN]){
		for(int i=0; i<n; i++){
			for(int j=0; j<m; j++){
				printf("%d ", v[i][j]);
			}
			puts("");
		}
	};
	scanf("%d %d",&n,&m);
	for(int i=0; i<n; i++){
		for(int j=0; j<m; j++){
			scanf("%d",&a[i][j]);
		}
	}
	vector<pi> v;
	for(int i=0; i<n; i++){
		for(int j=0; j<m; j++){
			int col = (a[i][j] - 1) / m;
			idx[a[i][j]] = sz(v);
			v.emplace_back(i+1, col+1);
		}
	}
	vector<int> color;
	assert(EC.solve(v, color) == m);
	for(int i=1; i<=n*m; i++){
		int iv = idx[i];
		b[v[iv].first-1][color[iv] - 1] = i;
	}
	print_grid(b);
	for(int i=0; i<m; i++){
		vector<int> v;
		for(int j=0; j<n; j++) v.push_back(b[j][i]);
		sort(all(v));
		for(int j=0; j<n; j++) b[j][i] = v[j];
	}
	print_grid(b);
}

