int dfs(int node) {

	if(node==sink) return 1;

	vis[node]=1;

	for(int i:v[node]) {

		if(!vis[e[i].go] && e[i].cap && dfs(e[i].go)) {

			e[i].cap=0;
			e[i^1].cap=1;

			return 1;

		}

	}

	return 0;

}

