		scanf("%d", &a[i][j]);
		--a[i][j];
	}
	return true;
}

vector<int> g[N * N];
int clr[N * N];

void dfs(int v){
	vector<int> clrs;
	for (auto u : g[v]) if (clr[u] != -1)
		clrs.pb(clr[u]);
	sort(all(clrs));
	clrs.resize(unique(all(clrs)) - clrs.begin());
	forn(i, sz(clrs)) if (clrs[i] != i){
		clr[v] = i;
		break;
	}
	if (clr[v] == -1){
		clr[v] = sz(clrs);
	}
	assert(clr[v] < m);
}

int b[N][N], c[N][N];

void solve(){
	memset(clr, -1, sizeof(clr));
	forn(i, n * m) g[i].clear();

	forn(i, n) forn(j, m) forn(k, m) if (k != j){
		g[a[i][j]].pb(a[i][k]);
		g[i * m + j].pb(i * m + k);
	}

	vector<int> ord(n * m);
	iota(all(ord), 0);
	sort(all(ord), [](int a, int b){
		return sz(g[a]) > sz(g[b]);
	});

	for (auto v : ord) dfs(v);

	forn(i, n) forn(j, m)
		b[i][clr[a[i][j]]] = a[i][j];

	forn(j, m){
		vector<int> nums;
		forn(i, n)
			nums.pb(b[i][j]);
		sort(all(nums));
		forn(i, n)
			c[i][j] = nums[i];
	}

	forn(i, n){
		forn(j, m)
			printf("%d ", b[i][j] + 1);
		puts("");
	}

	forn(i, n){
		forn(j, m)
			printf("%d ", c[i][j] + 1);
		puts("");
	}
}

