struct Kek {
    Kek(ll n, const vvl& g) : n(n), k(n), g(g) {
        mt.assign (k, -1);
        for (int v=0; v<n; ++v) {
            used.assign (n, false);
            try_kuhn (v);
        }
    }

    vector<pll> get() {
        vector<pll> ans;
        for (int i=0; i<k; ++i) {
            if (mt[i] != -1) ans.emplace_back(mt[i], i);
        }
        assert(ans.size() == n);
        return ans;
    }

    bool try_kuhn (int v) {
        if (used[v])  return false;
        used[v] = true;
        for (size_t i=0; i<g[v].size(); ++i) {
            int to = g[v][i];
            if (mt[to] == -1 || try_kuhn (mt[to])) {
                mt[to] = v;
                return true;
            }
        }
        return false;
    }

    int n, k;
    vvl g;
    vector<int> mt;
    vector<char> used;
};

