struct edge { int to, cap, rev, id; };

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vector<int> level, iter;
    int max_id = -1; 

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
        level = vector<int>(N);
        iter = vector<int>(N);
    }

    //実際の流量を求めたい辺には0以上のidを与える　逆辺のcapを用いる
    void add_Directed_edge(int from, int to, int cap, int id = -1){
        G[from].push_back((edge){to, cap, (int)G[to].size(), -1});
        G[to].push_back((edge){from, 0, (int)G[from].size() - 1, id});
        if(id > max_id) max_id = id; 
    }

    void bfs(int s){
        memset(&level[0], -1, sizeof(level[0]) * level.size());
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while(!que.empty()){
            int v = que.front(); que.pop();
            REP(i, G[v].size()){
                edge &e = G[v][i];
                if(e.cap > 0 && level[e.to] < 0){
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    int dfs(int v, int t, int f){
        if(v == t) return f;
        for(int &i = iter[v]; i < G[v].size(); i++){
            edge &e = G[v][i];
            if(e.cap > 0 && level[v] < level[e.to]){
                int d = dfs(e.to, t, min(f, e.cap));
                if(d > 0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int max_flow(int s, int t){
        int flow = 0;
        for(;;){
            bfs(s);
            if(level[t] < 0) return flow;
            memset(&iter[0], 0, sizeof(iter[0]) * iter.size());
            int f;
            while((f = dfs(s, t, INF)) > 0) flow += f;
        }
    }

    //実際の流量を求める、max_frow(s, t)を使ってから
    vector<int> calc_flow(){
        vector<int> flow(max_id + 1, -1);
        REP(v, N) for(auto e: G[v]) if(e.id >= 0) flow[e.id] = e.cap;
        return flow;
    }

};




