void solve_col(int c) {

	for(int i=1;i<=n;i++) last[i]=0,ok[i]=0;

	for(int i=1;i<=n;i++) {

		for(int j=c;j<=m;j++) {

			last[id(a[i][j])]=i;

		}

	}

	for(int i=1;i<=n;i++) {

		int cd=-1;
		int col=-1;

		for(int j=c;j<=m;j++) {

			if(ok[id(a[i][j])]) continue ;

			if(cd==-1) {

				cd=a[i][j];
				col=j;

			}
			else if(last[id(a[i][j])]<last[id(cd)]) {

				cd=a[i][j];
				col=j;

			}

		}

		assert(cd!=-1);

		swap(a[i][c],a[i][col]);

		ok[id(a[i][c])]=1;

	}

}

void solve_rows() {

	for(int i=1;i<=m;i++) {

		solve_col(i);

	}

	print();

}

