using namespace std;
struct hopcroft{
	vector<int> dist, pair_l, pair_r;
	vector<bool> seen;
	vector<vector<int>> to;
	int n1, n2;
	hopcroft(int n1, int n2) : n1(n1), n2(n2){
		to.resize(n1);
		pair_l.assign(n1, -1);
		pair_r.assign(n2, -1);
		dist.resize(n1);
		seen.resize(n1);
	}
	void add_edge(int u, int v){
		to[u].push_back(v);
	}
	bool bfs(){
		fill(dist.begin(), dist.end(), -1);
		queue<int> q;
		for (int i = 0; i < n1; i++){
			if (pair_l[i] == -1){
				dist[i] = 0;
				q.push(i);
			}
		}
		bool reach_minus = false;
		while (!q.empty()){
			int u = q.front();
			q.pop();
			for (int adj : to[u]){
				int radj = pair_r[adj];
				if (radj == -1){
					reach_minus = true;
				} else if (dist[radj] == -1){
					dist[radj] = dist[u] + 1;
					q.push(radj);
				}
			}
		}
		return reach_minus;
	}
	bool dfs(int u){
		seen[u] = true;
		for (int adj : to[u]){
			int radj = pair_r[adj];
			if (radj == -1 || (!seen[radj] && dfs(radj))){
				pair_l[u] = adj;
				pair_r[adj] = u;
				return true;
			}
		}
		return false;
	}
	int max_matching(){
		int res = 0;
		while (bfs()){
			fill(seen.begin(), seen.end(), false);
			for (int i = 0; i < n1; i++)
				if (pair_l[i] == -1 && dfs(i))
					res++;
		}
		return res;
	}
};
const int maxn = 111;
int g[maxn][maxn];
int cnt[maxn][maxn];
int res[maxn][maxn];
vector<int> ready[maxn][maxn];
int main(){
	int n, m; cin >> n >> m;
	for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) cin >> g[i][j];
	for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) g[i][j]--;
	for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) cnt[i][g[i][j] / m]++;
	for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) ready[i][g[i][j] / m].push_back(g[i][j]);
	for(int i = 0; i < m; i++){
		int nds = 0;
		hopcroft ho(n, n);
		for(int j = 0; j < n; j++){
			for(int k = 0; k < n; k++){
				if(cnt[j][k]){
					ho.add_edge(j, k);
				}
			}
		}
		assert(ho.max_matching() == n);
		for(int j = 0; j < n; j++){
			int val = ho.pair_l[j];
			res[j][i] = ready[j][val].back();
			ready[j][val].pop_back();
			cnt[j][val]--;
		}
	}
	for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) printf("%d%c", res[i][j] + 1, " \n"[j + 1 == m]);
	for(int i = 0; i < m; i++){
		vector<int> tmp;
		for(int j = 0; j < n; j++) tmp.push_back(res[j][i]);
		sort(tmp.begin(), tmp.end());
		for(int j = 0; j < n; j++) res[j][i] = tmp[j];
	}
	for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) printf("%d%c", res[i][j] + 1, " \n"[j + 1 == m]);
	return 0;
}

