void step1(matrix& a) {
  int n = a.size();
  int m = a[0].size();
  for (auto& ai: a) std::sort(ai.rbegin(), ai.rend());
  matrix b(n, std::vector<int>(m));
  std::vector<size_t> c(n);
  for (int i = 0; i < n*m; i += m) {
    std::vector<std::vector<int>> vs(n);
    for (size_t j = 0; j < a.size(); ++j) {
      while (!a[j].empty() && a[j].back() <= i+m) {
        vs[j].push_back(a[j].back());
        a[j].pop_back();
      }
    }
    for (size_t j = 0; j < size_t(m); ++j) {
      size_t mi = -1;
      size_t mv = -1;
      for (size_t k = 0; k < size_t(n); ++k) {
        if (vs[k].empty() || b[k][j] != 0) continue;
        if (c[k] <= mv) {
          mi = k;
          mv = c[k];
        }
      }
      --c[mi];
      b[mi][j] = vs[mi].back();
      vs[mi].pop_back();
    }
  }
  a = std::move(b);

  print(a);
}

