struct GGRAPH{
	struct GNODE{
		int to,cap,Vx,Vy;
		GNODE *nxt,*rev;
	}Gnod[(N*N+N*2)*3];
	GNODE *Gtop[N*3],*Gcnt;
	void Init(int Nn){
		Gcnt=Gnod;
		fill(Gtop,Gtop+1+Nn,Gcnt);
	}
	void AddEdge(int u,int v,int ca1,int ca2,int Vx,int Vy){
		GNODE *p=++Gcnt,*q=++Gcnt;
		*p=(GNODE){v,ca1,Vx,Vy,Gtop[u],q};Gtop[u]=p;
		*q=(GNODE){u,ca2,Vx,Vy,Gtop[v],p};Gtop[v]=q;
	}
}Gflw;

GGRAPH::GNODE *Cop[N*3];

int Aug(int u,int flwin){
	if(u==Pt) return flwin;
	int flwout=0;
	for(auto &it=Cop[u];it;it=it->nxt){
		int v=it->to;
		if(!it->cap || Edep[v]!=Edep[u]+1) continue;
		int flwv=min(flwin-flwout,it->cap);
		flwv=Aug(v,flwv);
		flwout+=flwv;
		it->cap-=flwv;
		it->rev->cap+=flwv;
		if(flwout==flwin) break;
	}
	return flwout;
}
bool BFS(){
	for(int i=1;i<=Rr*2+2;i++)
		Cop[i]=Gflw.Gtop[i],Edep[i]=inf;
