	int s,t,head[maxn],cur[maxn],cnt,q[maxn],rk[maxn];
	struct gg{
		int u,v,w,next;
	}side[maxn*2];
	Flow(){s=maxn-3,t=maxn-2,cnt=1;}
	void reset(){
		cnt=1;memset(head,0,sizeof(head));	
	}
	void ins(int u,int v){
		side[++cnt]=(gg){u,v,1,head[u]};head[u]=cnt;
		side[++cnt]=(gg){v,u,0,head[v]};head[v]=cnt;
	}
	bool bfs(){
		memset(rk,0,sizeof(rk));int hd=1,tl=1;q[tl]=s;rk[s]=1;
		while(hd<=tl){
			int u=q[hd++];
			for(int i=head[u];i;i=side[i].next){
				int v=side[i].v;if(rk[v]||!side[i].w)continue;
				rk[v]=rk[u]+1;q[++tl]=v;
			}
		}
		return rk[t];
	}
	int dfs(int u,int flow){
		if(u==t)return flow;
		int tot=0;
		for(int &i=cur[u];i;i=side[i].next){
			int v=side[i].v;if(rk[u]+1!=rk[v]||!side[i].w)continue;
			int sent=dfs(v,min(flow,side[i].w));flow-=sent;tot+=sent;
			side[i].w-=sent;side[i^1].w+=sent;
		}
		return tot;
	}
	void dinic(){
		int maxflow=0;
		while(bfs()){
			memcpy(cur,head,sizeof(head));
			maxflow+=dfs(s,inf);
		}
	}
