typedef int FLOW;
const FLOW INF = 10000000;

struct UnblockedPath {
    bool found = false;
    vector<int> preNodes;
    FLOW flow = 0;
};

class Graph {
public:
    int N;
    vector< vector<FLOW> > edges;
    vector< vector<bool> > added;
    vector< vector<int> > outEdges;

    Graph(int N) {
        this->N = N;

        edges = vector< vector<FLOW> >(N, vector<FLOW>(N, 0));
        added = vector< vector<bool> >(N, vector<bool>(N, false));
        outEdges = vector< vector<int> >(N, vector<int>());
    }

    void addEdge(int s, int t, FLOW w) {
        if (added[s][t] == false && w > 0) {
            outEdges[s].push_back(t);
        }
        edges[s][t] = w;

        if (w > 0) {
            added[s][t] = true;
        }
    }

    int getNodeNum() { return N; }

    vector<int> getOutEdges(int node) {
        return outEdges[node];
    }

    FLOW getEdge(int s, int t) {
        return edges[s][t];
    }
};

class MaxFlow {
public:
    int sink, source;
    FLOW maxFlow = 0;
    vector<UnblockedPath> paths;

    MaxFlow(int s, int t) {
        source = s;
        sink = t;
    }

    static UnblockedPath findUnblockedPath(Graph &g, int source, int sink) {
        UnblockedPath ubp{};
        ubp.preNodes = vector<int>(g.getNodeNum());
        ubp.preNodes[source] = -1;

        vector<bool> visited = vector<bool>(g.getNodeNum());

        queue<int> q;
        q.push(source);

        while (!q.empty()) {
            int currentNode = q.front();
            q.pop();
            visited[currentNode] = true;

            if (currentNode == sink) {
                ubp.found = true;
                break;
            }

            for (int nextNode: g.getOutEdges(currentNode)) {
                if (!visited[nextNode] && g.getEdge(currentNode, nextNode) > 0) {
                    ubp.preNodes[nextNode] = currentNode;
                    q.push(nextNode);
                }
            }
        }

        return ubp;
    }

    static MaxFlow FordFulkerson(Graph &g, int source, int sink) {
        MaxFlow mf(source, sink);
        FLOW increment = INF;

        while (true) {
            UnblockedPath ubp = findUnblockedPath(g, source, sink);
            if (!ubp.found) {
                break;
            }

            int end = ubp.preNodes[source];
            int temp = sink;

            while (ubp.preNodes[temp] != end) {
                increment = min(increment, g.getEdge(ubp.preNodes[temp], temp));
                temp = ubp.preNodes[temp];
            }

            ubp.flow = increment;
            mf.maxFlow += increment;
            mf.paths.push_back(ubp);

            temp = sink;
            while (ubp.preNodes[temp] != end) {
                g.addEdge(ubp.preNodes[temp], temp, g.getEdge(ubp.preNodes[temp], temp) - increment);
                g.addEdge(temp, ubp.preNodes[temp], g.getEdge(temp, ubp.preNodes[temp]) + increment);
                temp = ubp.preNodes[temp];
            }
        }

        return mf;
    }

    void analyse() {
        cout << "source  : " << source << endl;
        cout << "sink    : " << sink << endl;
        cout << "maxFlow : " << maxFlow << endl;

        for (UnblockedPath ubp : paths) {
            int temp = sink;
            int end = ubp.preNodes[source];

            cout << ubp.flow << "\t: ";
            while (ubp.preNodes[temp] != end) {
                cout << temp << " => ";
                temp = ubp.preNodes[temp];
            }
            cout << source << endl;
        }
    }
};

