void proc() {
	LOAD(int, N);
	LOAD(int, M);
	srand(100000007);
	std::vector<int>A(N * M);
	auto a = [&](int i, int j)->int& {
		return A[M * i + j];
	};
	//
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
			cin >> a(i, j);
		}
	}
	std::vector<std::vector<int>>n(M);
	for (int i = 0; i < M; ++i) {
		n[i].resize(N);
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
			n[j][(a(i, j) - 1) / M]++;
		}
	}
	//
	while (true) {
		for (int j = 0; j < M; ++j) {
			std::vector<int>I(N);
			std::unordered_set<int>Is;
			std::iota(ALL(I), 0);
			for (int i_ = 0; i_ < N; ++i_) {
				swap(I[i_], I[rand() % N]);
			}
			bool restart = false;
			for (int i_ = 0; i_ < N; ++i_) {
				int i = I[i_];
				Is.insert(i);
				while (2 <= n[j][i]) {
					int jj;
					for (jj = j + 1; jj <= M; ++jj) {
						if (jj == M) {
							break;
						}
						if (n[jj][i] == 0) {
							break;
						}
					}
					if (jj == M) {
						restart = true;
						break;
					}
					int ii;
					for (ii = 0; ii <= N; ++ii) {
						if (ii == N)break;
						auto itr = Is.find((a(ii, jj) - 1) / M);
						if ((a(ii, j) - 1) / M == i) {
							if (itr == Is.end() || rand() % 10 == 0) {
								break;
							}
						}
					}
					if (ii == N)break;
					n[j][(a(ii, j) - 1) / M]--;
					n[j][(a(ii, jj) - 1) / M]++;
					n[jj][(a(ii, j) - 1) / M]++;
					n[jj][(a(ii, jj) - 1) / M]--;
					std::swap(a(ii, j), a(ii, jj));
				}
				if (restart)break;
			}
			if (restart)break;
		}
		bool bFlag = true;
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j < M; ++j) {
				if (n[j][i] != 1) {
					bFlag = false;
					break;
				}
			}
		}
		if (bFlag)break;
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
			cout << a(i, j);
			if (j + 1 != M) {
				cout << " ";
			}
		}
		cout << endl;
	}
	std::vector<std::vector<int>>B(M);
	for (int i = 0; i < M; ++i) {
		B[i].resize(N);
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
			B[j][i] = a(i, j);
		}
	}
	for (int i = 0; i < M; ++i) {
		sort(ALL(B[i]));
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
			cout << B[j][i];
			if (j + 1 != M) {
				cout << " ";
			}
		}
		cout << endl;
	}
}

