int dfs (int u, int lim) {
  if (u == t) return lim;
  int tf = 0;
  for (auto v : edges[u]) {
    if (cap[v.se] && dist[v.fi] == dist[u] + 1) {
      int f = dfs(v.fi, min(lim, cap[v.se]));
      cap[v.se] -= f; cap[v.se ^ 1] += f;
      //if (f) cout << u << ' ' << v.fi << endl;
      lim -= f; tf += f;
    }
  }
  return tf;
}
