#include <bits/stdc++.h>

using namespace std;

const int MAXN = 1e2 + 5;

int n, m;
int a[MAXN][MAXN];

void read_input()
{
	scanf("%d %d", &n, &m);

	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < m; j++)
		{
			scanf("%d", &a[i][j]);
			a[i][j]--;
		}
		sort(a[i], a[i] + n);
	}
}

int for_row[MAXN][MAXN];

bool used[MAXN];
int par[MAXN];

int k;
vector <int> graph[MAXN];

bool try_kuhn(int p)
{
	if(used[p]) return false;
	used[p] = true;

	int z = graph[p].size();
	for(int i = 0; i < z; i++)
	{
		int to = graph[p][i];
		if(par[to] == -1 || try_kuhn(par[to]))
		{
			par[to] = p;
			return true;
		}
	}
	return false;
}

int b1[MAXN][MAXN], b2[MAXN][MAXN];
bool con[MAXN];

void solve()
{
	bool fl = true;
	for(int i = 0; i < n; i++)
	{
		k = i;

		memset(par, -1, sizeof(par));

		for(int j = 0; j < m; j++)
		{
			graph[j].clear();
			int temp = a[i][j] / m;
			for(int z = 0; z < m; z++)
			{
				if(for_row[z][temp] == 0)
				{
					graph[j].push_back(z);
				}
			}
		}

		for(int j = 0; j < m; j++)
		{
			for(int z = 0; z < m; z++)
			{
				used[z] = 0;
			}
			fl &= try_kuhn(j);
		}
		for(int j = 0; j < m; j++)
		{
			//printf("~%d ", par[j]);
			int temp = a[i][par[j]] / m;
			for_row[j][temp] = true;
			b1[i][j] = par[j];
		}
		//printf("\n");
	}

	if(!fl)
	{
		printf("%d\n", 5 / 0);
		return;
	}
	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < m; j++)
		{
			printf("%d ", a[i][b1[i][j]] + 1);
			b2[j][i] = a[i][b1[i][j]] + 1;
		}
		printf("\n");
	}
	for(int i = 0; i < m; i++)
	{
		sort(b2[i], b2[i] + n);
	}

	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < m; j++)
		{
			printf("%d ", b2[j][i]);
		}
		printf("\n");
	}

}
int main()
{
	read_input();
	solve();

	return 0;
}

