using Tup = tuple<int, int, int>;
vector<Tup> eds;
map<int, pii> op[114];

void Invert(int v, int uc, int vc) {
  assert(op[v].count(uc));
  int w = v;
  vector<int> vs(1, w);
  vector<int> as;
  while (op[w].count(uc)) {
    int nw, a;
    tie(nw, a) = op[w][uc];
    vs.eb(nw);
    as.eb(a);
    swap(uc, vc);
    w = nw;
  }

  int m = as.size();
  assert(unused[vs.back()].count(uc));
  assert(!op[vs.back()].count(uc));
  unused[vs.back()].insert(vc);
  op[vs.back()].erase(vc);
  rrep(i, m) {
    int a = as[i];
    int u = vs[i];
    int v = vs[i+1];
    op[u][uc] = pii(v, a);
    op[v][uc] = pii(u, a);
    unused[u].erase(uc);
    unused[v].erase(uc);
    swap(uc, vc);
  }
  assert(op[vs.front()].count(uc) && op[vs.front()].count(vc));
  op[vs.front()].erase(uc);
  unused[vs.front()].insert(uc);
}

