#include <bits/stdc++.h>
using namespace std;
const int N = 550;
int n,m;
int a[N][N], used[N][N];
int S, T, tot, to[N * N * 2], nex[N * N * 2], final[N * 2], f[N * N * 2];
int e[N][N], ans[N][N];

void _link(int x, int y, int fl) {
	to[++tot] = y, nex[tot] = final[x], final[x] = tot;
	f[tot] = fl;
}

void link(int x, int y, int fl) {
	_link(x, y, fl), _link(y, x, 0);
}

int dis[N * 2];

void bfs() {
	for(int i = 1; i <= T; i++) dis[i] = -1;
	static int Q[N * 2]; int h = 0, t = 0;
	Q[++t] = S;
	dis[S] = 0;
	while(h < t) {
		int x = Q[++h];
		for(int i = final[x]; i; i = nex[i]) if(f[i]) {
			int y = to[i]; if (dis[y] == -1) {
				dis[y] = dis[x] + 1;
				Q[++t] = y;
			}
		}
	}
}

int go(int x,int flow) {
	if (x == T) return flow;
	int used = 0;
	for(int i = final[x]; i; i = nex[i]) if(f[i] && dis[x] + 1 == dis[to[i]]) {
		int y = to[i];
		int take = go(y, min(f[i], flow - used));
		used += take;
		f[i] -= take;
		f[i ^ 1] += take;
		if (used == flow) return used;
	}
	return used;
}

void work(int col) {
	tot = 1;
	memset(final, 0, sizeof final);
	S = n + n + 1, T = S + 1;
	for(int i = 1; i <= n; i++) {
		link(S, i, 1);
		for(int j = 1; j <= m; j++) if (!used[i][j]) {
			e[i][j] = tot + 1;
			link(i, n + 1 + (a[i][j] - 1) / m, 1);
		}
	}

	for(int i = 1; i <= n; i++) {
		link(n + i, T, 1);
	}

	while(bfs(), dis[T] != -1)
		go(S, 1e9);

	for(int i = 1; i <= n; i++) 
		for(int j = 1; j <= m; j++) if (!used[i][j]) {
			if (f[e[i][j]] == 0) {
				ans[i][col] = a[i][j];
				used[i][j] = 1;
				break;
			}
		}
}

int g[N];
int main() {
	//int gg = clock();
	//freopen("d.in","r",stdin);
