	cin>>n>>m;
	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= m; j++) scanf("%d", &a[i][j]);//, a[i][j] = (i - 1) * m + j;
	}

	for(int i = 1; i <= m; i++) {
		//cerr<<i<<endl;
		work(i);
	}

	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= m; j++) printf("%d ",ans[i][j]);
		printf("\n");
	}

	for(int i = 1; i <= m; i++) {
		for(int j = 1; j <= n; j++) g[j] = ans[j][i];
		sort(g + 1, g + 1 + n);
		for(int j = 1; j <= n; j++) ans[j][i] = g[j];
	}

	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= m; j++) printf("%d ",ans[i][j]);
		printf("\n");
	}
	//cerr<<clock()-gg<<endl;
