class DinicMatching{
private:
	struct Edge{ ll to, cap, rev; };
	vector<vector<Edge>> G;
	vll level;
	vll iter;
	ll sNum, tNum, s, t;
public:
	DinicMatching(ll sNum, ll tNum):
		G(sNum+tNum+2), sNum(sNum), tNum(tNum), s(sNum+tNum), t(sNum+tNum+1)
	{
#if 0
		EACH(e, edges){ this->Link(e.first, e.second+sNum, 1); }
#endif
		REP(i, sNum){ this->link(this->s, i, 1); }
		REP(i, tNum){ this->link(i+sNum, this->t, 1); }
	}

#if 0
	DinicMatching(ll sNum, ll tNum, vector<pair<ll, ll>> &edges):
		G(sNum+tNum+2), sNum(sNum), tNum(tNum), s(sNum+tNum), t(sNum+tNum+1)
	{
		EACH(e, edges){ this->Link(e.first, e.second+sNum, 1); }
		REP(i, sNum){ this->Link(this->s,       i, 1); }
		REP(i, tNum){ this->Link( i+sNum, this->t, 1); }
	}
#endif

	void Link(ll sIdx, ll tIdx){
		ll v = sIdx, u = tIdx + this->sNum;
		this->G[v].push_back({u,  1, (ll)this->G[u].size()});
		this->G[u].push_back({v,  0, (ll)this->G[v].size()-1});
	}

	vector<pair<ll,ll>> GetMatch(){ //最大マッチングを得る
		ll matchNum = MaxFlow(this->s, this->t);
		vector<pair<ll, ll>> matches;
		REP(v, sNum){//ソース側ノードをなめる
			EACH(e, G[v]){
				if (e.cap == 0 && e.to != s){
					matches.emplace_back(v, e.to-sNum);
					break;
				}
			}
		}
		return move(matches);
	}

	ll MaxFlow(ll s, ll t){//s→tの最大流を求める
		ll f, flow = 0;
		while (true){
			this->BfsLevelRenew(s);
			if (this->level[t] < 0) return flow;
			iter.assign(this->G.size(), 0);
			while ((f = this->DfsFindPath(s, t, INF)) > 0) { flow += f; }
		}
	}

private:
	void link(ll v, ll u, ll cap, ll rcap = 0){//v→uに重みcapで張る、逆辺も張る
		this->G[v].push_back({u,  cap, (ll)this->G[u].size()});
		this->G[u].push_back({v, rcap, (ll)this->G[v].size()-1});
	}

	void BfsLevelRenew(ll s) {
		this->level.assign(this->G.size(), -1);
		this->level[s] = 0;
		queue<ll> que;
		que.push(s);
		while (!que.empty()){
			ll from = que.front(); que.pop();
			EACH(e, this->G[from]){
				if (e.cap > 0 && this->level[e.to] < 0){
					this->level[e.to] = this->level[from] + 1;
					que.push(e.to);
				}
			}
		}
	}

	ll DfsFindPath(ll v, ll t, ll f){
		if (v == t) return f;

		for (ll &i = iter[v]; i < (ll)this->G[v].size(); i++){
			Edge &e = this->G[v][i];
			if (e.cap > 0  &&  this->level[v] < this->level[e.to]){
				ll d = this->DfsFindPath(e.to, t, min(f, e.cap));
				if (d > 0){
					e.cap -= d;
					this->G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};


void solve()
{
	ll N, M;
	cin >> N >> M;

	vvll A(N);
	REP(i, N) A[i] = cinv(M);
	REP(i, N)REP(j, M) A[i][j]--;

	vvll B(N);

	REP(r, M){
#if 0
		vector<pair<ll, ll>> pairs;
		REP(i, N) REP(j, M){
			pairs.emplace_back(i, A[i][j]/M);
		}
		DinicMatching dm(N, N, pairs);
#endif
		DinicMatching dm(N, N);
		REP(i, N){
			REP(j, M-r) dm.Link(i, A[i][j]/M);
		}
		auto matches = dm.GetMatch();

		REP(i, N){
			REP(j, M-r){
				if (A[i][j]/M == matches[i].second){
					B[i].push_back(A[i][j]);
					A[i].erase(A[i].begin()+j);
					break;
				}
			}
		}
	}

	vvll C(N);
	REP(r, M){
		vll tmp(N);
		REP(i, N) tmp[i] =  B[i][r];
		sort(tmp.begin(), tmp.end());
		REP(i, N) C[i].push_back(tmp[i]);
	}


	REP(i, N)REP(j, M) B[i][j]++;
	REP(i, N)REP(j, M) C[i][j]++;

	REP(i, N) coutv(B[i]);
	REP(i, N) coutv(C[i]);
}

