// bipartite matching
struct match {
  vi pre, root;
  vvi to;
  vi p, q;
  int n, m;
  match(int n, int m):pre(n,-1),root(n,-1),to(n),p(n,-1),q(m,-1),n(n),m(m){}
  void add(int a, int b) { to[a].pb(b);}
  int solve() {
    int res = 0;
    bool upd = true;
    while (upd) {
      upd = false;
      queue<int> s;
      rep(i,n) if (!~p[i]) {
        root[i] = i;
        s.push(i);
      }
      while (sz(s)) {
        int v = s.front(); s.pop();
        if (~p[root[v]]) continue;
        rep(i,sz(to[v])) {
          int u = to[v][i];
          if (!~q[u]) {
            while (~u) {
              q[u] = v;
              swap(p[v],u);
              v = pre[v];
            }
            upd = true;
            ++res;
            break;
          }
          u = q[u];
          if (~pre[u]) continue;
          pre[u] = v; root[u] = root[v];
          s.push(u);
        }
      }
      if (upd) fill(rng(pre),-1), fill(rng(root),-1);
    }
    return res;
  }
};

void output(vvi a) {
  rep(i,sz(a)) cout<<a[i]<<endl;
}

int main() {
  int h,w;
  scanf("%d%d",&h,&w);
  vvi a(h,vi(w));
  cin>>a;
  {
    vvvi ps(h,vvi(h));
    rep(i,h)rep(j,w) {
      int g = (a[i][j]-1)/w;
      ps[g][i].pb(a[i][j]);
    }
    vvi b(h,vi(w));
    rep(j,w) {
      match g(h,h);
      rep(k,h)rep(i,h) if (sz(ps[k][i])) g.add(i,k);
      assert(g.solve() == h);
      rep(i,h) {
        int k = g.p[i];
        b[i][j] = ps[k][i].back();
        ps[k][i].pop_back();
      }
    }
    output(b);
    a = b;
  }
  {
    rep(i,w) {
      vi s;
      rep(j,h) s.pb(a[j][i]);
      sort(rng(s));
      rep(j,h) a[j][i] = s[j];
    }
    output(a);
  }
  return 0;
}

