struct tinder {
    int n, u;
    vector< vector<int> > g;
    vector<int> used, mt;

    tinder(int n) : n(n), u(1) {
        g.resize(n);
        used.resize(n, 0);
        mt.resize(n, -1);
    }

    void add_edge(int i, int j) {
        g[i].emplace_back(j);
    }

    bool dfs(int v) {
        if (used[v] == u)
            return false;

        used[v] = u;

        for (const auto& to : g[v])
            if (mt[to] == -1 || dfs(mt[to])) {
                mt[to] = v;
                return true;
            }

        return false;
    }

    vector<int> tyan() {
        for (int i = 0; i < n; ++i, ++u)
            dfs(i);

        return mt;
    }
};

int n, m;
int a[N][N];

bool read() {
    if (!(cin >> n >> m))
        return false;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            cin >> a[i][j], --a[i][j];

    return true;
}

void solve() {
    for (int j = 0; j < m; ++j) {
        tinder T(n);

        for (int i = 0; i < n; ++i)
            for (int j1 = j; j1 < m; ++j1)
                T.add_edge(i, a[i][j1] / m);

        auto mt = T.tyan();
        assert(!count(mt.begin(), mt.end(), -1));

        for (int i = 0; i < n; ++i)
            for (int j1 = j; j1 < m; ++j1)
                if (mt[i] == a[i][j1] / m) {
                    for (int j2 = j1; j2 > j; --j2)
                        swap(a[i][j2], a[i][j2 - 1]);

                    break;
                }
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            cout << a[i][j] + 1 << " \n"[j == m - 1];

    for (int j = 0; j < m; ++j) {
        vector<int> sex;

        for (int i = 0; i < n; ++i)
            sex.emplace_back(a[i][j]);

        sort(sex.begin(), sex.end(), [] (int a, int b) {
            return a / m < b / m;
        });

        for (int i = 0; i < n; ++i)
            a[i][j] = sex[i];
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            cout << a[i][j] + 1 << " \n"[j == m - 1];
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

