void vert_const(togasat::Solver& solver, Box& A)
{
    //縦には同じに系列中ちょうど1枚が入る

    //y行におけるp行系列の存在場所
    vector<pi> G[N];
    rep(i, N)rep(j, M)
    {
        int p = A[i][j] / M;
        G[p].push_back(make_pair(i, j));
    }

    rep(j,M)rep(p, N){
    vector<int>f;
    rep(s, G[p].size()){

        int a = G[p][s].first;
        int b = G[p][s].second;
        int x = boxid(a, j);
