const int N = 205;
const int INF = 0x3f3f3f3f;

int n, m, a[N][N], b[N][N], c[N][N], res[N];

struct NetworkFlow
{
	int head[N << 1], to[N * N * 2], nxt[N * N * 2], edge[N * N * 2], cnt;
	int dep[N << 1], s, t;
	queue<int> q;

	void add(int u, int v, int w)
	{
		nxt[++cnt] = head[u];
		head[u] = cnt;
		to[cnt] = v;
		edge[cnt] = w;
	}

	void Add(int u, int v, int w)
	{
		add(u, v, w);
		add(v, u, 0);
	}

	bool bfs()
	{
		memset(dep, -1, sizeof(dep));
		dep[s] = 0;
		q.push(s);

		while (!q.empty())
		{
			int u = q.front();
			q.pop();
			for (int i = head[u]; i; i = nxt[i])
			{
				int v = to[i];
				int w = edge[i];
				if (w > 0 && dep[v] == -1)
				{
					dep[v] = dep[u] + 1;
					q.push(v);
				}
			}
		}

		return dep[t] != -1;
	}

	int dfs(int u, int flow)
	{
		if (dep[u] == dep[t]) return u == t ? flow : 0;
		int out = 0;
		for (int i = head[u]; i; i = nxt[i])
		{
			int v = to[i];
			int w = edge[i];
			if (w > 0 && dep[v] == dep[u] + 1)
			{
				int f = dfs(v, min(flow - out, w));
				edge[i] -= f;
				edge[i ^ 1] += f;
				out += f;
				if (out == flow) break;
			}
		}
		return out; 
	}

	void reset()
	{
		cnt = 1;
		s = N * 2 - 2;
		t = N * 2 - 1;
		memset(head, 0, sizeof(head));
		for (int i = 1; i <= n; ++i)
		{
			Add(s, i, 1);
			Add(i + n, t, 1);
		}
	}

	void maxflow()
	{
		while (bfs()) dfs(s, INF);
		for (int u = 1; u <= n; ++u)
		{
			res[u] = -1;
			for (int i = head[u]; i; i = nxt[i])
			{
				int v = to[i];
				int w = edge[i];
				if (v <= 2 * n && w == 0)
				{
					res[u] = v - n;
					break;
				}
			}
		}
	}
} flow;

int main()
{
