		{
			for (int j = 1; j <= m; ++j)
			{
				if (a[i][j]) flow.Add(i, (a[i][j] - 1) / m + 1 + n, 1);
			}
		}
		flow.maxflow();
		for (int i = 1; i <= n; ++i)
		{
			for (int j = 1; j <= m; ++j)
			{
				if (a[i][j] && (a[i][j] - 1) / m + 1 == res[i])
