const int INF = 100000000;

template <typename T>
struct Edge
{
    int to;
    T cap;
    int rev;
    int id;
};

template <typename T>
struct Flow
{
    int n, c;
    vector<vector<Edge<T>>> g;
    vector<int> ch;

    Flow(){}

    Flow(int n) : n(n), c(1){
        g.resize(n);
        ch.resize(n);
    }

    void add_edge(int from, int to, T cap, int id = -1){
        g[from].push_back((Edge<T>){to, cap, (int)g[to].size(), id});
        g[to].push_back((Edge<T>){from, 0, (int)g[from].size() - 1, -1});
    }

    T dfs(int u, T f, int t){
        if(u == t) return f;
        ch[u] = c;
        for(int i = 0; i < (int)g[u].size(); i++){
            Edge<T> &e = g[u][i];
            int v = e.to;
            if(e.cap > 0 && ch[v] != c){
                T fl = dfs(v, min(f, e.cap), t);
                if(fl > 0){
                    e.cap -= fl;
                    g[v][e.rev].cap += fl;
                    return fl;
                }
            }
        }
        return 0;
    }

    T max_flow(int s, int t){
        T res = 0;
        for(T f; (f = dfs(s, INF, t)) > 0; c++) res += f;
        return res;
    }
};

struct Bipartite_Matching
{
    int n;
    int m;
    Flow<int> g;
    vector<int> match;

    Bipartite_Matching(int n, int m) : n(n), m(m){
        g.n = n + m + 2;
        g.c = 1;
        g.ch.resize(g.n);
        g.g.resize(g.n);
        for(int i = 0; i < n; i++) g.add_edge(n + m, i, 1);
        for(int i = n; i < n + m; i++) g.add_edge(i, n + m + 1, 1);
    }

    void add_edge(int i, int j, int id = -1){
        g.add_edge(i, j + n, 1, id);
    }

    int max_matching(){
        g.max_flow(n + m, n + m + 1);
        for(int i = 0; i < n; i++){
            for(int j = 1; j < (int)g.g[i].size(); j++){
                if(g.g[i][j].cap == 0) match.push_back(g.g[i][j].id);
            }
        }
        return (int)match.size();
    }
};

int main()
{
