const int MAXH=100,MAXW=100;

int h,w;
int a[MAXH][MAXW];
int b[MAXH][MAXW];
int c[MAXH][MAXW];

vector<int> vals[MAXH][MAXH];

bool can[MAXH][MAXH];

int lmatch[MAXH],rmatch[MAXH];
bool ldone[MAXH];

bool augment(int x) {
	if(ldone[x]) return false; else ldone[x]=true;
	REP(xx,h) if(can[x][xx]&&(rmatch[xx]==-1||augment(rmatch[xx]))) { rmatch[xx]=x,lmatch[x]=xx; return true; }
	return false;
}

int maxmatch() {
	REP(x,h) lmatch[x]=rmatch[x]=-1,ldone[x]=false;
	int ret=0; REP(x,h) if(augment(x)) { ++ret; REP(xx,h) ldone[xx]=false; }
	return ret;
}


void solve() {
	REP(x,h) REP(xx,h) vals[x][xx].clear();
	REP(x,h) REP(y,w) vals[x][a[x][y]/w].PB(a[x][y]);
	REP(y,w) {
		REP(x,h) REP(xx,h) can[x][xx]=SZ(vals[x][xx])>0;
		//printf("can:\n"); REP(x,h) { REP(xx,h) printf("%c",can[x][xx]?'V':'.'); puts(""); }
		assert(maxmatch()==h);
		REP(x,h) { int xx=lmatch[x]; assert(xx!=-1&&SZ(vals[x][xx])!=0); int v=vals[x][xx].back(); vals[x][xx].pop_back(); b[x][y]=v; c[xx][y]=v; }
	}

}

void run() {
	scanf("%d%d",&h,&w);
	REP(x,h) REP(y,w) scanf("%d",&a[x][y]),--a[x][y];
	solve();
	REP(x,h) { REP(y,w) { if(y!=0) printf(" "); printf("%d",b[x][y]+1); } puts(""); }
	REP(x,h) { REP(y,w) { if(y!=0) printf(" "); printf("%d",c[x][y]+1); } puts(""); }
}

int main() {
	run();
	return 0;
}

