const int MAXN = 1e2 + 5;

int n, m;
int a[MAXN][MAXN];

void read_input()
{
	scanf("%d %d", &n, &m);

	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < m; j++)
		{
			scanf("%d", &a[i][j]);
			a[i][j]--;
		}
	}
}

int for_row[MAXN][MAXN];

bool used[MAXN];
int par[MAXN];

int k;

bool try_kuhn(int p)
{
	if(used[p]) return false;
	used[p] = true;
	int j = a[k][p] / m;

	for(int i = 0; i < m; i++)
	{
		if(par[i] == -1 && for_row[i][j] == 0)
		{
			par[i] = p;
			for_row[i][j] = true;
			return true;
		}
		if(for_row[i][j] == 0)
		{
			int prev = a[k][par[i]] / m;
			if(try_kuhn(par[i]))
			{
				for_row[i][prev] = false;
				par[i] = p;
				for_row[i][j] = true;
				return true;
			}
		}
	}
	return false;
}

int b1[MAXN][MAXN], b2[MAXN][MAXN];
bool con[MAXN];

void solve()
{
	bool fl = true;
	for(int i = 0; i < n; i++)
	{
		k = i;

		memset(par, -1, sizeof(par));
		memset(con, 0, sizeof(con));

		for(int j = 0; j < m; j++)
		{
			int temp = a[i][j] / m;
			for(int z = 0; z < m; z++)
			{
				if(par[z] == -1 && for_row[z][temp] == 0)
				{
					for_row[z][temp] = true;
					par[z] = j;
					con[j] = true;
					break;
				}
			}
		}

		for(int j = 0; j < m; j++)
		{
			if(con[j]) continue;
			for(int z = 0; z < m; z++)
			{
				used[j] = 0;
			}
			fl &= try_kuhn(j);
		}
		for(int j = 0; j < m; j++)
		{
			//printf("~%d ", par[j]);
			b1[i][j] = par[j];
		}
		//printf("\n");
	}

	if(!fl)
	{
		printf("%d\n", 5 / 0);
	}
	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < m; j++)
		{
			printf("%d ", a[i][b1[i][j]] + 1);
			b2[j][i] = a[i][b1[i][j]] + 1;
		}
		printf("\n");
	}
	for(int i = 0; i < m; i++)
	{
		sort(b2[i], b2[i] + n);
	}

	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < m; j++)
		{
			printf("%d ", b2[j][i]);
		}
		printf("\n");
	}

}
int main()
{
	read_input();
	solve();

	return 0;
}

