#include <bits/stdc++.h>
using namespace std;

const int MAXN = 205;
const int INF = 1000000000;

struct edge {
	int a, b, cap, flow;
};

int N, s, t, d[MAXN], ptr[MAXN], q[MAXN];
vector<edge> e;
vector<int> g[MAXN];

void add_edge (int a, int b, int cap) {
	edge e1 = { a, b, cap, 0 };
	edge e2 = { b, a, 0, 0 };
	g[a].push_back ((int) e.size());
	e.push_back (e1);
	g[b].push_back ((int) e.size());
	e.push_back (e2);
}

bool bfs() {
	int qh=0, qt=0;
	q[qt++] = s;
	memset (d, -1, N * sizeof d[0]);
	d[s] = 0;
	while (qh < qt && d[t] == -1) {
		int v = q[qh++];
		for (size_t i=0; i<g[v].size(); ++i) {
			int id = g[v][i],
				to = e[id].b;
			if (d[to] == -1 && e[id].flow < e[id].cap) {
				q[qt++] = to;
				d[to] = d[v] + 1;
			}
		}
	}
	return d[t] != -1;
}

int dfs (int v, int flow) {
	if (!flow)  return 0;
	if (v == t)  return flow;
	for (; ptr[v]<(int)g[v].size(); ++ptr[v]) {
		int id = g[v][ptr[v]],
			to = e[id].b;
		if (d[to] != d[v] + 1)  continue;
		int pushed = dfs (to, min (flow, e[id].cap - e[id].flow));
		if (pushed) {
			e[id].flow += pushed;
			e[id^1].flow -= pushed;
			return pushed;
		}
	}
	return 0;
}

int dinic() {
	int flow = 0;
	for (;;) {
		if (!bfs())  break;
		memset (ptr, 0, N * sizeof ptr[0]);
		while (int pushed = dfs (s, INF))
			flow += pushed;
	}
	return flow;
}

const int Maxn = 105;

int n, m;
int B[Maxn][Maxn];
int myr[Maxn * Maxn];
int A[Maxn][Maxn];

void Solve(int lef, int rig)
{
    N = m + m + 2; s = 0, t = N - 1;
    e.clear();
    for (int i = 0; i < N; i++)
        g[i].clear();
    for (int i = lef; i <= rig; i++)
        add_edge(0, i - lef + 1, 1);
    for (int i = 0; i < m; i++)
        add_edge(1 + m + i, N - 1, 1);
    for (int i = lef; i <= rig; i++) {
        int r = myr[i];
        for (int j = 0; j < m; j++) if (!A[r][j])
            add_edge(i - lef + 1, 1 + m + j, 1);
    }
    assert(dinic() >= m);
