template<class T>
struct Dinic {
    int s, t, tot;
    vector<edge> edges;
    vector<int> G[maxn];
    bool vis[maxn];
    int d[maxn];
    int cur[maxn];
    T infinity;

    void init(T infinity) {
        edges.clear();
        for (int i = 0; i <= t; i++)G[i].clear();
        this->infinity = infinity;
    }

    void addedge(int from, int to, int cap) {
        edges.push_back(edge{from, to, cap, 0});
        edges.push_back(edge{to, from, 0, 0});
        tot = edges.size();
        G[from].push_back(tot - 2);
        G[to].push_back(tot - 1);
    }

    bool bfs() {
        memset(vis, 0, sizeof(vis));
        queue<int> q;
        q.push(s);
        d[s] = 0;
        vis[s] = 1;
        while (!q.empty()) {
            int x = q.front();
            q.pop();
            for (int i = 0; i < G[x].size(); i++) {
                edge &e = edges[G[x][i]];
                if (!vis[e.to] && e.cap > e.flow) {
                    vis[e.to] = 1;
                    d[e.to] = d[x] + 1;
                    q.push(e.to);
                }
            }
        }
        return vis[t];
    }

    T dfs(int x, T a) {
        if (x == t || a == 0)return a;
        T flow = 0, f;
        for (int &i = cur[x]; i < G[x].size(); i++) {
            edge &e = edges[G[x][i]];
            if (d[x] + 1 == d[e.to] && (f = dfs(e.to, min(a, e.cap - e.flow))) > 0) {
                e.flow += f;
                edges[G[x][i] ^ 1].flow -= f;
                flow += f;
                a -= f;
                if (a == 0)break;
            }
        }
        return flow;
    }

    T maxflow() {
        T flow = 0;
        while (bfs()) {
            memset(cur, 0, sizeof(cur));
            flow += dfs(s, infinity);
        }
        return flow;
    }

    /*求最小点覆盖，从s出发，左边标记过的点和右边没标记过的点构成最小点覆盖，除去这些点外的点构成最大独立集。

    void dfs1(int u) {
        ok[u] = 1;
        for (int i = 0; i < G[u].size(); i++) {
            edge &e = edges[G[u][i]];
            if (e.cap > e.flow && !ok[e.to]) dfs1(e.to);
        }
    }*/
};

