vector<pair<int,int>> maxmatch() {
  fill_n(matching, n, -1);
  for (int i = 0; i < n; i++) {
    fill_n(done, n, 0);
    assert(match(i));
  }
  vector<pair<int,int>> r;
  for (int i = 0; i < n; i++) {
    r.push_back({matching[i], i});
  }
  return r;
}

