		if (pos == -1) return true;
		for (int i = 0; i < H; ++i) {
			int nxt = (pos < H ? i + H : i);
			if (vis[nxt] || (pos < H ? G[pos][i] : G[i][pos - H]) == 0) continue;
			vis[nxt] = true;
