const int INF = 2e9;

class Dinic {
public: 
    Dinic(): n(0) {};

    Dinic(int k, bool dir) {
        n = k;
        direct = dir;
        g.resize(n);
    }

    void addOneEdge(int u, int v, int cap) {
        g[u].push_back(sz(edges));
        edges.push_back(Edge{u, v, cap, 0});
    }

    void addEdge(int u, int v, int cap) {
        addOneEdge(u, v, cap);
        addOneEdge(v, u, direct ? 0 : cap);
    }

    ll maxFlow(int s, int t) {
        ll ans = 0;
        vector<int> dist(n);
        while (bfs(s, t, dist)) {
            int flow = 0;
            vector<int> ptr(n);
            while ((flow = dfs(s, t, dist, ptr, INF)) > 0) 
                ans += (ll)flow;
        }
        return ans;
    }

    vector<int> get(int s) {
        vector<int> res;
        for (int e : g[s]) {
            auto ed = edges[e];
            int v = ed.to;
            for (int i = 0; i < sz(g[v]); ++i) {
                if (edges[g[v][i]].flow > 0) {
                    res.push_back(edges[g[v][i]].to);
                }
            }
        }
        return res;
    }

    void clear() {
        for (int i = 0; i < sz(edges); ++i)
            edges[i].flow = 0;
    }

private:
    bool bfs(int s, int t, vector<int> &dist) {
        queue<int> q;
        dist.assign(sz(dist), -1);
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int cur = q.front();
            for (auto e : g[cur]) {
                if (dist[edges[e].to] == -1 && edges[e].cap > edges[e].flow) {
                    q.push(edges[e].to);
                    dist[edges[e].to] = dist[cur] + 1;
                }
            }
            q.pop();
        }
        return (dist[t] >= 0);
    }

    int dfs(int v, int t, vector<int> &dist, vector<int> &ptr, int maxFlow) {
        if (v == t)
            return maxFlow;
        for (int i = ptr[v]; i < sz(g[v]); ++i) {
            int e = g[v][i];
            if (dist[v] + 1 == dist[edges[e].to] && edges[e].cap - edges[e].flow > 0) {
                int curFlow = min(maxFlow, edges[e].cap - edges[e].flow);
                int flow = dfs(edges[e].to, t, dist, ptr, curFlow);
                if (flow > 0) {
                    edges[e].flow += flow;
                    edges[e ^ 1].flow -= flow;
                    return flow;
                }
            }
            ++ptr[v];
        }
        return 0;
    }

    struct Edge {
        int from;
        int to;
        int cap;
        int flow;
    };

    int n;
    bool direct;
    vector<Edge> edges;
    vector<vector<int>> g;
    vector<int> pos;
};

