void solve() {
  int n, m; cin >> n >> m;
  Graph<int> a(n, vi(m)); cin >> a;

  vector<map<int, int>> column(n), num(n);
  vector<queue<int>> g(n);
  rep(i,n) {
    for (auto &v : a[i]) {
      int j = (v-1) / m;
      column[i][j]++;
      num[j][i]++;
      g[j].emplace(v);
    }
  }

  Graph<int> pre(n, vi(m));

  rep(j,m) {
    auto s = column;
    auto t = num;
    vb seen(n, false), finished(n, false);
    queue<pii> q;

    rep(i,n) {
      if (seen[i]) continue;
      int val = begin(s[i])->first;
      seen[i] = finished[val] = true;
      q.emplace(i, val);

      while (!q.empty()) {
        int k, v;
        tie(k, v) = q.front();
        q.pop();
        pre[k][j] = v;
        s[k].erase(v);
        t[v].erase(k);

        for (auto &p : s[k]) {
          t[p.first].erase(k);
          if (t[p.first].size() == 1 && !finished[p.first]) {
            int idx = begin(t[p.first])->first;
            seen[idx] = finished[p.first] = true;
            q.emplace(idx, p.first);
          }
        }
        if (--column[k][v] == 0) column[k].erase(v);

        for (auto &p : t[v]) {
          s[p.first].erase(v);
          if (s[p.first].size() == 1 && !seen[p.first]) {
            int to = begin(s[p.first])->first;
            seen[p.first] = finished[to] = true;
            q.emplace(p.first, to);
          }
        }
        if (--num[v][k] == 0) num[v].erase(k);
      }
    }
  }

  Graph<int> b(n, vi(m)), c(n, vi(m));
  rep(i,n) {
    rep(j,m) {
      b[i][j] = g[pre[i][j]].front();
      g[pre[i][j]].pop();
    }
  }
  rep(j,m) {
    rep(i,n) {
      c[(b[i][j] - 1) / m][j] = b[i][j];
    }
  }

  cout << b << endl;
  cout << c << endl;
}


