	for (int i = 0; i < M; ++i) {
		n[i].resize(N);
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
			n[j][(a(i, j) - 1) / M]++;
		}
	}
	//
	while(true) {
		for (int j = 0; j < M; ++j) {
			std::vector<int>I(N);
			std::unordered_set<int>Is;
			std::iota(ALL(I), 0);
			for (int i_ = 0; i_ < N; ++i_) {
				swap(I[i_], I[rand() % N]);
			}
			for (int i_ = 0; i_ < N; ++i_) {
				int i = I[i_];
				Is.insert(i);
				while (2 <= n[j][i]) {
					int jj;
					for (jj = j + 1; jj <= M; ++jj) {
						if (jj == M) {
							break;
						}
						if (n[jj][i] == 0) {
							break;
						}
					}
					if (jj == M)break;
					int ii;
					for (ii = 0; ii <= N; ++ii) {
						if (ii == N)break;
						auto itr = Is.find((a(ii, jj) - 1) / M);
						if ((a(ii, j) - 1) / M == i && itr == Is.end())break;
					}
					if (ii == N)break;
					n[j][(a(ii, j) - 1) / M]--;
					n[j][(a(ii, jj) - 1) / M]++;
					n[jj][(a(ii, j) - 1) / M]++;
					n[jj][(a(ii, jj) - 1) / M]--;
					std::swap(a(ii, j), a(ii, jj));
				}
			}
		}
		bool bFlag = true;
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j < M; ++j) {
				if (n[j][i] != 1) {
					bFlag = false;
					break;
				}
			}
		}
		if (bFlag)break;
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
