	for (int i = 0; i < M; ++i) {
		B[i].resize(N);
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
			B[j][i] = a(i, j);
		}
	}
	for (int i = 0; i < M; ++i) {
		sort(ALL(B[i]));
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < M; ++j) {
			cout << B[j][i];
			if (j + 1 != M) {
				cout << " ";
			}
		}
		cout << endl;
	}
}

