typedef long long LL;

vector <LL> v[405][405];
LL n,m;
LL vis[405],p[405];
LL e[405][405],ans[405][405],a[405][405];

LL dfs(LL u){
	if(!u) return 1;
	for(LL i = 1;i <= n + n;i ++){
		if(e[u][i] <= 0) continue;
		if(vis[i]) continue;
		vis[i] = 1;
		if(dfs(p[i])){
			p[u] = i; p[i] = u;
			return 1;
		}
	}
	return 0;
}

void get_match(LL x){
	memset(p,0,sizeof(p));
	for(LL i = 1;i <= n;i ++){
		memset(vis,0,sizeof(vis));
		dfs(i);
	}
	for(LL i = 1;i <= n;i ++){
		e[i][p[i]] --; e[p[i]][i] --;
		ans[x][i] = v[i][p[i]][v[i][p[i]].size() - 1];
		v[i][p[i]].pop_back();
	}
}

int main(){
	ios::sync_with_stdio(false);
	cin >> n >> m;
	for(LL i = 1;i <= n;i ++){
		for(LL j = 1;j <= m;j ++){
			cin >> a[i][j];
			e[i][(a[i][j] - 1) / m + 1 + n] ++;
			e[(a[i][j] - 1) / m + 1 + n][i] ++;
			v[i][(a[i][j] - 1) / m + 1 + n].push_back(a[i][j]);
		}
	}
	for(LL i = 1;i <= m;i ++) get_match(i);
	for(LL i = 1;i <= n;i ++){
		for(LL j = 1;j <= m;j ++){
			cout << ans[j][i] << (j == m ? '\n' : ' ');
		}
	}
	for(LL i = 1;i <= m;i ++){
		for(LL j = 1;j <= n;j ++){
			for(LL k = 1;k <= n;k ++){
				if(ans[i][j] < ans[i][k]) swap(ans[i][j],ans[i][k]);
			}
		}
	}
	for(LL i = 1;i <= n;i ++){
		for(LL j = 1;j <= m;j ++){
			cout << ans[j][i] << (j == m ? '\n' : ' ');
		}
	}
	return 0;
}

