		if(c=='-') f=-1;
		c=getchar();
	}
	while(c>='0'&&c<='9') {
		x=x*10+c-'0';
		c=getchar();
	}
	return x*f;
}
int a[N][N],b[N][N],num[N][N];
queue<int>q[N][N];
int S,T;
struct node {
	int v,nxt,w;
}e[N * N];
int head[N],ejs = 1,cur[N];
void add(int u,int v,int w) {
	e[++ejs].v = v;e[ejs].nxt = head[u];head[u] = ejs;e[ejs].w= w;
	e[++ejs].v = u;e[ejs].nxt = head[v];head[v] = ejs;e[ejs].w = 0;
}
int dep[N];
queue<int>qq;
int bfs() {
	memset(dep,0,sizeof(dep));
	dep[S] = 1;
	qq.push(S);
	while(!qq.empty()) {
		int u = qq.front();qq.pop();
		for(int i = head[u];i;i = e[i].nxt) {
			int v = e[i].v;
			if(!dep[v] && e[i].w){
				dep[v] = dep[u] + 1;
				qq.push(v);
			}
		}
	}
	return dep[T];
}

int dfs(int u,int now) {
	if(u == T) return now;
	int ret = 0;
	for(int &i = cur[u];i;i = e[i].nxt) {
		int v = e[i].v;
		if(dep[v] == dep[u] + 1 && e[i].w) {
			int k = dfs(v,min(e[i].w,now - ret));
			e[i].w -= k;
			e[i ^ 1].w += k;
			ret += k;
			if(ret == now) return ret;
		}
	}
	return ret;
}

void dinic() {
	while(bfs()) {
		memcpy(cur,head,sizeof(cur));
		dfs(S,10000000);
	}

}
