class SAState
{
public:
	SAState()
	{
	}

	SAState(const vector < vector < int > >& input_a)
	{
		a = input_a;
		H = SZ(a);
		W = SZ(a[0]);
	}

	void    saInit()
	{
		freq.resize(W);
		for (int x = 0; x < W; ++x)
		{
			freq[x].resize(H);
			for (int y = 0; y < H; ++y)
			{
				int c = a[y][x] / W;
				freq[x][c]++;
			}
		}
	}

	double  saScore()
	{
		return saRealScore();
	}

	double  saRealScore()
	{
		int ret = 0;

		for (int x = 0; x < W; ++x)
		{
			for (int c = 0; c < H; ++c)
			{
				ret -= SQ(freq[x][c]);
			}
		}
		return ret;
	}


	double  saMove()
	{
		mY = mRand.nextInt(H);
		mX1 = mRand.nextInt(W);
		mX2 = mRand.nextInt(W - 1);
		if (mX2 >= mX1) mX1++;

		const int c1 = a[mY][mX1] / W;
		const int c2 = a[mY][mX2] / W;
		const int deltaScore = -2 * (freq[mX1][c2] + freq[mX2][c1] - freq[mX1][c1] - freq[mX2][c2] + 2);
		return deltaScore;
	}

	void    saForward()
	{
		const int c1 = a[mY][mX1] / W;
		const int c2 = a[mY][mX2] / W;
		freq[mX1][c1]--;
		freq[mX2][c2]--;
		freq[mX1][c2]++;
		freq[mX2][c1]++;

		swap(a[mY][mX1], a[mY][mX2]);
	}

	int		saTheoriticalBestScore()
	{
		return - H * W;
	}

	void    saResume()
	{
	}

	void    saSetProgressRatio(double progressRatio, double temp)
	{
	}

public:
	vector <vector <int> > a;
	vector <vector <int> > freq;
	int H;
	int W;
	int mY;
	int mX1;
	int mX2;

	RandXor mRand;

};

void tenchi(vector <vector <int>>& vs)
{
	const int H = SZ(vs);
	const int W = SZ(vs[0]);

	vector <vector <int>> ret(W, vector <int>(H));
	for (int y = 0; y < W; y++)
	{
		for (int x = 0; x < H; x++)
		{
			ret[y][x] = vs[x][y];
		}
	}

	vs = ret;
}

