int NUM(int k) {

	return (k + M - 1) / M;
}

vector<int> V[105];

vector<int> W[105];

int used[105][105];

//vector<int> p(105);

int q = 1;

int sign;

void DFS(set<int> S, vector<int> p) {
	//cout << "u= " << u << endl;
	int I = p.size();

	if (sign == 1) { return; }

	if (I >=N) {

			for (int i = 1; i <= N; i++) {
				//cout << "i= " << i << " p= " << p[i-1] << endl;
				used[i][p[i - 1]] = 1;
				B[i][q] = A[i][p[i - 1]];
			}
			q++;

			sign = 1;

		return;
	}


	for (int y = 1; y <= M; y++) {
		if (S.count(NUM(A[I+1][y])) == 0 && used[I+1][y] == 0 && sign==0 ) {
			set<int> R = S;
			R.insert(NUM(A[I+1][y])); 
			vector<int> P = p;
			P.push_back(y);
			//cout << "I+1 = " <<I+1<<" val= " << A[I+1][y] <<endl;
		DFS(R, P);
		if (sign == 1) { break; }
		}
	}

}

