struct BiMatch{
  Int L,R;
  vector<vector<Int> > G;
  vector<Int> match,level;

  BiMatch(){}
  BiMatch(Int L,Int R):L(L),R(R),G(L+R),match(L+R,-1),level(L+R){}

  void add_edge(Int u,Int v){
    G[u].emplace_back(v+L);
    G[v+L].emplace_back(u);
  }

  bool bfs(){
    fill(level.begin(),level.end(),-1);
    queue<Int> q;
    for(Int i=0;i<L;i++){
      if(match[i]<0){
        level[i]=0;
        q.emplace(i);
      }
    }
    bool found=false;
    while(!q.empty()){
      Int v=q.front();q.pop();
      for(Int u:G[v]){
        if(~level[u]) continue;
        level[u]=level[v]+1;
        Int w=match[u];
        if(w==-1){
          found=true;
          continue;
        }
        if(~level[w]) continue;
        level[w]=level[u]+1;
        q.emplace(w);
      }
    }
    return found;
  }

  bool dfs(Int v){
    for(Int u:G[v]){
      if(level[v]+1!=level[u]) continue;
      level[u]=-1;
      Int w=match[u];
      if(w<0||dfs(w)){
        match[v]=u;
        match[u]=v;
        level[v]=-1;
        return true;
      }
    }
    level[v]=-1;
    return false;
  }

  Int build(){
    Int res=0;
    while(bfs())
      for(Int i=0;i<L;i++)
        if(match[i]<0&&dfs(i))
          res++;
    return res;
  }

};


