			n[j][(a(i, j) - 1) / M]++;
		}
	}
	//
	while(true) {
		for (int j = 0; j < M; ++j) {
			std::vector<int>I(N);
			std::unordered_set<int>Is;
			std::iota(ALL(I), 0);
			for (int i_ = 0; i_ < N; ++i_) {
				swap(I[i_], I[rand() % N]);
			}
