					}
					if (ii == N)break;
					n[j][(a(ii, j) - 1) / M]--;
					n[j][(a(ii, jj) - 1) / M]++;
					n[jj][(a(ii, j) - 1) / M]++;
					n[jj][(a(ii, jj) - 1) / M]--;
					std::swap(a(ii, j), a(ii, jj));
