using Box = vector<vector<int>>;
using pi = pair<int, int>;

int N, M;

inline int id(int box_id, int x)
{
    return box_id * M + x + 1;
}
inline int boxid(int y, int x)
{
    return y * M + x;
}
void box_const(togasat::Solver& solver, Box& A)
{
    //各マスにM枚中ちょうど1枚が入る
    rep(i, N * M)
    {
        vector<int> box;
        rep(j, M) {box.emplace_back(id(i, j));}
        solver.addClause(box);
        rep(j, M)repi(k, j + 1, M)
        {
            vector<int> twice = {-box[j], -box[k]};
            solver.addClause(twice);
        }
    }
    rep(i, N)rep(j, M)rep(k, M)repi(l, k + 1, M)
    {
        int x = boxid(i, k);
        int y = boxid(i, l);
        vector<int> twice = {-id(x, j), -id(y, j)};
        solver.addClause(twice);
    }
}
void vert_const(togasat::Solver& solver, Box& A)
{
    //縦には同じに系列中ちょうど1枚が入る

    //y行におけるp行系列の存在場所
    vector<pi> G[N];
    rep(i, N)rep(j, M)
    {
        int p = A[i][j] / M;
        G[p].push_back(make_pair(i, j));
    }

    rep(p, M)rep(s, G[p].size())repi(t, s + 1, G[p].size())rep(j, M)
    {
        int a = G[p][s].first;
        int b = G[p][t].first;
        int x = boxid(a, j);
        int y = boxid(b, j);
        vector<int> twice = {-id(x, G[p][s].second), -id(y, G[p][t].second)};
        solver.addClause(twice);
    }

}
void solve()
{
    cin >> N >> M;
    Box A(N, vector<int>(M));
    rep(i, N) rep(j, M) {cin >> A[i][j]; A[i][j]--;}

    togasat::Solver solver;
    box_const(solver, A);
    vert_const(solver, A);
    auto status = solver.solve();

    Box B(N, vector<int>(M));
    rep(i, N)rep(j, M)rep(k, M)
    {
        int b = boxid(i, j);
        int ID = id(b, k);
        if(solver.assigns[ID-1]==0)
        {
            B[i][j] = A[i][k];
            break;
        }
    }
    Box C(N, vector<int>(M));
    rep(i, N)rep(j, M)
    {
        int p = B[i][j] / M;
        C[p][j] = B[i][j];
    }

    rep(i, N)
    {
        rep(j, M)
        {
            cout << (B[i][j] + 1) << " ";
        }
        cout << "\n";
    }
    rep(i, N)
    {
        rep(j, M)
        {
            cout << (C[i][j] + 1) << " ";
        }
        cout << "\n";
    }


}

