using namespace std;
namespace NF
{
    int N=0,S=1,T=2;
    int las[maxn],to[maxn],pre[maxn],len[maxn],dis[maxn],cnt[maxn],inc=1;
    void ins(int a,int b,int c){pre[++inc]=las[a],las[a]=inc,to[inc]=b,len[inc]=c;}
    int dfs(int u,int flow)
    {
        int v,temp,delta;
        if(u==T) return flow;
        delta=0;
        for(v=las[u];v;v=pre[v]) 
        {
            if(len[v]>0&&dis[u]==dis[to[v]]+1) 
            {
                temp=dfs(to[v],min(flow-delta,len[v]));
                len[v]-=temp,len[v^1]+=temp,delta+=temp;
                if(delta==flow||dis[S]>=N) return delta;
            }
        }
        if(dis[S]>=N) return delta;
        if(!--cnt[dis[u]]) dis[S]=N;
        cnt[++dis[u]]++;
        return delta;
    }
    int Solve()
    {
        int ret=0;
        while(dis[S]<N) ret+=dfs(1,1e9);
        return ret;
    }
    void Init()
    {
    	for(int i=1;i<=N;i++) las[i]=cnt[i]=dis[i]=0;
    	inc=1,N=0;
	}
}
