void roll(ll a[]) {
    ll tmp = a[0];
    for (int i = 0; i < m - 1; i++) {
        a[i] = a[i + 1];
    }
    a[m - 1] = tmp;
}

bool ok(ll k) {
    int used[105][105] = {};

    for (int i = 0; i <= k; i++) {
        for (int j = 0; j < m; j++) {
            ll r = (a[i][j] - 1) / m;

            if (used[j][r]) return false;
            used[j][r] = true;
        }
    }

    return true;
}

