bool dfs (int x, const vector<vector<vector<int>>> &cnt, vector<int> &match, vector<int> &rev_match, vector<char> &used)
{
    if (used[x])
        return false;
    used[x] = 1;

    for (int i = 0; i < int(cnt[x].size()); i++)
    if (!cnt[x][i].empty())
    if (match[i] == -1 || dfs(match[i], cnt, match, rev_match, used))
    {
        match[i] = x;
        rev_match[x] = i;
        return true;
    }

    return false;
}

