using namespace std;
using ll = long long;
using vi = vector<ll>;
using pi = pair<ll, ll>;
const int maxn = 2e2 + 6;//, mod = 1e9 + 7;
struct Edge {
	int u, v, flow = 0, cap;
	Edge(int u, int v, int cap) : u(u), v(v), cap(cap) {
	}
};
int match[maxn];
struct Dinic {// 0 indexed
	int n, m, s, t;
	vector<Edge> edges;
	vector<vi> g;
	vi lst, lvl;
	Dinic(int n, int s, int t) :n(n), s(s), t(t) {
		m = 0;
		g.resize(n);
		lst.resize(n);
		lvl.resize(n);
	}
	void add_edge(int u, int v, int cap) {
		edges.pb(Edge(u, v, cap));
		edges.pb(Edge(v, u, 0));
		g[u].pb(m++);
		g[v].pb(m++);
	}
	bool bfs() {
		queue<int> q;
		fill(all(lvl), -1);
		lvl[s] = 0;
		q.push(s);
		while(!q.empty()) {
			int u = q.front();
			q.pop(); 
			for(auto i : g[u]) {
				if(lvl[edges[i].v]!=-1) continue;
				if(edges[i].cap-edges[i].flow<1) continue;
				lvl[edges[i].v] = lvl[u]+1;
				q.push(edges[i].v);
			}
		}
		return lvl[t] != -1;
	}
	int dfs(int v, int mn) {
		if(mn==0) return 0;
		if(v==t) return mn;
		for(ll &i = lst[v]; i < g[v].size(); i++) {
			int x = g[v][i];
			int u = edges[x].v;
			if(lvl[u] != lvl[v]+1||edges[x].cap-edges[x].flow<1) continue;
			int t = dfs(u, min(mn, edges[x].cap-edges[x].flow));
			if(!t) continue;
			edges[x].flow += t;
			edges[x^1].flow -= t;
			return t;
		}
		return 0;
	}
	int solve() {
		int flow = 0;
		while(true) {
			if(!bfs()) break;
			fill(all(lst), 0);
			while(int f = dfs(s, 1e9)) {
				flow += f;
				fill(all(lst), 0);
			}
		}
        int N = (n-2)/2;
		for(auto i : edges) {
			if(i.flow==1&&i.u>1&&i.v>1) {
				if(i.u>i.v) swap(i.u, i.v);
				//assert();
				//cout << i.u << " " << i.v << "edge\n";
				match[i.u-2] = i.v-2-N;
			}
		}
		return flow;
	}
};
int n, m;
int mat[maxn][maxn];
map<int, int> cnt[maxn];
set<int> h[maxn];
void gay_sort(int x) {
	for(int _ = 0; _ < n; _++)
		for(int i = 1; i < n; i++)
			if(mat[i][x]<mat[i-1][x]) swap(mat[i][x], mat[i-1][x]);
}
