		Dinic d(n + n + 2, 0, 1);// n rows + n colours + s + t
		for(int i = 0; i < n; i++) d.add_edge(0, 2+i, 1);
		for(int i = 0; i < n; i++) d.add_edge(2+n+i, 1, 1);
