			for(auto x : h[j]) {
				d.add_edge(2+j, 2+n+x/m, 1);
			}
		}
		d.solve();
		for(int j = 0; j < n; j++) {
			for(auto x : h[j]) {
				if(x/m==match[j]) {mat[j][i] = x;break;}
			}
			h[j].erase(mat[j][i]++);
