bool dfs(int v, vector<vector<int>>& mat, vector<char>& used, vector<int>& rpair) {
    used[v] = 1;

    for (int u = 0; u != SZ(mat); ++u)
        if (mat[v][u] != -1 and rpair[u] == -1) {
            rpair[u] = v;
            return true;
        }

    for (int u = 0; u != SZ(mat); ++u)
        if (mat[v][u] != -1 and not used[rpair[u]] and dfs(rpair[u], mat, used, rpair)) {
            rpair[u] = v;
            return true;
        }

    return false;
}

