bool bfs(){
	int std=h[fin]+3;
	h[st]=std;
	int hd=0,tl=0;
	q[tl++]=st;
	while(hd!=tl){
		int x=q[hd++];
		if(x==fin)break;
		for(int pos=p[x];pos;pos=e[pos].xt){
			if(!e[pos].rem)continue;
			int cur=e[pos].to;
			if(h[cur]<std){
				h[cur]=h[x]+1;
				q[tl++]=cur;
			}
		}
	}
	return h[fin]>std;
}
int dfs(int x,int f){
	if(x==fin)return f;
	int res=0;
	for(int &pos=g[x];pos;pos=e[pos].xt){
		if(!e[pos].rem)continue;
		int cur=e[pos].to;
		int tp=dfs(cur,min(e[pos].rem,f));
		if(tp){
			f-=tp,res+=tp;
			e[pos].rem-=tp;
			e[pos^1].rem+=tp;
		}
		if(!f){
			break;
		}
	}
	return res;
}
