		}
	}

	S = 2*n, T = 2*n+1;
	for(int z = 0; z < m; z++){

		for(int i = 0; i <= T; i++) G[i].clear();
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				if(vec[i][j].size() > 0) add_edge(j, n+i, 1);
			}
		}
		for(int i = 0; i < n; i++) add_edge(S, i, 1), add_edge(n+i, T, 1);

		llint ans = 0, flow;
		while(1){
			bfs(S);
			if(level[T] >= inf) break;
			for(int i = 0; i <= T; i++) iter[i] = 0;
			while(1){
				flow = dfs(S, inf);
				if(flow <= 0) break;
				ans += flow;
			}
		}

		for(int i = 0; i < n; i++){
			for(int j = 0; j < G[i].size(); j++){
				int v = G[i][j].to;
				if(G[i][j].cap > 0 || v < n || v >= 2*n) continue;
				v -= n;
				b[v][z] = vec[v][i].back(), vec[v][i].pop_back();
			}
		}
	}

	for(int i = 0; i < n; i++){
