void solve() {
  int n, m; cin >> n >> m;
  Graph<int> a(n, vi(m)); cin >> a;

  Spacial<int> g(n, Graph<int>(n));
  rep(i,0,n) {
    for(auto &x : a[i]) {
      g[i][(x - 1) / m].emplace_back(x);
    }
  }

  Graph<int> b(n);

  rep(_,0,m) {
    vector<set<int>> rest(n);
    rep(i,0,n) {
      rep(j,0,n) {
        if(!g[i][j].empty()) {
          rest[i].emplace_hint(rest[i].end(), j);
        }
      }
    }

    vi pos(n, -1);
    vi val(n, -1);

    rep(i,0,n) {
      queue<int> q;
      q.emplace(i);
      vi from(n, -1);

      while(!q.empty()) {
        int v = q.front(); q.pop();

        for(auto x : rest[v]) {
          from[x] = val[v];

          if(pos[x] == -1) {
            pos[x] = i;

            while(from[x] != -1) {
              swap(pos[x], pos[from[x]]);
              val[pos[x]] = x;
              rest[pos[x]].erase(x);
              rest[pos[x]].emplace(x = from[x]);
            }

            val[i] = x;
            rest[i].erase(x);
            v = -1;
            break;
          }

          q.emplace(pos[x]);
        }

        if(v == -1) break;
      }
    }

    rep(i,0,n) {
      b[i].emplace_back(g[i][val[i]].back());
      g[i][val[i]].pop_back();
    }
  }

  Graph<int> c(n);

  rep(j,0,m) {
    rep(i,0,n) {
      c[(b[i][j] - 1) / m].emplace_back(b[i][j]);
    }
  }

  cout << b << '\n' << c << endl;
}


/* -------- <programs end> -------- */


signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);
  solve();
  return 0;
}

