inline void add_edge(int u,int v,int flow){
	edge[ecnt]=(Edge){v,head[u],flow},head[u]=ecnt++;
	edge[ecnt]=(Edge){u,head[v],0},head[v]=ecnt++;
}

bool bfs(int s,int t){
	memset(dep+1,0,4*t);
	queue<int> Q;dep[s]=1,Q.push(s);
	while(!Q.empty()){
		int u=Q.front();Q.pop();
		for(int i=head[u],v;~i;i=edge[i].next){
			v=edge[i].v;
			if(edge[i].flow&&!dep[v])
				dep[v]=dep[u]+1,Q.push(v);
		}
	}
	return dep[t];
}

int dfs(int u,int flow,const int &t){
	if(u==t)return flow;
	int used=0,rlow;
	for(int v,&i=cur[u];~i;i=edge[i].next){
		v=edge[i].v;
		if(edge[i].flow&&dep[v]==dep[u]+1){
			rlow=dfs(v,min(edge[i].flow,flow-used),t);
			if(rlow)edge[i].flow-=rlow,edge[i^1].flow+=rlow,used+=rlow;
			if(used==flow)break;
		}
	}
	if(!used)dep[u]=-1;
	return used;
}

