int if_swap(int i, int x, int y){
    int p = a[i][x], q = a[i][y];
    int diff = 0;
    diff -= cnt[x][p/m]*cnt[x][p/m];
    diff -= cnt[x][q/m]*cnt[x][q/m];
    diff -= cnt[y][p/m]*cnt[y][p/m];
    diff -= cnt[y][q/m]*cnt[y][q/m];
    --cnt[x][p/m];++cnt[x][q/m];
    --cnt[y][q/m];++cnt[y][p/m];
    diff += cnt[x][p/m]*cnt[x][p/m];
    diff += cnt[x][q/m]*cnt[x][q/m];
    diff += cnt[y][p/m]*cnt[y][p/m];
    diff += cnt[y][q/m]*cnt[y][q/m];
    ++cnt[x][p/m];--cnt[x][q/m];
    ++cnt[y][q/m];--cnt[y][p/m];
    return diff;
}

int do_swap(int i, int x, int y){
    int p = a[i][x], q = a[i][y];
    int diff = 0;
    diff -= cnt[x][p/m]*cnt[x][p/m];
    diff -= cnt[x][q/m]*cnt[x][q/m];
    diff -= cnt[y][p/m]*cnt[y][p/m];
    diff -= cnt[y][q/m]*cnt[y][q/m];
    --cnt[x][p/m];++cnt[x][q/m];
    --cnt[y][q/m];++cnt[y][p/m];
    diff += cnt[x][p/m]*cnt[x][p/m];
    diff += cnt[x][q/m]*cnt[x][q/m];
    diff += cnt[y][p/m]*cnt[y][p/m];
    diff += cnt[y][q/m]*cnt[y][q/m];
    swap(a[i][x], a[i][y]);
    return diff;
}
struct Xor128{
    unsigned x,y,z,w;

    Xor128(unsigned w_=88675123):x(123456789),y(362436069),z(521288629),w(w_){};

    inline unsigned xor128(){
        unsigned t;
        t = x^(x<<11);
        x = y;
        y = z;
        z = w;
        return w = (w^(w>>19))^(t^(t>>8));
    }

    int nextInt(int x,int y){
        if(x>y)swap(x,y);
        return xor128()%(y-x)+x;
    }

    double nextDouble(double a,double b){
        return (double)(xor128()&0xffff)/0xffff*(b-a)+a;
    }

};

