        : n(n), INF(INF), ZERO(ZERO), G(n), level(n), iter(n) {}
    void addEdge(int from, int to, T cap) {
        G[from].push_back({to, (int) G[to].size(), cap, false});
        G[to].push_back({from, (int) G[from].size() - 1, ZERO, true});
    }
    void bfs(int s) {
        fill(level.begin(), level.end(), -1);
        std::queue<int> que;
        level[s] = 0;
        que.push(s);
        while (!que.empty()) {
            int v = que.front();
            que.pop();
            for (int i = 0; i < G[v].size(); i++) {
                edge &e = G[v][i];
                if (e.cap > ZERO && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }
    T dfs(int v, int t, T f) {
        if (v == t) { return f; }
        for (int &i = iter[v]; i < G[v].size(); i++) {
            edge &e = G[v][i];
            if (level[v] < level[e.to] && e.cap > ZERO) {
                T d = dfs(e.to, t, std::min(f, e.cap));
                if (d > ZERO) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return ZERO;
    }
    T calcMaxFlow(int s, int t, T lim) {
        T flow = ZERO;
        while (true) {
            bfs(s);
            if (level[t] < 0 || lim == ZERO) { return flow; }
            fill(iter.begin(), iter.end(), 0);
            T f;
            while ((f = dfs(s, t, lim)) > ZERO) {
                flow += f;
                lim -= f;
            }
        }
    }
    T calcMaxFlow(int s, int t) { return calcMaxFlow(s, t, INF); }
    vpint getMaxFlow() {
        vpint ret;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < G[i].size(); j++) {
                edge &e = G[i][j];
                if (e.isRev&&e.cap!=0) { ret.push_back({e.to, i}); }
            }
        }
        return ret;
    }
    std::map<std::pair<int, int>, T> getMinCut(int s) {
        std::map<std::pair<int, int>, T> ret;
        std::vector<int> visited(n);
        std::queue<int> que;
        que.push(s);
        while (!que.empty()) {
            int v = que.front();
            que.pop();
            if (visited[v]) { continue; }
            visited[v] = true;
            for (int i = 0; i < G[v].size(); i++) {
                edge &e = G[v][i];
                if (e.cap > ZERO) { que.push(e.to); }
            }
        }
        for (int i = 0; i < n; i++) {
            if (visited[i]) { continue; }
            for (int j = 0; j < G[i].size(); j++) {
                edge &e = G[i][j];
                if (e.isRev && visited[e.to]) { ret[{e.to, i}] = e.cap; }
            }
        }
        return ret;
    }
};

