bool kuhn(int v)
{
	if (U[v])
		return 0;

	U[v] = 1;

	for(auto i: g[v])
		if (mt[i] == -1)
		{
			mt[i] = v;
			return 1;
		}

	for(auto i: g[v])
		if (kuhn(mt[i]))
		{
			mt[i] = v;
			return 1;
		}

	return 0;
}

