{
	FOR(i, 0, N)
		g[i].clear();

	FOR(i, 0, m)
		FOR(j, 0, m)
			if (!used[i][row[j] / m])
				g[i].PB(j);

	go_kuhn();
	VI bulo = row;
	FOR(i, 0, m)
		row[mt[i]] = bulo[i];

	FOR(i, 0, m)
	{
		assert(!used[i][row[i] / m]);
		used[i][row[i] / m] = 1;
	}
}

