int main() {
    ll n, m;
    std::cin >> n >> m;
    auto am = make_v<ll>(0, n, m);
    for (auto &&v : am) for (auto &&e : v) {
        std::cin >> e;
        e--;
    }
    auto bm = am;

    std::map<pll, std::set<ll>> edges;
    for (ll i = 0; i < n; i++) for (ll j = 0; j < m; j++) {
        ll v = am[i][j];
        edges[pll(i, v / m)].insert(v);
    }
    for (ll i = 0; i < m; i++) {
        flow::BipartiteMatching<flow::Dinic, graph::FlowGraph<true>, true> bim(n, n);
        for (auto &&e : edges) {
            ll a, b;
            std::tie(a, b) = e.first;
            bim.add_edge(a, b);
        }
        bim.solve();
        auto res = std::move(bim.extract());
        for (auto &&e : res) {
            ll a, b;
            std::tie(a, b) = e;
            auto &st = edges[pll(a, b)];
            bm[a][i] = *st.begin();
            st.erase(st.begin());
            if (st.empty()) edges.erase(pll(a, b));
        }
    }

    auto output = [&] {
        for (ll i = 0; i < n; i++) for (ll j = 0; j < m; j++) std::cout << bm[i][j] + 1 << " \n"[j + 1 == m];
    };

    output();

    for (ll j = 0; j < m; j++) {
        vec<ll> tmp(n);
        for (ll i = 0; i < n; i++) tmp[i] = bm[i][j];
        std::sort(ALL(tmp));
        for (ll i = 0; i < n; i++) bm[i][j] = tmp[i];
    }

    output();

    return 0;
}

