	{ gr[u][v].push_back(c), gr[v][u].push_back(c); }
int match[MAXN<<2];
bool vis[MAXN<<2];
inline bool dfs(int u)
{
	for(int i = n+1; i<=2*n; i++)
		if(!vis[i]&&!gr[u][i].empty())
		{
			vis[i] = true;
			if(match[i]<0||dfs(match[i]))
			{
				match[i] = u;
				return true;
			}
		}
	return false;
}
inline int calc(int x)
	{ return (x-1)/m+1; }
