		for(int j = 1; j<=n; j++)
			tmp[j] = ansb[j][i];
		sort(tmp+1,tmp+n+1);
		for(int j = 1; j<=n; j++)
			ansc[j][i] = tmp[j]; 
	}
	for(int i = 1; i<=n; i++)
	{
		for(int j = 1; j<=m; j++)
			cout << ansb[i][j] << " ";
		cout << endl;
	}
	for(int i = 1; i<=n; i++)
	{
		for(int j = 1; j<=m; j++)
