int a[maxn][maxn],b[maxn][maxn],c[maxn][maxn],n,m,p[maxn],fre[maxn],cnt=0,been[maxn][maxn];
pii g[maxn][maxn];

bool visit(int u) {
    if (fre[u]!=cnt) fre[u]=cnt;
    else return false;
    for (int v=0;v<n;v++)
        if (g[u][v].fi==1) {
            if (p[v]==-1||visit(p[v])) {
                p[v]=u;
                return true;
            }
        }
    return false;
}

