        for (int i=0;i<n;i++) {
            for (int j=0;j<m;j++) g[i][j]=pii(-1,-1);
            p[i]=-1;
        }
        for (int i=0;i<n;i++)
            for (int j=0;j<m;j++)
                if (!been[i][j]) g[i][a[i][j]/m]=pii(1,j);
       // if (cnt==3) cout<<g[2][2].fi<<endl;
        int num=0;
        for (int i=0;i<n;i++) {
            cnt++;
            num+=visit(i);
        }
        //cout<<endl;
        for (int i=0;i<n;i++) {
            int row = p[i];
            //cout<<row<<" "<<i<<endl;
            b[row][col] = a[row][g[row][i].se]+1;
            c[i][col] = a[row][g[row][i].se]+1;
            been[row][g[row][i].se]=1;
            //cout<<row<<" "<<g[row][i].se<<" "<<i<<endl;
