namespace DINIC { // Max Flow
	struct Edge {
		int to;
		long long dis; 
		int nxt;
	} e[Maxm << 1];
	int head[Maxn], cnt;
	inline void clear() {
		memset(head, 0, sizeof (head));
		cnt = 1; 
	}
	inline void add_edge(int u, int v, long long flow) {
		e[++cnt] = (Edge){v, flow, head[u]}, head[u] = cnt;
		e[++cnt] = (Edge){u, 0, head[v]}, head[v] = cnt;
	}
	int dis[Maxn], cur[Maxn];
	int que[Maxn], qh, qe;
	bool bfs(int s, int t) {
		memset(dis, 0, sizeof (dis));
		memcpy(cur, head, sizeof (cur));
		qh = qe = 0, que[qe++] = s;
		dis[s] = 1;
		while (qh < qe) {
			int u = que[qh++], v;
			for (int i = head[u]; i; i = e[i].nxt)
				if (!dis[v = e[i].to] && e[i].dis)
					dis[v] = dis[u] + 1, que[qe++] = v;
		}
		return dis[t];
	}
	long long dfs(int u, int t, long long limit) {
		if (u == t || !limit) return limit;
		int v; long long res = 0, p;
		for (int &i = cur[u]; i && limit; i = e[i].nxt)
			if (dis[v = e[i].to] == dis[u] + 1 && e[i].dis > 0) {
				p = dfs(v, t, min(limit, e[i].dis));
				e[i].dis -= p, e[i ^ 1].dis += p, res += p;
				if (res >= limit) break;
			}
		return res;
	}
	long long dinic(int s, int t) {
		long long res = 0;
		while (bfs(s, t))
			res += dfs(s, t, 0x3f3f3f3f3f3f3f3f);
		return res;
	}
}

