// Choose unvisited x and visited y as minimum vertex cover
// Also, Maximum Independent Set is the complement set of minimum vertex cover
template<int SZX,int SZY> struct BIPARTITE_MATCHING{
	int mx[SZX+1],my[SZY+1],lev[SZX+1],visx[SZX+1],visy[SZY+1];
	vector<int> e[SZX+1];
	bool dfs(int x){
		for(int y:e[x]){
			int w=my[y];
			if(w==-1||(lev[w]==lev[x]+1&&dfs(w)))
				return mx[x]=y,my[y]=x,true;
		}
		return lev[x]=-1,false;
	}
	void clear(int m){for(int i=0;i<=m;i++)	vector<int>().swap(e[i]);}
	void addedge(int x,int y){e[x].emplace_back(y);}
	int matching(int m,int n){
		fill(mx,mx+m+1,-1),fill(my,my+n+1,-1);
		for(int res=0;;){
			queue<int> q;
			for(int i=0;i<m;i++)
				if(mx[i]==-1)	q.emplace(i),lev[i]=0;
				else	lev[i]=-1;
			while(!q.empty()){
				int x=q.front();q.pop();
				for(int y:e[x]){
					int w=my[y];
					if(w!=-1&&lev[w]==-1)
						q.emplace(w),lev[w]=lev[x]+1;
				}
			}
			int delta=0;
			for(int i=0;i<m;i++)
				if(mx[i]==-1&&dfs(i))
					delta++;
			if(delta)	res+=delta;
			else	return res;
		}
		return 0;
	}
	int cover(int m,int n){
		int res=matching(m,n);
		fill(visx+1,visx+m+1,0), fill(visy+1,visy+n+1,0);
		queue<int> q;
		for(int i=1;i<=m;i++)	if(mx[i]==-1)	q.emplace(i),visx[i]=true;
		while(!q.empty()){
			int x=q.front();q.pop();
			for(int y:e[x]){
				visy[y]=true;
				int w=my[y];
				if(!visx[w])	q.emplace(w),visx[w]=true;
			}
		}
		return res;
	}
};
