using namespace std;

struct BipartiteGraph
{
	vector<int> leftMatch, rightMatch, lab, seen;
	vector<vector <int>> a;
	int m, n;

	BipartiteGraph() {}
	BipartiteGraph(int m, int n)
	{
		this -> m = m;
		this -> n = n;
		a = vector<vector<int>>(m);
		leftMatch = vector<int>(n, -1);
		rightMatch = vector<int>(m, -1);
		lab = vector<int>(m, -1);
		seen = vector<int>(n, 0);
	}

	void addEdge(int x, int y)
	{
		a[x].push_back(y);
	}

	int findMatch(int x)
	{
		for (int i = 0; i < int(a[x].size()); i++)
		{
			int y = a[x][i];
			if (seen[y]) continue;
			seen[y] = 1;
			if (leftMatch[y] < 0 || findMatch(leftMatch[y]))
			{
				leftMatch[y] = x; rightMatch[x] = y;
				return 1;
			}
		}
		return 0;
	}

	int maxMatching()
	{
		for (int i = 0; i < m; i++) lab[i] = i;
		while (1)
		{
			int lastM = m;
			for (int i = 0; i < n; i++) seen[i] = 0;
			for (int i = m - 1; i >= 0; i--)
				if (findMatch(lab[i])) lab[i] = lab[--m];
			if (lastM == m) break;
		}
		int match = 0;
		for (int i = 0; i < n; i++) match += (leftMatch[i] >= 0);
		return match;
	}
};

