{
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	int n,m,i,j,k;
	cin>>n>>m;
	for(i=0;i<n;i++)
		for(j=0;j<m;j++)
		{
			cin>>a[i][j];
			br[j][(a[i][j]-1)/m]++;
		}
	MAXFLOW<int>f;
	int b[N];
	for(i=0;i<n;i++)
	{
		for(j=0;j<m;j++)
		{
			b[j]=a[i][j];
			for(k=0;k<m;k++)
				if(br[k][(a[i][j]-1)/m]==0)
				{
					f.add_edge(j,m+k,1);
					f.add_edge(m+k,j,0);
				}
			if(br[j][(a[i][j]-1)/m]==1)
			{
				f.add_edge(j,m+j,1);
				f.add_edge(m+j,j,0);
			}
			f.add_edge(m+m,j,1);
			f.add_edge(j,m+m,0);
			f.add_edge(m+j,m+m+1,1);
			f.add_edge(m+m+1,m+j,0);
		}
		for(j=0;j<m;j++)
			br[j][(a[i][j]-1)/m]--;
		vector<pair<int,int> > d=f.maching(m+m,m+m+1);
		for(j=0;j<(int)d.size();j++)
		{
			a[i][d[j].second-m]=b[d[j].first];
			br[d[j].second-m][(a[i][d[j].second-m]-1)/m]++;
