bool c[maxn + 10][maxn + 10];
int lk[maxn + 10], d[maxn + 10];
bool vis[maxn + 10];
bool ban[maxn + 10][maxn + 10];

bool cmp(int x, int y) {
	return (x - 1) / m + 1 < (y - 1) / m + 1;
}

bool dfs(int p) {
	for (int i = 1; i <= n; ++i)
		if (c[p][i] && !vis[i]) {
			vis[i] = 1;
			if (!lk[i] || dfs(lk[i])) {
				lk[i] = p; return 1;
			}
		}
	return 0;
}

int main() {
	scanf("%d%d", &n, &m);
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j) scanf("%d", &a[i][j]);
	for (int i = 1; i <= m; ++i) {
		memset(c, 0, sizeof c);
		memset(lk, 0, sizeof lk);
		for (int j = 1; j <= n; ++j)
			for (int k = 1; k <= m; ++k)
				if (!ban[j][k])
					c[j][(a[j][k] - 1) / m + 1] = 1;
		for (int j = 1; j <= n; ++j)
			if (!lk[j]) {
				memset(vis, 0, sizeof vis);
				assert(dfs(j));
			}
		for (int j = 1; j <= n; ++j) {
			int pos = lk[j];
			for (int k = 1; k <= m; ++k)
				if (!ban[pos][k] && (a[pos][k] - 1) / m + 1 == j) {
					ban[pos][k] = 1;
					b[pos][i] = a[pos][k];
					break;
				}
		}
