			d[j] = b[j][i];
		sort(d + 1, d + n + 1, cmp);
		for (int j = 1; j <= n; ++j)
			b[j][i] = d[j];
	}
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
