const int MAXD = 256;

int gf[MAXD], bf[MAXD];
bool vis[MAXD];
multiset<int> e[MAXD];
vc<pii> nums[MAXN][MAXN];

bool Dfs( int pos ){
	vis[pos] = 1;
	for( auto v : e[pos] ){
		if(vis[bf[v]]) continue;
		if( !bf[v] or Dfs(bf[v]) ){
			bf[v] = pos;
			gf[pos] = v;
			return true;
		}
	}
	return false;
}

void Match(){
	Ms(gf); Ms(bf);
	For(i,n){
		Ms(vis);
		bool succeed = Dfs(i);
		assert(succeed);
	}
}

void SectionI(){
	For(i,n) For(j,m){
		e[i].insert(a[i][j].F);
		nums[i][a[i][j].F].Pb(a[i][j]);
	}
	For(col,m){
		Match();
		For(i,n){
			int use = gf[i];
			a[i][col] = nums[i][use].back();
			nums[i][use].pop_back();
			e[i].erase(e[i].find(use));
		}
		// Dbg();
	}
	PrintAns();
	Dbg();
}

void SectionII(){
	For(col,m){
		static vc<pii> tmp;
		tmp.clear();
		For(i,n) tmp.Eb(a[i][col]);
		sort(All(tmp),[]( const pii &a , const pii &b ){ return a.F < b.F; });
		For(i,n) a[i][col] = tmp[i-1];
	}
	PrintAns();
	Dbg();
}

