void flush(vector<vector<int>> const &V)
{
  assert(!V.empty());
  for (auto j = size_t{0}; j < V[0].size(); j++)
  {
    for (auto i = size_t{0}; i < V.size(); i++)
    {
      cout << V[i][j] + 1;
      if (i < V.size() - 1)
      {
        cout << " ";
      }
      else
      {
        cout << endl;
      }
    }
  }
}

int main()
{
  int N, M;
  cin >> N >> M;
  vector<vector<int>> A(N, vector<int>(M));
  for (auto i = 0; i < N; i++)
  {
    for (auto j = 0; j < M; j++)
    {
      cin >> A[i][j];
      A[i][j]--;
    }
  }
  Bipartite<> graph(2 * N);
  for (auto i = 0; i < N; i++)
  {
    for (auto j = 0; j < M; j++)
    {
      graph.add_edge(i, A[i][j] / M + N, A[i][j]);
    }
  }
  vector<vector<int>> B(M, vector<int>(N));
  for (auto i = 0; i < M; i++)
  {
    assert(graph.bipartite_matching() == N);
    for (auto ptr : graph.matching())
    {
      if (ptr->from < N)
      {
        B[i][ptr->from] = ptr->id;
      }
    }
  }
  auto C = B;
  for (auto i = 0; i < M; i++)
  {
    sort(C[i].begin(), C[i].end());
  }
  flush(B);
  flush(C);
}

