inline int col(int x){
	if(x%m==0)return x/m;
	return x/m+1;
}

int S,T;
int Q[V],hd,tl,d[V];
bool bfs(){
	memset(d,-1,sizeof(int)*(2*n+3));
	d[S]=0;
	hd=tl=0;
	Q[tl++]=S;
	while(hd<tl){
		int u=Q[hd];
		hd++;
		for(int i=head[u];i;i=nxt[i])
		    if(w[i]&&d[v[i]]==-1){
		    	d[v[i]]=d[u]+1;
		    	Q[tl++]=v[i];
				if(v[i]==T)return true; 
			}
	}
	return false;
}
int dfs(int u,int flow){
	if(u==T||!flow)return flow;
	int ans=0,res;
	for(int &i=head[u];i;i=nxt[i])
	   if(w[i]&&d[v[i]]==d[u]+1&&(res=dfs(v[i],min(flow,w[i])))){
	   	    w[i]-=res;
	   	    if(i&1)w[i+1]+=res;
	   	    else w[i-1]+=res;
	   	    ans+=res;
	   	    flow-=res;
	   	    if(!flow)break;
	   }
	return ans;
}

