const int Q=505,P=1<<20;
int las[Q],e[P],nn[P],c[P],inc;
int S,T;
int cnt[Q],dis[Q];
int Sap(int x,int fl)
{
    if(x==T)return fl;
    int had=0;
    for(int t=las[x];t;t=nn[t]){
        int y=e[t];
        if((!c[t])||dis[x]-1!=dis[y])continue;
        int res=Sap(y,min(c[t],fl-had));
        had+=res,c[t]-=res,c[t^1]+=res;
        if(had==fl||dis[S]>=T)return had;
    }
    --cnt[dis[x]];
    if(!cnt[dis[x]])dis[S]=T;
    cnt[++dis[x]]++;
    return had;
}
void iNS(int x,int y,int z)
{
    e[++inc]=y;
    nn[inc]=las[x];
    las[x]=inc;
    c[inc]=z;
}
void ins(int x,int y,int z)
{iNS(x,y,z),iNS(y,x,0);}
