                if(!uz[a[i][j]])
                    ins(i,(a[i][j]-1)/m+1+n,1);
        for(int i=1;i<=n;i++)
            ins(S,i,1),ins(i+n,T,1);
        int ch=0;
        while(dis[S]<T)ch+=Sap(S,(int)1e9);
        assert(ch==n);
        int now=1;
        for(int i=1;i<=n;i++){
            for(int j=1;j<=m;j++)
                if(!uz[a[i][j]]){
                    now+=2;
                    if(c[now]){
                        uz[a[i][j]]=1;
                        b[i][p]=a[i][j];
                    }
                }
        }
    }
    for(int i=1;i<=n;i++,puts(""))
        for(int j=1;j<=m;j++)
            printf("%d ",b[i][j]);
    for(int j=1;j<=m;j++){
        for(int i=1;i<=n;i++)
            cc[i]=b[i][j];
        sort(cc+1,cc+n+1);
        for(int i=1;i<=n;i++)
            b[i][j]=cc[i];
    }
    for(int i=1;i<=n;i++,puts(""))
        for(int j=1;j<=m;j++)
            printf("%d ",b[i][j]);
    return 0;
}

