#include <bits/stdc++.h>
using namespace std;
const int MN = 105;
const int INF = 1e9;
int N,M,A[MN],B[MN],dist[MN],D[MN][MN],L[MN][MN];
bool used[MN],ch[MN][MN];
vector<int> G[MN],V[MN];

bool cmp(int A, int B)
{
    return (A-1)/M<(B-1)/M;
}

void bfs(){
    queue<int> Q;
    for(int i=0; i<N; i++){
        if(!used[i]){
            dist[i] = 0;
            Q.push(i);
        }
        else dist[i] = INF;
    }
    while(!Q.empty()){
        int a = Q.front();
        Q.pop();
        for(int b: G[a]){
            if(B[b] != -1 && dist[B[b]] == INF){
                dist[B[b]] = dist[a] + 1;
                Q.push(B[b]);
            }
        }
    }
}

bool dfs(int a){
    for(int b: G[a]){
        if(B[b]==-1||dist[B[b]]==dist[a]+1&&dfs(B[b])){
            used[a] = 1;
            A[a] = b;
            B[b] = a;
            return 1;
        }
    }
    return 0;
}

int main()
{
    ios_base::sync_with_stdio(0),cin.tie(0);
    cin >> N >> M;
    for(int i=0; i<N; i++){
        for(int j=0; j<M; j++){
            cin >> D[i][j];
        }
    }
    for(int t=0; t<M; t++){
        for(int i=0; i<N; i++){
            G[i].clear();
            for(int j=0; j<M; j++){
                if(ch[i][j]) continue;
                G[i].push_back((D[i][j]-1)/M);
            }
        }
        int match = 0;
        fill(A,A+MN,-1);
        fill(B,B+MN,-1);
        while(1){
            bfs();
            int flow = 0;
            for(int i=0; i<N; i++)
                if(!used[i] && dfs(i)) flow++;
            if(flow == 0) break;
            match += flow;
        }
        fill(used,used+MN,0);
        for(int i=0; i<N; i++){
            for(int j=0; j<M; j++){
                if(ch[i][j]) continue;
                if(A[i]==(D[i][j]-1)/M){
                    ch[i][j] = 1;
                    L[i][t] = D[i][j];
                    break;
                }
            }
        }
    }
    for(int i=0; i<N; i++){
        for(int j=0; j<M; j++){
            cout << L[i][j] << ' ';
            V[j].push_back(L[i][j]);
        }
        cout << '\n';
    }
    for(int j=0; j<M; j++) sort(V[j].begin(),V[j].end(),cmp);
    for(int i=0; i<N; i++){
        for(int j=0; j<M; j++){
            cout << V[j][i] << ' ';
        }
        cout << '\n';
    }
}

