        {
            l_now++;
            continue;
        }

        vector<int> loop;
        int x = *edges[l_now].begin();

        vector<int> visited(N);
        visited[l_now] = 1;
        loop.push_back(x);
        edges[l_now].erase(x);

        int l = x / M;
        while (l != l_now)
        {
            visited[l] = 1;
            int xx = *edges[l].begin();

            for (auto nx : edges[l])
            {
                if (visited[nx / M] == 0)
                {
                    xx = nx;
                    break;
                }
            }
            edges[l].erase(xx);
            loop.emplace_back(xx);
            l = loop.back() / M;
            if (visited[xx / M]) break;
        }

        reverse(ALL(loop));

        bool flg = true;
        FOR(i, 1, loop.size()) if (Ainv[loop[i]] == Ainv[loop[0]]) flg = false;
