    for(int iter = 0;iter < m;iter++){
        vector<vi> g(0);
        for(int i = 0;i < n;i++){
            vi tmp(0);
            for(int j = 0;j < m;j++){
                if(!vis[i][j]){
                    tmp.push_back(col[i][j]);
                } 
            }
            sort(all(tmp));
            auto it = unique(all(tmp));
            tmp.erase(it, tmp.end());
            g.push_back(tmp);
        }
        vi btoa(n, -1);
        dfsMatching(g, btoa);
        for(int i = 0;i < n;i++){
            int r = btoa[i];
            for(int j = 0;j < m;j++){
                if(!vis[r][j] and col[r][j] == i){
                    vis[r][j] = true;     
                    b[r][iter] = a[r][j];
                    break;
                }
            }
        }
    }
    for(int i = 0;i < n;i++){
        for(int j = 0;j < m;j++){
            col[i][j] = b[i][j] / m;
        }
    } 
    for(int j = 0;j < m;j++){
        for(int i = 0;i < n;i++){
            c[col[i][j]][j] = b[i][j];
        }
    }
    for(int i = 0;i < n;i++){
        for(int j = 0;j < m;j++){
            cout << b[i][j] + 1 << (j == m - 1 ? '\n' : ' ');
        }
    }
    for(int i = 0;i < n;i++){
        for(int j = 0;j < m;j++){
            cout << c[i][j] + 1 << (j == m - 1 ? '\n' : ' ');
        }
    }
    return 0;
}

#include <iostream>
