bool bfs()
{
	int i;
	for(i=1;i<=2*n+2;++i)
		d[i]=1<<30;
	d[2*n+1]=0;
	q[bg=ed=1]=2*n+1;
	while(bg<=ed)
	{
		for(i=head[q[bg]];i;i=nxt[i])
			if(flow[i]<cap[i]&&d[adj[i]]==(1<<30))
			{
				d[adj[i]]=d[q[bg]]+1;
				q[++ed]=adj[i];
			}
		++bg;
	}
	return d[2*n+2]<(1<<30);
}
int dfs(int x,int a)
{
	if(x==2*n+2||a<=0)
		return a;
	int g,h=0;
	for(;cur[x];cur[x]=nxt[cur[x]])
		if(d[adj[cur[x]]]==d[x]+1&&(g=dfs(adj[cur[x]],min(cap[cur[x]]-flow[cur[x]],a)))>0)
		{
			flow[cur[x]]+=g;
			flow[cur[x]&1?cur[x]+1:cur[x]-1]-=g;
			a-=g;
			h+=g;
			if(a<=0)
				break;
		}
	return h;
}
