struct edge { int to, cap, rev; };
typedef vector<edge> vertex;
typedef vector<vertex> graph;

typedef long long i64;
const int inf = (int)1.05e9;

void add_edge(graph& g, int s, int t, int cap)
{
	g[s].push_back({t, cap, (int)g[t].size()});
	g[t].push_back({s, 0, (int)g[s].size() - 1});
}

void compute_level(int s, vector<int>& level, graph& g)
{
	level.resize(g.size());
	fill(level.begin(), level.end(), -1);

	queue<int> q;
	level[s] = 0;
	q.push(s);

	while(!q.empty()) {

		const int v = q.front();
		q.pop();

		for(const auto& e : g[v]) {

			const int w = e.to;
			const int c = e.cap;

			if(c <= 0 || level[w] != -1)
				continue;
			level[w] = level[v] + 1;
			q.push(w);
		}
	}
}

int compute_flow_path(int v, int t, int f, vector<int>& iter, vector<int>& level, graph& g)
{
	if(v == t)
		return f;

	for(int& i = iter[v]; i < (int)g[v].size(); ++i) {

		auto& e = g[v][i];
		const int c = e.cap;
		const int w = e.to;

		if(c <= 0 || level[v] >= level[w])
			continue;

		const int d = compute_flow_path(w, t, min(f, c), iter, level, g);
		if(d <= 0)
			continue;
		e.cap -= d;
		g[w][e.rev].cap += d;
		return d;
	}

	return 0;
}

int max_flow(int s, int t, graph& g)
{
	int flow = 0;
	vector<int> level(g.size());
	vector<int> iter(g.size());

	while(true) {

		compute_level(s, level, g);
		if(level[t] == -1)
			break;
		fill(iter.begin(), iter.end(), 0);
		while(true) {
			const int f = compute_flow_path(s, t, inf, iter, level, g);
			flow += f;
			if(f <= 0)
				break;
		}
	}

	return flow;
}

void show_grid(vector<vector<int>>& as)
{
	for(auto& ad : as) {
		for(int i = 0; i < ad.size(); i++) {
			printf("%d%c", ad[i] + 1, (i + 1) == ad.size() ? '\n' : ' ');
		}
	}
}

int main()
{
	int n, m;
	vector<vector<int>> as;

	scanf("%d%d", &n, &m);
	as.resize(n);
	for(int i = 0; i < n; i++) {
		as[i].resize(m);
		for(int j = 0; j < m; j++) {
			scanf("%d", &as[i][j]);
			as[i][j] -= 1;
		}
	}

	vector<vector<int>> bs, cs;
	graph g;

	bs = as;

	vector<int> q(n * m, 0);
	for(int i = 0; i < n * m; i++) {
		q[i] = i / m;
	}

	for(int line = 1; line < n; line++) {

		g.clear();
		g.resize(2 * m + 2);
		for(int i = 0; i < m; i++) {
			for(int j = 0; j < m; j++) {
				int x = bs[line][j];
				bool ok = true;
				for(int k = 0; k < line; k++) {
					if(q[bs[k][i]] == q[x]) {
						ok = false;
						break;
					}
				}
				if(!ok) {
					continue;
				}
				add_edge(g, i, m + j, 1);
			}
		}
		for(int i = 0; i < m; i++) {
			add_edge(g, 2 * m, i, 1);
			add_edge(g, m + i, 2 * m + 1, 1);
		}

		int f = max_flow(2 * m, 2 * m + 1, g);
		assert(f == m);

		for(int i = 0; i < m; i++) {
			int to = -1;
			for(auto& e : g[i]) {
				if(e.cap == 0) {
					to = e.to - m;
					break;
				}
			}
			assert(to != -1 && to >= 0 && to < m);
			bs[line][i] = as[line][to];
		}
	}

	cs = bs;

	for(int line = 0; line < m; line++) {
		for(int i = 0; i < n; i++) {
			int x = bs[i][line];
			cs[x / m][line] = x;
		}
	}

	show_grid(bs);
	show_grid(cs);

	for(int i = 0; i < n; i++) {
		sort(cs[i].begin(), cs[i].end());
		for(int j = 0; j < m; j++) {
			assert(cs[i][j] == i * m + j);
		}
	}

	return 0;
}

