const int MAXN = 210; // the maximum value of N

int matched[MAXN + 10]; // matched[v] = -1 if v is not matched, else matched[v] == u, where u is the vertice it matched with
bool vis[MAXN + 10]; // vis[v] = have we visited v before?

// the graph. this code assumes that there are N vertices from 1 to N, and the graph is a bipartite graph

// User's duty: the following data's must be filled by you
int N; // the count of nodes
vector<int> G[MAXN + 10]; // the graph, in adjacency list form
// done

// this function tries to match u with another v
// it returns true if its successful, false if its unsuccessful
// Complexity: jani na :P
bool bpm(int u) {
   for(int v : G[u]) {
      // if we've tried v recently, don't try again
      if(vis[v]) continue;
      vis[v] = true;
      // if v is not used, or I can match matched[v] with another vertice
      // then we can match u with v :)
      if(matched[v] == -1 || bpm(matched[v])) {
         matched[v] = u;
         matched[u] = v;
         return true;
      }
   }
   return false;
}

// return the maximum bipartite matching of the graph
// Complexity: Wikipedia says its O(V * E), so...
int maxBPM() {
   // fill matched with -1, that is, every vertice is unmatched at the beginning
   memset(matched, -1, sizeof(matched));
   int rs = 0; // rs is the count of matches
   for(int u = 1; u <= N; u++) {
      memset(vis, 0, sizeof(vis));
      // try to match u with any vertice
      // if its possible, increase rs
      rs += bpm(u);
   }
   return rs;
}


