int cost(int i,int x,int y){
   int w1 = (a[i][x]-1)/m,w2 = (a[i][y]-1)/m;
   if(w1 == w2)return 0;
   int diff = 0;
   diff -= cnt[x][w1]; diff -= cnt[y][w2];
   diff += cnt[x][w2]; diff += cnt[y][w1];
   return diff+2;
}

