	int V, S, T, Head[Max_V], Total, To[Max_E], Next[Max_E], Cap[Max_E], Flow[Max_E];
	inline void Add_Edge(int tot, int s, int t, int c)
	{
		To[tot] = t, Next[tot] = Head[s], Head[s] = tot, Cap[tot] = c, Flow[tot] = 0;
	}
	inline void Add_Link(int s, int t, int c)
	{
		Total += 2, Add_Edge(Total, s, t, c), Add_Edge(Total ^ 1, t, s, 0);
	}
	void clear()
	{
		for (int i = 1;i <= V;++i)
			Head[i] = 0;
		for (int i = 2;i <= Total + 1;++i)
			To[i] = Next[i] = Cap[i] = Flow[i] = 0;
		V = S = T = 0;
	}
	int Cur[Max_V], Q[Max_V], Dist[Max_V];
	bool BFS()
	{
		int l, r;
		for (int i = 1;i <= V;++i)
			Dist[i] = 0;
		Dist[Q[l = r = 1] = S] = 1;
		for (int u;l <= r;)
		{
			if ((u = Q[l++]) == T)
				return true;
			for (int i = Head[u], v;i;i = Next[i])
				if (!Dist[v = To[i]] && Cap[i] > Flow[i])
					Dist[Q[++r] = v] = Dist[u] + 1;
		}
		return false;
	}
	int DFS(int u, int a)
	{
		if (u == T || a == 0)
			return a;
		int Ans(0);
		for (int &i = Cur[u], v, f;i;i = Next[i])
			if (Dist[v = To[i]] == Dist[u] + 1 && (f = DFS(v, min(a, Cap[i] - Flow[i]))) > 0)
			{
				Ans += f, Flow[i] += f, Flow[i ^ 1] -= f;
				if ((a -= f) == 0)
					break;
			}
		return Ans;
	}
	int Dinic()
	{
		int Ans(0);
		while (BFS())
		{
			for (int i = 1;i <= V;++i)
				Cur[i] = Head[i];
			Ans += DFS(S, INF);
		}
		return Ans;
	}
}

