using namespace std;

const int inf=1000000000;

namespace Dinic
{
	int hd[210],cur[210],q[210],l,r,dis[210],cnt,n;
	struct node{int to,next,c;}e[100010];
	void init(int N){n=N,cnt=1,memset(hd,0,sizeof(hd));}
	void addedge(int x,int y,int c)
	{
		e[++cnt]=(node){y,hd[x],c},hd[x]=cnt;
		e[++cnt]=(node){x,hd[y],0},hd[y]=cnt;
	}
	bool bfs()
	{
		q[l=r=1]=1,dis[1]=0;
		for (int i=2; i<=n; i++) dis[i]=-1;
		while (l<=r)
		{
			int x=q[l++];
			for (int i=hd[x]; i; i=e[i].next)
				if (e[i].c&&dis[e[i].to]==-1) dis[q[++r]=e[i].to]=dis[x]+1;
		}
		return dis[n]!=-1;
	}
	int dfs(int x,int f)
	{
		if (x==n) return f;
		for (int &i=cur[x]; i; i=e[i].next) 
			if (e[i].c&&dis[e[i].to]==dis[x]+1)
			{
				int nw=dfs(e[i].to,min(f,e[i].c));
				if (nw) return e[i].c-=nw,e[i^1].c+=nw,nw;
			}
		return 0;
	}
	int solve()
	{
		int ans=0,nw;
		while (bfs())
		{
			for (int i=1; i<=n; i++) cur[i]=hd[i];
			while (nw=dfs(1,inf)) ans+=nw;
		}
		return ans;
	}
}

