                if((a[j][k] - 1) / m == i) {
                    rev[(a[j][k] - 1) % m] = j;
                    REP(l, v.size()) {
                        hk.add_edge((a[j][k] - 1) % m, v[l]);
                    }
                }
            }
        }
        hk.bipartite_matching();
        REP(j, m) {
            b[rev[j]][hk.match[j]] = i * m + j + 1;
        }
    }
    return b;
}

vector<vector<int>> func2(const vector<vector<int>>& b) {
    vector<vector<int>> c(n, vector<int>(m));
    REP(i, m) {
        REP(j, n) {
            c[(b[j][i] - 1) / m][i] = b[j][i];
        }
    }
    return c;
}

