vector<vector<int>> func1(const vector<vector<int>>& a) {
    vector<vector<int>> b(n, vector<int>(m, -1));
    REP(i, n) {
        HopcroftKarp hk(m, m);
        vector<int> rev(m, -1);
        REP(j, n) {
            vector<int> v;
            REP(k, m) {
                if(b[j][k] == -1) v.pb(k);
            }
            REP(k, m) {
                if((a[j][k] - 1) / m == i) {
                    rev[(a[j][k] - 1) % m] = j;
                    REP(l, v.size()) {
                        hk.add_edge((a[j][k] - 1) % m, v[l]);
                    }
                }
            }
        }
        hk.bipartite_matching();
        REP(j, m) {
            b[rev[j]][hk.match[j]] = i * m + j + 1;
        }
    }
    return b;
}

