	int tot=1,head[S],nxt[M],adj[M],w[M],s,t,dep[S],cur[S],q[S],vis[M];
	inline void addedge(ri x,ri y,ri z){
		nxt[++tot]=head[x];
		adj[head[x]=tot]=y;
		w[tot]=z;
	}
	inline void add(ri x,ri y,ri z){
		addedge(x,y,z);
		addedge(y,x,0);
	}
	inline bool bfs(){
		ri l,r,x,i,y;
		for(i=s;i<=t;++i) dep[i]=0,cur[i]=head[i];
		q[l=r=1]=s;
		dep[s]=1;
		while(l<=r){
			x=q[l++];
			for(i=head[x];i;i=nxt[i]){
				if(!vis[i]&&w[i]&&!dep[y=adj[i]])
					dep[y]=dep[x]+1,
					q[++r]=y;
			}
		}
		return dep[t];
	}
	inline int dfs(ri x,ri now){
		if(x==t) return now;
		ri y,tmp,res=0;
		for(int &i=cur[x];i;i=nxt[i])
			if(!vis[i]&&w[i]&&dep[y=adj[i]]==dep[x]+1&&(tmp=dfs(y,min(now,w[i])))){
				w[i]-=tmp;
				w[i^1]+=tmp;
				res+=tmp;
				if(!(now-=tmp)) return res; 
			}
		return res;
	}
	inline void maxflow(){
		while(bfs())
			dfs(s,inf);
	}
