bool neko(std::vector<std::multiset<std::pair<int, int>>>& ms,
          size_t i, std::set<int>& seen, std::vector<int>& res) {

  size_t n = ms.size();
  if (i == n) return true;
  for (auto it = ms[i].begin(); it != ms[i].end(); ++it) {
    if (it->first == 0) continue;
    int p = it->second;
    auto itp = seen.insert(p);
    if (!itp.second) continue;

    res[i] = p;
    // fprintf(stderr, "[%zu] <- %d\n", i, p);
    if (neko(ms, i+1, seen, res)) {
      int m = it->first;
      ms[i].erase(it);
      ms[i].emplace(--m, p);
      return true;
    }

    res[i] = -1;
    seen.erase(itp.first);
  }
  return false;
}

void step1(matrix& a) {
  for (auto& ai: a) std::sort(ai.rbegin(), ai.rend());
  std::vector<std::multimap<int, int>> mmp(a.size());  // [商] => 値
  std::vector<std::map<int, int>> mp(a.size());  // [商] => 個数
  std::vector<std::multiset<std::pair<int, int>>> ms(a.size());  // [個数] => 商
  int n = a.size();
  int m = a[0].size();
  for (size_t i = 0; i < a.size(); ++i) {
    for (size_t j = 0; j < a[i].size(); ++j) {
      mmp[i].emplace((a[i][j]-1) / m, a[i][j]);
      ++mp[i][(a[i][j]-1) / m];
    }
    for (auto& p: mp[i])
      ms[i].emplace(p.second, p.first);
  }

  matrix b(n);
  for (int i = 0; i < m; ++i) {
    std::vector<int> res(n);
    std::set<int> seen;
    bool v = neko(ms, 0, seen, res);
    // fprintf(stderr, "v? %d\n", !!v);
    // for (size_t j = 0; j < res.size(); ++j)
    //   fprintf(stderr, "%d%c", res[j], j+1<res.size()? ' ': '\n');

    for (int j = 0; j < n; ++j) {
      auto it = mmp[j].find(res[j]);
      b[j].push_back(it->second);
      // fprintf(stderr, "b[%d][]: %d\n", j, it->second);
      mmp[j].erase(it);
    }
  }

  a = std::move(b);
  print(a);
}

void step2(matrix& a) {
  int n = a.size();
