		for(j=1;j<=n;++j){
			g.addedge(g.n-1,j,1);g.addedge(j+n,g.n,1);
			for(k=0;k<=m-i;++k)g.addedge(j,(a[j][k]-1)/m+1+n,1);
		}
		assert(g.dinic(g.n-1,g.n)==n);
		for(j=1;j<=n;++j){
			for(k=g.h[j];g.e[k].f || g.e[k].to==g.n-1;k=g.e[k].next);
			for(l=0;(a[j][l]-1)/m+1!=g.e[k].to-n;++l);
