      }
    }
    bm.bipartite_matching();
    vector< int > rev(N);
    for(int j = 0; j < N; j++) {
      rev[bm.match[j]] = j;
    }
    for(int j = 0; j < N; j++) {
      B[j][i] = A[j][pre[j][rev[j]]];
