const int N = 100;
struct BM {
  int L, R;
  vector<vector<int>> adj;
  vector<int> level, mate;
  void init(int l, int r){
    L = l, R = r;
    adj = vector<vector<int>>(L+R);
    level = vector<int>(L);
    mate = vector<int>(L+R, -1);
  }
  void add_edge(int u, int v) {
    adj[u].push_back(v+L);
    adj[v+L].push_back(u);
  }
  int maximum_matching() {
    function<bool(void)> levelize = [&](){
      queue<int> Q;
      for(int u=0; u<L; u++){
        level[u] = -1;
        if(mate[u] < 0) {
          level[u] = 0;
          Q.push(u);
        }
      }
      while (!Q.empty()) {
        int u = Q.front();
        Q.pop();
        for(int w: adj[u]) {
          int v = mate[w];
          if(v < 0) return true;
          if(level[v] < 0) {
            level[v] = level[u] + 1;
            Q.push(v);
          }
        }
      }
      return false;
    };
    function<bool(int)> augment = [&](int u) {
      for(int w: adj[u]) {
        int v = mate[w];
        if(v < 0 || (level[v] > level[u] && augment(v))){
          mate[u] = w;
          mate[w] = u;
          return true;
        }
      }
      return false;
    };
    int match = 0;
    while(levelize()) for(int u=0; u<L; u++) if (mate[u] < 0 && augment(u)) match++;
    return match;
  }
} bm;

