void dfs(int l, int r, int x, int y, int cx, int cy) {
	col[l][x][cx] = y;
	if (int v = col[r][y][cx]) {
		col[l][v][cx] = 0;
		col[r][y][cx] = x;
		dfs(r, l, y, v, cy, cx);
	} else col[r][y][cx] = x;
}
