struct Dinic {// 0 indexed
	int n, m, s, t;
	vector<Edge> edges;
	vector<vector<pi>> g;
	vi lvl, lst;
	void init(int n, int s, int t) {
		g.clear();
		lvl.clear();
		lst.clear();
		edges.clear();
		this-> s = s;
		this->t = t;
		this->n = n;
		m = 0;
		g.resize(n);

	}
	void add_edge(int f, int t, int cap) {
		edges.pb(Edge(f, t, cap));
		edges.pb(Edge(t, f, cap));
		g[f].pb({t, m++});
		g[t].pb({f, m++});
	}
	bool bfs() {
		lvl.assign(n, -1);
		queue<int> q;
		q.push(s);
		lvl[s] = 0;
		while(!q.empty()) {
			int u = q.front();
			q.pop();
			for(auto i : g[u]) {
				if(lvl[i.first]==-1&&edges[i.second].flow!=edges[i.second].cap) {
					lvl[i.first] = lvl[u] + 1;
					q.push(i.first);
				}
			}
		}
		return lvl[t] != -1;
	}
	bool dfs(int v, int &mn, int p = -1) {
		if(mn<1) return false;
		if(v==t) {
			return true;
		}
		for(ll &i = lst[v]; i < g[v].size(); i++) {
			if(g[v][i].first==p||edges[g[v][i].second].flow==edges[g[v][i].second].cap||lvl[g[v][i].first]!=lvl[v]+1) continue;
			int x = mn;
			//cout << g[v][i].first << " " << edges[g[v][i].second].flow << ")\n";
			mn = min(mn, edges[g[v][i].second].cap-edges[g[v][i].second].flow);
			int t = dfs(g[v][i].first, mn, v);
			if(!t) {
				mn = x;
				continue;
			}
			edges[g[v][i].second].flow += mn;
			edges[g[v][i].second^1].flow -= mn;
			return true;
		}
		return false;
	}
	ll solve() {
		ll flow = 0;
		int path;
		lst.assign(n, 0);
		while(true) {
			if(!bfs()) break;
			int iter = 0;
			do {
				path = 2e9;
				if(!dfs(s, path)) path = 0;
				flow += path;
				//cout << "====" << path << endl;
				lst.assign(n, 0);
				if(path) iter++;
			} while(path);
			if(!iter) break;
		}
		for(auto i : edges) {
			if(i.flow==1&&i.u>1&&i.v>1) {
				assert(i.u<i.v);
				//cout << i.u << " " << i.v << "edge\n";
				match[i.u-2] = i.v-1-n/2;
			}
		}
		//cout << flow << ";\n";
		return flow;
	}
};
