bool DFS(int i, int j)
{
   eprintf("DFS%d%d\n", i, j);
   if (j >= M) {
      if (i >= N-1) return true;
      return DFS(i+1, 0);
   }
   if (B[i][j]) return DFS(i, j+1);
   if (!i) {
      B[i][j] = A[i][j];
      return DFS(i, j+1);
   }
   REP(k, M) { // put A[i][k] into B[i][j]
      bool isBad = false;
      REP(l, j) { // if A[i][k] == B[i][l], not good
         if (A[i][k] == B[i][l]) {
            isBad = true;
            break;
         }
      }
      REP(l, i) { // if A[i][k] & B[l][j] is in same group, not good
         if ((A[i][k]-1)/M == (B[l][j]-1)/M) {
            isBad = true;
            break;
         }
      }
      if (isBad) continue;
      B[i][j] = A[i][k];
      if (DFS(i, j+1)) {
         return true;
      }
   }
   return false;
}

