typedef vector<int> vi;
typedef long long ll;
typedef pair<int,int> pii;

bool find(int j, vector<vi>& g, vi& btoa, vi& vis) {
	if (btoa[j] == -1) return 1;
	vis[j] = 1; int di = btoa[j];
	trav(e, g[di])
		if (!vis[e] && find(e, g, btoa, vis)) {
			btoa[e] = di;
			return 1;
		}
	return 0;
}
int dfsMatching(vector<vi>& g, vi& btoa) {
	vi vis;
	rep(i,0,sz(g)) {
		vis.assign(sz(btoa), 0);
		trav(j,g[i])
			if (find(j, g, btoa, vis)) {
				btoa[j] = i;
				break;
			}
	}
	return sz(btoa) - (int)count(all(btoa), -1);
}

int n, m;

vector<vi> step1(vector<vi> &as){
	vector<vi> bs(n, vi(m));
	vector<vector<bool>> done(n, vector<bool>(m));
	rep(r,0,n){
		vector<vi> g(m);
		rep(j,0,m) rep(c,0,m)
			if(!done[(as[r][j]-1)/m][c])
				g[j].push_back(c);
		vi btoa(m, -1);
		dfsMatching(g, btoa);
		rep(c,0,m){
			done[(as[r][btoa[c]]-1)/m][c] = true;
			bs[r][c] = as[r][btoa[c]];
		}
	}
	return bs;
}

vector<vi> step2(vector<vi> &bs){
	vector<vi> cs(n, vi(m));
	rep(i,0,n) rep(j,0,m){
		int r = (bs[i][j]-1) / m;
		cs[r][j] = bs[i][j];
	}
	return cs;
}

void skriv(vector<vi> &xs){
	trav(v, xs){
		trav(x, v) cout << x << ' ';
		cout << endl;
	}
}

