int main()
{
    int N;
    cin >> N;
    int M;
    cin >> M;
    vector<vector<int>> A(N, vector<int>(M));
    REP(i, N) REP(j, M)
    {
        cin >> A[i][j];
        A[i][j]--;
    }

    vector<int> Ainv(N * M);
    REP(i, N) REP(j, M) Ainv[A[i][j]] = i;

    vector<set<int>> edges(N);

    REP(i, N) REP(j, M)
    {
        int t = A[i][j] / M;
        if (t != i)
        {
            edges[i].insert(A[i][j]);
        }
    }
    // dbg(edges);

    int l_now = 0;
    vector<vector<int>> loops;
    while (l_now < N)
    {
        if (edges[l_now].size() == 0)
        {
            l_now++;
            continue;
        }

        vector<int> loop;
        int x = *edges[l_now].begin();

        vector<int> visited(N);
        visited[l_now] = 1;
        loop.push_back(x);
        edges[l_now].erase(x);

        int l = x / M;
        while (l != l_now)
        {
            visited[l] = 1;
            int xx = *edges[l].begin();

            for (auto nx : edges[l])
            {
                if (visited[nx / M] == 0)
                {
                    xx = nx;
                    break;
                }
            }
            edges[l].erase(xx);
            loop.emplace_back(xx);
            l = loop.back() / M;
            if (visited[xx / M]) break;
        }

        reverse(ALL(loop));

        bool flg = true;
        FOR(i, 1, loop.size()) if (Ainv[loop[i]] == Ainv[loop[0]]) flg = false;
        if (!flg)
        {
            while (true)
            {
                int x = loop.back();
                loop.pop_back();
                edges[Ainv[x]].insert(x);
                if (Ainv[x] == Ainv[loop[0]]) break;
            }
        }
        reverse(ALL(loop));
        loops.emplace_back(loop);
    }
