		if(e[i].flow&&lv[e[i].to]==lv[now]+1){
			int tmp=find(e[i].to,std::min(limit,e[i].flow));
			e[i].flow-=tmp; e[i^1].flow+=tmp;
			ans+=tmp; limit-=tmp;
			if(!limit)break;
		}
	}
	return ans;
}
