using namespace std;
typedef long long ll;
ll inf = 1e18;

class network_flow{
public:
	int N;
	struct edge{int to; ll cap; int rev; bool is_rev,used; int num;};
	vector<vector<edge>> G;
	vector<int> level,iter;
	void bfs(int s){
		for(int i=0;i<=N;i++) level[i] = -1;
		queue<int> Q;
		level[s] = 0;
		Q.push(s);
		while(!Q.empty()){
			int v = Q.front(); Q.pop();
			for(int i=0;i<G[v].size();i++){
				edge &e = G[v][i];
				if(e.cap > 0 && level[e.to]<0 && !e.used){
					level[e.to] = level[v]+1;
					Q.push(e.to);
				}
			}
		}
	}
	ll dfs(int v,int t,ll f){
		if(v==t) return f;
		for(int &i=iter[v];i<G[v].size();i++){
			edge &e = G[v][i];
			if(level[v]<level[e.to] && e.cap>0 && !e.used){
				ll d = dfs(e.to,t,min(f,e.cap));
				if(d>0){
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
public:
	network_flow(int n){
		N = n;
		G = vector<vector<edge>>(N+1);
		level = iter = vector<int>(N+1);
	}
	void add_edge(int from, int to,ll cap,int num){
		G[from].push_back((edge){to,cap,(int) G[to].size(),false,false,num});
		G[to].push_back((edge){from,0,(int) G[from].size()-1,true,false,num});
	}
	void reset(){
		for(int i=0;i<N;i++){
			for(auto& x:G[i]) x.cap = (!x.is_rev);
		}
	}
	ll max_flow(int s,int t){
		ll flow = 0;
		for(;;){
			bfs(s);
			if(level[t]<0) return flow;
			for(int i=0;i<=N;i++) iter[i] = 0;
			ll f;
			while((f=dfs(s,t,inf))>0) flow += f;
		}
	}
};

int main(){
    int N,M;
    cin >> N >> M;
    vector<vector<int>> A(N+1,vector<int>(M+1,-1));
    vector<vector<int>> B(N+1,vector<int>(M+1,-1));
    vector<vector<int>> C(N+1,vector<int>(M+1,-1));
    for(int i=1;i<=N;i++) for(int j=1;j<=M;j++){
        cin >> A[i][j];
    }
    network_flow flow(2*N+2);
    for(int i=1;i<=N;i++){
		flow.add_edge(0,i,1,0);
		flow.add_edge(N+i,2*N+1,1,0);
		for(int j=1;j<=M;j++){
			flow.add_edge(i,N+(A[i][j]+M-1)/M,1,A[i][j]);
		}
    }
	for(int t=1;t<=M;t++){
		int res = flow.max_flow(0,2*N+1);
		assert(res==N);
		for(int i=1;i<=N;i++){
			for(auto& x:flow.G[i+N]){
				if(!x.used && x.is_rev && x.cap==1){
					B[x.to][t] = x.num;
					x.used = true;
					flow.G[x.to][x.rev].used = true;
					break;
				}
			}
		}
		flow.reset();
