int n, m, a[maxn + 3][maxn + 3], b[maxn + 3][maxn + 3];
int row[maxn + 3], num[maxn + 3], tmp[maxn + 3];
bool used[maxn + 3][maxn + 3], vis[maxn + 3];
vector<int> S[maxn + 3][maxn + 3];

bool match(int u, int x) {
	for (int i = 1; i <= m; i++) {
		if (used[u][i] || vis[i]) continue;
		vis[i] = true;
		if (!num[i] || match(row[i], num[i])) {
			row[i] = u, num[i] = x;
			return true;
		}
	}
	return false;
}

int main() {
	scanf("%d %d", &n, &m);
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			scanf("%d", &a[i][j]);
			S[(a[i][j] - 1) / m + 1][i].push_back(a[i][j]);
		}
	}
	for (int i = 1; i <= n; i++) {
		memset(row, 0, sizeof(row));
		memset(num, 0, sizeof(num));
		for (int j = 1; j <= n; j++) {
			for (int t = 0, k; t < S[i][j].size(); t++) {
				k = S[i][j][t];
				memset(vis, false, sizeof(vis));
				if (!match(j, k)) {
					puts("-1");
					return 0;
				}
			}
		}
		for (int j = 1; j <= m; j++) {
			b[row[j]][j] = num[j];
			used[row[j]][j] = true;
		}
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			printf("%d%c", b[i][j], " \n"[j == m]);
		}
	}
	for (int i = 1; i <= m; i++) {
		for (int j = 1; j <= n; j++) {
			tmp[j] = b[j][i];
		}
		sort(tmp + 1, tmp + n + 1);
		for (int j = 1; j <= n; j++) {
			b[j][i] = tmp[j];
		}
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			printf("%d%c", b[i][j], " \n"[j == m]);
		}
	}
	return 0;
}

