int n, m;

const int N = 302;
vector<int> g[N << 1];
int mt[N << 1];

int used[N << 1];

bool dfs(int v) {
    if (used[v]) {
        return 0;
    }
    used[v] = 1;
    for (int u : g[v]) {
        if (mt[u] == -1 || dfs(mt[u])) {
            mt[u] = v;
            return 1;
        }
    }
    return 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    vector<vector<int>> a(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
            --a[i][j];
        }
    }
    vector<vector<bool>> b(n, vector<bool>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int l = a[i][j] / m;
            g[j].clear();
            for (int k = 0; k < m; ++k) {
                if (!b[l][k]) {
                    g[j].eb(k + N);
                    //cout << j << ' ' << k << endl;
                }
            }
        }
        fill(mt, mt + (N << 1), -1);
        fill(used, used + (N << 1), false);
        for (int j = 0; j < m; ++j) {
            fill(used, used + (N << 1), false);
            dfs(j);
        }
        vector<int> r(m);
        for (int j = 0; j < m; ++j) {
            //cout << '!' << j << ' ' << j + N << ' ' << mt[j + N] << endl;
            r[j] = a[i][mt[j + N]];
            b[a[i][mt[j + N]] / m][j] = 1;
        }
        a[i] = r;
        for (int el : a[i]) {
            cout << el + 1 << ' ';
        }
        cout << '\n';
    }
    for (int j = 0; j < m; ++j) {
        vector<int> r(n);
        for (int i = 0; i < n; ++i) {
            r[i] = a[i][j];
        }
        sort(all(r));
        for (int i = 0; i < n; ++i) {
            a[i][j] = r[i];
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cout << a[i][j] + 1 << ' ';
        }
        cout << '\n';
    }
    return 0;
}

