#include <bits/stdc++.h>
using namespace std;
const int N = 105;
int a[N][N], n, m, ans1[N][N], ans2[N][N];
bool change[N][N];
map<pair<int,int>,set<int>> mp;
int main() {
	ios_base::sync_with_stdio(0), cin.tie(0);
	cin >> n >> m;
	for(int i=0;i<n;i++) {
		for(int j=0;j<m;j++) {
			cin >> a[i][j];
		}
	}
	for(int i=0;i<n;i++) {
		for(int j=0;j<m;j++) {
			int go = a[i][j]/m;
			if(a[i][j]%m==0)go--;
			if(go!=i) mp[make_pair(go,i)].insert(a[i][j]);
		}
	}
	for(auto &k: mp) {
		pair<int,int> key = k.first;
		set<int> &v = k.second;
		if(key.first>key.second) continue;
		for(auto &val : v) {
			int ch = *mp[make_pair(key.second, key.first)].begin();
			int good=-1;
			for(int i=0;i<m;i++) if(change[key.first][i]==false&&change[key.second][i]==false) good=i;
			change[key.first][good]=true;
			change[key.second][good]=true;
			ans1[key.second][good]=val;
			ans1[key.first][good]=ch;
			mp[make_pair(key.second, key.first)].erase(ch);
		}
		v.clear();
	}
	for(int i=0;i<n;i++) {
		set<int> st;
		for(int j=0;j<m;j++) st.insert(a[i][j]);
		for(int j=0;j<m;j++) if(ans1[i][j]) st.erase(ans1[i][j]);
		for(int j=0;j<m;j++) if(ans1[i][j]==0) {
			ans1[i][j]=*st.begin();
			st.erase(*st.begin());
		}
	}
	for(int i=0;i<n;i++) {
		for(int j=0;j<m;j++) {
			cout << ans1[i][j] << " ";
		}
		cout << "\n";
	}
	for(int j=0;j<m;j++) {
		set<int> st;
		for(int i=0;i<n;i++) {
			st.insert(ans1[i][j]);
		}
		for(int i=0;i<n;i++) {
			ans2[i][j]=*st.begin();
			st.erase(*st.begin());
		}
	}
	for(int i=0;i<n;i++) {
		for(int j=0;j<m;j++) {
			cout << ans2[i][j] << " ";
		}
		cout << "\n";
	}
	return 0;
}

