const int N = 110;

int n, m, a[N][N], b[N][N], c[N][N];

struct Edge {
  int u, v, nxt, id, mark;
} E[N * N];

int head[N], tot = 0, vis[N], match[N];

void addedge(int u, int v, int id) {
  E[++tot] = (Edge) {u, v, head[u], id, 0};
  head[u] = tot;
}

bool dfs(int u) {
  for (int i = head[u]; i; i = E[i].nxt) if (!E[i].mark) {
    int v = E[i].v;
    if (vis[v]) continue;
    vis[v] = 1;
    if (!match[v] || dfs(E[match[v]].u)) {
      match[v] = i;
      return 1;
    }
  }
  return 0;
}

