const int maxn = 100;

int n, m;
pii a[maxn][maxn];
bool rm[maxn][maxn];
pii b[maxn][maxn];

void Run1(void) {
  FILLA(rm, 0);
  for (int i = 0; i < m; ++i) {
    dinic::Init(2 * n + 2);
    for (int r = 0; r < n; ++r) {
      for (int c = 0; c < m; ++c) {
        if (!rm[r][c]) {
          dinic::AddEdge(r, n + a[r][c].first, 1, r * m + c);
        }
      }
    }
    int S = 2 * n, T = S + 1;
    for (int r = 0; r < n; ++r) {
      dinic::AddEdge(S, r, 1);
      dinic::AddEdge(n + r, T, 1);
    }
    dinic::Solve(S, T);
    auto res = dinic::Result();
    assert(res.size() == n);
    for (int j = 0; j < n; ++j) {
      int t = res[j].first;
      int r = t / m, c = t % m;
      rm[r][c] = true;
      b[r][i] = a[r][c];
    }
  }
  COPYA(b, a);
}

void Run2(void) {
  static pii col[maxn];
  for (int c = 0; c < m; ++c) {
    for (int r = 0; r < n; ++r) {
      col[r] = a[r][c];
    }
    sort(col, col + n);
    for (int r = 0; r < n; ++r) {
      a[r][c] = col[r];
    }
  }
}

void Print(void) {
  for (int r = 0; r < n; ++r) {
    for (int c = 0; c < m; ++c) {
      printf("%d%c", a[r][c].second, " \n"[c == m - 1]);
    }
  }
}

int main(void) {
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      int id;
      scanf("%d", &id);
      a[i][j] = pii((id - 1) / m, id);
    }
  }
  Run1();
  Print();
  Run2();
  Print();
  return 0;
}

