namespace detail {
template <typename Tp, size_t N>
std::vector<Tp> make_vector(
    std::vector<size_t>& sizes,
    typename std::enable_if<(N == 1), Tp const&>::type x
) {
  return std::vector<Tp>(sizes[0], x);
}
template <typename Tp, size_t N>
auto make_vector(
    std::vector<size_t>& sizes,
    typename std::enable_if<(N > 1), Tp const&>::type x
) {
  size_t size = sizes[N-1];
  sizes.pop_back();
  return std::vector<decltype(make_vector<Tp, N-1>(sizes, x))>(
      size, make_vector<Tp, N-1>(sizes, x)
  );
}
}  // detail::

template <typename Tp, size_t N>
auto make_vector(size_t const(&sizes)[N], Tp const& x) {
  std::vector<size_t> s(N);
  for (size_t i = 0; i < N; ++i) s[i] = sizes[N-i-1];
  return detail::make_vector<Tp, N>(s, x);
}

using matrix = std::vector<std::vector<int>>;

void print(matrix const& a) {
  for (auto const& ai: a)
    for (size_t j = 0; j < ai.size(); ++j) {
      // assert(ai[j] != 0);
      printf("%d%c", ai[j], j+1<ai.size()? ' ': '\n');
    }
}

void step1(matrix& a) {
  for (auto& ai: a) std::sort(ai.rbegin(), ai.rend());
  std::sort(a[0].begin(), a[0].end());
  print(a);
}

void step2(matrix& a) {
  int n = a.size();
  int m = a[0].size();

  matrix b(m, std::vector<int>(n));
  for (size_t i = 0; i < a.size(); ++i)
    for (size_t j = 0; j < a[i].size(); ++j)
      b[j][i] = a[i][j];

  for (size_t j = 0; j < b.size(); ++j)
    std::sort(b[j].begin(), b[j].end());

  for (size_t i = 0; i < a.size(); ++i)
    for (size_t j = 0; j < a[i].size(); ++j)
      a[i][j] = b[j][i];

  print(a);
}

int main() {
  size_t n, m;
  scanf("%zu %zu", &n, &m);

  auto a = make_vector<int>({n, m}, 0);
  for (auto& ai: a)
    for (auto& aij: ai)
      scanf("%d", &aij);

  step1(a);
  step2(a);
  for (size_t i = 0; i < n; ++i) {
    std::sort(a[i].begin(), a[i].end());
    for (size_t j = 0; j < m; ++j) {
      // fprintf(stderr, "%d%c", a[i][j], j+1<m? ' ': '\n');
      assert(a[i][j] == int(i*m)+int(j)+1);
