using namespace std;
using ll = long long;

struct Dinic {
  struct edge { int v; long long c; };
  vector<edge> es;
  vector<vector<int>> g;
  vector<int> dist;
  vector<int> index;

  Dinic(int n) : g(n), dist(n), index(n) {}

  int add(int u, int v, long long c) {
    g[u].push_back(es.size());
    g[v].push_back(es.size() + 1);
    es.push_back(edge{v, c});
    es.push_back(edge{u, 0});
    return es.size() - 2;
  }

  long long calc(int s, int t) {
    long long ans = 0;
    while (bfs(s, t)) {
      for (;;) {
        long long d = dfs(s, t, 1e18);
        if (d == 0) break;
        ans += d;
      }
    }
    return ans;
  }

  bool bfs(int s, int t) {
    fill(dist.begin(), dist.end(), -1);
    fill(index.begin(), index.end(), 0);
    queue<int> q;
    q.push(t);
    dist[t] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      for (int i : g[u]) {
        int v = es[i].v;
        if (es[i ^ 1].c > 0 && dist[v] == -1) {
          dist[v] = dist[u] + 1;
          q.push(v);
        }
      }
    }
    return dist[s] != -1;
  }

  long long dfs(int u, int t, long long f) {
    if (u == t) return f;
    for (int &it = index[u]; it < g[u].size(); it++) {
      int i = g[u][it];
      int v = es[i].v;
      if (es[i].c > 0 && dist[v] < dist[u]) {
        long long d = dfs(v, t, min(f, es[i].c));
        if (d > 0) {
          es[i ^ 0].c -= d;
          es[i ^ 1].c += d;
          return d;
        }
      }
    }
    return 0;
  }
};

