void swap(int &a, int &b) {
	int tmp = a;
	a = b;
	b = tmp;
}

bool checkRow(int a, int N, int M, int i, int j) {
	int j2 = (a - 1) % M;
	return (j2 == j);
}

bool checkColw(int a, int N, int M, int i, int j) {
	int i2 = (a - 1) / M;
	return (i2 == i);
}

int main() {
