	int A[N_MAX][N_MAX];

	REP(i,N) REP(j,M) {
		cin >> A[i][j];
	}

//	PrimalDual<int, int> pd(3 * N * M);

	//行方向
	REP(i, N) {
		REP(j, M) {
			int j2 = (A[i][j] - 1) % M;
			if (j2 != j) {
				int j3 = (A[i][j2] - 1) % M;
				if ((j3 != j2) || (A[i][j] < (N * M / 2))) {
					swap(A[i][j], A[i][j2]);
				}
			}
		}
	}
	print2D(N, M, A);

	//列方向
	REP(j, M) {
		REP(i, N) {
			int i2 = (A[i][j] - 1) / M;
			if (i2 != i) {
				int i3 = (A[i2][j] - 1) / M;
				if ((i3 != i2) || (A[i][j] < (N * M / 2))) {
					swap(A[i][j], A[i2][j]);
				}
			}
		}
	}
	print2D(N, M, A);
}

