struct edge {
    int from, to, cap, flow;
};
const int N = 1000, oo = 1e9 + 10;
struct Dinic {
    vi g[N];
    vector<edge> e;

    void add_edge(int from, int to, int cap) {
        g[from].push_back(e.size());
        e.push_back({from, to, cap, 0});
        g[to].push_back(e.size());
        e.push_back({to, from, 0, 0});
    }

    int d[N], q[N + N], ptr[N];

    bool bfs(int s, int t) {
        int ql, qr;
        ql = qr = 0;
        q[qr++] = s;
        d[s] = 0;
        while (ql < qr) {
            int v = q[ql++];
            for (int id : g[v]) {
                int to = e[id].to;
                if (d[to] == -1 && e[id].cap > e[id].flow) {
                    d[to] = d[v] + 1;
                    q[qr++] = to;
                }
            }
        }
        return d[t] != -1;
    }

    int dfs(int v, int fin, int flow) {
        if (!flow || fin == v)
            return flow;
        for (; ptr[v] < (int) g[v].size(); ++ptr[v]) {
            int id = g[v][ptr[v]];
            int to = e[id].to;
            if (d[to] != d[v] + 1)
                continue;
            int pushed = dfs(to, fin, min(flow, e[id].cap - e[id].flow));
            if (pushed) {
                e[id].flow += pushed;
                e[id ^ 1].flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    int dinic(int s, int t) {
        int flow = 0;
        while (true) {
            fill(d, d + t + 1, -1);
            fill(ptr, ptr + t + 1, 0);
            if (!bfs(s, t))
                return flow;
            while (int pushed = dfs(s, t, oo)) {
                flow += pushed;
            }
        }
    }
};


