namespace dinic{
	const int OO=1e9;
	struct edge{
	    int from,to,flow,capacity;
	    edge(int f,int t,int c):from(f),to(t),flow(0),capacity(c){}
	};
	vector<vector<int>> g;
	vector<edge> es;
	int n,source,sink;
	vector<int> q,dist,y;
	void init(int _n,int s,int t){
		n=_n;
		source=s;
		sink=t;
		g.assign(n,vector<int>());
		es.clear();
		q.resize(n);
		dist.resize(n);
		y.resize(n);
	} 
	void ae(int a,int b,int c){
	    es.pb(a,b,c);g[a].pb(es.size()-1);
	    es.pb(b,a,0);g[b].pb(es.size()-1);
	}
	bool bfs(){
		fill(dist.begin(), dist.end(), n);
	    dist[source]=0;
	    int l=0,r=0;
	    q[r++]=source;
	    while(l<r){
	        int v=q[l++];
	        for(int x:g[v]){
	            if(dist[v]+1<dist[es[x].to]&&es[x].flow+1<=es[x].capacity){
	                dist[es[x].to]=dist[v]+1;
	                q[r++]=es[x].to;
	            }
	        }
	    }
	    return dist[sink]<n;
	}
	int dfs(int v,int pu=OO){
	    if(v==sink)return pu;
	    for(;y[v]<sz(g[v]);++y[v]){
	        int x=g[v][y[v]];
	        int val=min(pu,es[x].capacity-es[x].flow);
	        if(dist[es[x].to]==dist[v]+1&&es[x].flow+1<=es[x].capacity&&(val=dfs(es[x].to,val))){
	            es[x].flow+=val;
	            es[x^1].flow-=val;
	            return val;
	        }
	    }
	    return 0;
	}
	int dinic(){
	    int ans=0,res;
	    while(bfs()){
	    	fill(y.begin(), y.end(), 0);
	        while(res=dfs(source))ans+=res;
	    }
	    return ans;
	}
}

