						loc1[iRow][k] = x;
						loc1[iRow][iCol] = y;
						colMap[x] = k;
						colMap[y] = iCol;
						spaces[k] = 1;
						break;
					}
				}
				if( k == M)
					throw "Should not reach here";
			}
			else
				spaces[iCol] = 1;
		}
	}

