class Graph{
	edge e[200100];
	int tot,head[1010],cur[1010],b[1010];
public:
	int t;
	Graph(){tot=1;memset(head,0,sizeof(head));}
	void add(int x,int y,int z){
		e[++tot]={y,head[x],z};
		head[x]=tot;
		e[++tot]={x,head[y],0};
		head[y]=tot;
	}
	bool bfs(){
		memset(b,0,sizeof(b));b[0]=1;
		queue<int> q;q.push(0);
		while(!q.empty()){
			int u=q.front();q.pop();
			for(int i=head[u];i;i=e[i].nxt)
				if(e[i].f&&!b[e[i].v]){
					b[e[i].v]=b[u]+1;
					q.push(e[i].v);
				}
		}
		return b[t];
	}
	int dfs(int x,int flow){
		if(x==t||!flow) return flow;
		int f=flow,tmp;
		for(int &i=cur[x];i;i=e[i].nxt)
			if(b[e[i].v]==b[x]+1&&(tmp=dfs(e[i].v,min(e[i].f,f)))){
				f-=tmp;
				e[i].f-=tmp;e[i^1].f+=tmp;
				if(!f) break;
			}
		return flow-f;
	}
	int Dinic(){
		int ans=0;
		while(bfs()){
			memcpy(cur,head,sizeof(cur));
			ans+=dfs(0,100000000);
		}
		return ans;
	}
	int chk(int x){
		for(int i=head[x];i;i=e[i].nxt)
			if(e[i].v&&!e[i].f) return e[i].v;
	}
};
