int mt[maxn]; 
int used[maxn]; 

bool dfs(int u) {
    if (used[u]) return false;
    used[u] = 1;
    for (auto v : gr[u]) {
        if (gays[u][v].empty()) continue; 
        if (mt[v] == -1 || dfs(v)) {
            mt[v] = u; 
            return true; 
        }
    } 
    return false;
}

vector<int> ans[maxn]; 

void get() {
    for (int i = 0; i < n; ++i) {
        used[i] = 0; 
        mt[i] = -1; 
    }        
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) used[j] = 0; 
        dfs(i); 
    }
    for (int i = 0; i < n; ++i) {
        ans[mt[i]].pb(gays[mt[i]][i].back());
        gays[mt[i]][i].pop_back();         
    }
}

