#define MAX_V 40000

typedef int F;
const F INF = TEN(9);

struct edge {
	int to, rev;
	F cap;
	edge(int to, F cap, int rev) : to(to), cap(cap), rev(rev) {};
};

vector<edge> G[MAX_V];
int level[MAX_V]; 
int iter[MAX_V]; 

void add_edge(int from, int to, F cap) {
	//cerr << "from = " << from << ", to = " << to << endl;
	G[from].emplace_back(to, cap, (int)G[to].size());
	G[to].emplace_back(from, 0, (int)G[from].size() - 1);
}

void bfs(int s) {
	memset(level, -1, sizeof(level));
	queue<int> que;
	level[s] = 0;
	que.push(s);

	while (!que.empty()) {
		int v = que.front(); que.pop();
		for (edge &e : G[v]) {
			if (e.cap > 0 && level[e.to] < 0) {
				level[e.to] = level[v] + 1;
				que.push(e.to);
			}
		}
	}
}

F dfs(int v, int t, F f) {
	if (v == t) return f;
	for (int &i = iter[v]; i < G[v].size(); i++) {
		edge &e = G[v][i];
		if (e.cap > 0 && level[v] < level[e.to]) {
			F d = dfs(e.to, t, min(INF, e.cap));
			if (d > 0) {
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

F max_flow(int s, int t) {
	F flow = 0;
	while (true) {
		bfs(s);
		if (level[t] < 0) return flow;
		memset(iter, 0, sizeof(iter));
		F f;
		while ((f = dfs(s, t, INF)) > 0) flow += f;
	}
}

