struct mf {
	struct edge {
		int to, flow, back;

		edge(int a, int b, int c) : to(a), flow(b), back(c) {}
	};

	int n, s, t, ans, now;
	vector<vector<edge>> v;
	vector<int> at, ver, dis;
	queue<int> q;

	void init(int a, int b, int c) {
		n = a;
		v = vector<vector<edge>>(n, vector<edge>());
		at = ver = dis = vector<int>(n);
		s = b;
		t = c;
		ans = 0;
		q = queue<int>();
	}

	void bd(int a, int b, int c) {
		// printf("bd %d %d %d\n", a, b, c);
		v[a].emplace_back(b, c, v[b].size());
		v[b].emplace_back(a, 0, v[a].size() - 1);
	}

	void bd(int a, int b) {
		bd(a, b, 1);
	}

	int dfs(int a, int b) {
		if (a == t)
			return b;
		for (int &i = at[a]; i < v[a].size(); i++)
			if (ver[v[a][i].to] == now && v[a][i].flow && dis[v[a][i].to] == dis[a] + 1) {
				int re = dfs(v[a][i].to, min(v[a][i].flow, b));
				if (re) {
					b -= re;
					v[a][i].flow -= re;
					v[v[a][i].to][v[a][i].back].flow += re;
					return re;
				}
			}
		return 0;
	}

	void bfs() {
		for (now = 1; ; now++) {
			q.push(s);
			ver[s] = now;
			at[s] = 0;
			dis[s] = 0;
			while (!q.empty()) {
				int tmp = q.front();
				q.pop();
				for (int j = 0; j < v[tmp].size(); j++)
					if (v[tmp][j].flow) {
						int to = v[tmp][j].to;
						if (ver[to] != now) {
							ver[to] = now;
							at[to] = 0;
							dis[to] = dis[tmp] + 1;
							q.push(to);
						}
					}
			}
			if (ver[t] != now)
				return;
			while (1) {
				int tmp = dfs(s, INT_MAX);
				if (tmp)
					ans += tmp;
				else
					break;
			}
		}
	}
} mf;

