int h[MN], nxt[MM], to[MM], cap[MM], K = 1;
int q[MN], hh = 0, tt = 0;
int iter[MN], d[MN];
int A[MN][MN], B[MN][MN], C[MN][MN];
std::vector<int> cnt[MN][MN];

void ins(int u, int v, int c) {nxt[++K] = h[u]; h[u] = K; to[K] = v; cap[K] = c;}
void insw(int u, int v, int c) {ins(u, v, c); ins(v, u, 0);}

bool bfs(int S, int T)
{
	memcpy(iter, h, sizeof(h));
	memset(d, 0, sizeof(d)); d[S] = 1;
	hh = tt = 0; q[tt++] = S;
	while(hh < tt)
	{
		int u = q[hh++]; 
		for(int i = h[u]; i; i = nxt[i])
			if(cap[i] && !d[to[i]])
			{
				d[to[i]] = d[u] + 1;
				q[tt++] = to[i];
			}
	}
	return d[T];
}

int dfs(int u, int T, int f)
{
	if(u == T) return f;
	int used = 0;
	for(int &i = iter[u]; i; i = nxt[i])
	{
		if(cap[i] && d[to[i]] == d[u] + 1)
		{
			int w = dfs(to[i], T, std::min(cap[i], f - used));
			if(w)
			{
				cap[i] -= w; cap[i ^ 1] += w; used += w;
				if(f == used) return f;
			}
		}
	}
	return used;
}

int dinic(int S, int T)
{
	int w, f = 0;
	while(bfs(S, T))
		while(w = dfs(S, T, 1e9)) f += w;
	return f;
}

