		E[size].next=head[u];
		E[size].w=w;
		E[size].id=id;
		head[u]=size;
	}
	inline void add(int u,int v,int w,int id)
	{
		addE(u,v,w,id);
		addE(v,u,0,id);
	}
	inline void clear()
	{
		memset(head,0,sizeof(head));
		memset(E,0,sizeof(E));
		size=1;
	}
	inline bool bfs()
	{
		for(int i=0;i<=T;++i)
			dfn[i]=-1;
		queue<int>Q;
		Q.push(S);
		dfn[S]=0;
		while(!Q.empty())
		{
			int u=Q.front();
			Q.pop();
			for(int i=head[u];i;i=E[i].next)
			{
				int v=E[i].to;
				if(E[i].w==0||dfn[v]!=-1)
					continue;
				dfn[v]=dfn[u]+1;
				Q.push(v);
			}
		}
		return dfn[T]!=-1;
	}
	int dfs(int u,int up)
	{
		if(u==T)
			return up;
		int s=0;
		for(int i=head[u];i;i=E[i].next)
		{
			int v=E[i].to;
			if(dfn[v]!=dfn[u]+1||E[i].w==0)
				continue;
			int g=dfs(v,min(E[i].w,up-s));
			E[i].w-=g;
			E[i^1].w+=g;
			s+=g;
			if(g==0)
				dfn[v]=-1;
			if(s==up)
				break;
		}
		return s;
	}
	inline void solve()
	{
		int s=0;
		while(bfs())
			s+=dfs(S,123456);
		assert(s==n);
	}
}
