inline void addedge(int x,int y,int z)
{
	ne[++cnt]=he[x],he[x]=cnt,to[cnt]=y,w[cnt]=z;
	ne[++cnt]=he[y],he[y]=cnt,to[cnt]=x,w[cnt]=0;
}
int S,T;
int dis[maxn],inq[maxn];
int bfs()
{
	f(i,1,T)inq[i]=dis[i]=0;
	queue<int>q;q.push(S),dis[S]=1;
	while(q.size())
	{
		int x=q.front();q.pop();inq[x]=0;
		for(int i=he[x];i;i=ne[i])
		{
			if(w[i]&&!dis[to[i]])
			{
				dis[to[i]]=dis[x]+1;
				if(!inq[to[i]])
				{
					inq[to[i]]=1;
					q.push(to[i]);
				}
			 } 
		}
	}
	return dis[T];
}
int cur[maxn];
int dfs(int x,int f)
{
	if(f==0||x==T)return f;
	int ans=0;
	for(int i=cur[x];i&&ans<f;i=ne[i])
	{
		cur[x]=i;
		if(dis[x]+1==dis[to[i]]&&w[i]){
			int qwq=dfs(to[i],min(f-ans,w[i]));
			ans+=qwq;w[i]-=qwq;w[i^1]+=qwq;
		}
	}
	return ans;
}
int dinic()
{
