// Backtracking to solve n-queens problem.

int teto(int a, int b) {
	return a/b + (a % b != 0);
}

void bfs(int n, int m, int c, vector<vector<int>> & a, vector<vector<int>> & r) {
	queue<vector<int>> fila;
	vector<int> v(n+1, 0);
	int k = 1;
	v[0] = 1;
	v[k] = c;
	r[k][c] = c;
	fila.push(v); 
	bool vf = 0;
	while (!fila.empty()) {
		v = fila.front();
		fila.pop();
		k = v[0] + 1;
		int j_s = 0;
		for(int j=1; j<=m; j++) {
			if (!r[k][j]) {
				bool logica = 1;
				for(int i=1; i<k; i++) {
					if (teto(a[k][j], m) == teto(a[i][v[i]], m)) {
						logica = 0;
					}
				}
				if (logica) j_s = j;
			}
		}
		if (j_s) {
			v[k] = j_s;
			r[k][j_s] = c;
			v[0] = k;
			if (v[0] == n) vf = 1;
			else fila.push(v);
		}
	}
}

