			readint(a[i][j]),--a[i][j];
	for(int i=0;i<n;++i)g[i]=i;
	while(1)
	{
		bool flag=1;
		memset(cur,0,sizeof(cur));
		for(int t=0;t<n;++t)
		{
			int i=g[t];
			for(int j=0;j<m;++j)
				for(int k=0;k<m;++k)
					G[j][k]=!cur[j][a[i][k]/m];
			memset(match,-1,sizeof(match));
			for(int j=0;j<m;++j)
			{
				memset(vis,0,sizeof(vis));
				if(!dfs(j)){flag=0;break;}
			}
			if(!flag)break;
			for(int j=0;j<m;++j)p[match[j]]=a[i][j];
			for(int j=0;j<m;++j)a[i][j]=p[j],cur[j][p[j]/m]=1;
		}
		if(flag)break;
		random_shuffle(g,g+n);
	}
	for(int i=0;i<n;++i)
	{
		for(int j=0;j<m;++j)
			printf("%d ",a[i][j]+1);
		putchar('\n');
	}
	for(int j=0;j<m;++j)
	{
		for(int i=0;i<n;++i)p[i]=a[i][j];
		sort(p,p+n);
		for(int i=0;i<n;++i)a[i][j]=p[i];
	}
	for(int i=0;i<n;++i)
	{
		for(int j=0;j<m;++j)
			printf("%d ",a[i][j]+1);
		putchar('\n');
	}
	return 0;
}

