bool dfs(int v){
    color[v] = 1;
    for (int u : graph[v]){
        if (left[u] == -1 || (color[left[u]] == 0 && dfs(left[u]))){
            right[v] = u;
            left[u] = v;
            return true;
        }
    }
    return false;
}

