        for (int j = 0; j < m; j++)
            graph[j].clear();
        for (int j = 0; j < m; j++){
            for (int k = 0; k < m; k++){
                if (!used[s[i][j] / m][k])
                    graph[j].push_back(k);
            }
        }
        fill(left, left + m, -1);
        fill(right, right + m, -1);
        bool ok = true;
        for (int j = 0; j < m; j++){
            fill(color, color + m, 0);
            ok = dfs(j);
            // assert(ok);
        }
