	#define inf 999999999
	struct edge
	{
		int to,nxt,f;
	}e[200001];
	int head[211];
	int edge_cnt;
	int s,t;
	void init(int s1,int t1)
	{
		s=s1,t=t1;
		edge_cnt=-1;
		memset(head,-1,sizeof(head));
	}
	void add(int u,int v,int f)
	{
		e[++edge_cnt].nxt=head[u];
		e[edge_cnt].to=v;
		e[edge_cnt].f=f;
		head[u]=edge_cnt;
	}
	void add_edge(int u,int v,int f)
	{
		add(u,v,f);
		add(v,u,0);
	}
	int dep[211];
	bool bfs(int s,int t)
	{
		memset(dep,0x3f,sizeof(dep));
		queue<int>q;
		q.push(s);
		dep[s]=0;
		while(!q.empty())
		{
			int u=q.front();
			q.pop();
			for(int i=head[u];i!=-1;i=e[i].nxt)
				if(e[i].f!=0)
				{
					int to=e[i].to;
					if(dep[to]>dep[u]+1)
					{
						dep[to]=dep[u]+1;
						q.push(to);
					}
				}
		}
		return dep[t]<inf;
	}
	int dfs(int u,int flow)
	{
		if(u==t) return flow;
		int use=flow;
		for(int i=head[u];i!=-1;i=e[i].nxt)
		{
			int to=e[i].to;
			if(use&&dep[to]==dep[u]+1&&e[i].f)
			{
				int f=dfs(to,min(e[i].f,use));
				use-=f;
				e[i].f-=f;
				e[i^1].f+=f;
			}
		}
		return flow-use;
	}
	int dinic()
	{
		int maxflow=0;
		while(bfs(s,t))
			maxflow+=dfs(s,inf);
		return maxflow;
	}
}
