namespace dinic
{
	int cur[maxnode];
	int dis[maxnode];
	bool BFS()
	{
		static int q[maxnode]; int hd = 0, tl = 0;
		memset(dis, -1, sizeof(dis));
		dis[st] = 0;
		q[tl++] = st;
		while(hd < tl)
		{
			int u = q[hd++];
			for(int i = head[u]; ~i; i = G[i].nex) if(G[i].cap != G[i].flow)
			{
				int v = G[i].to;
				if(dis[v] == -1)
				{
					dis[v] = dis[u] + 1;
					q[tl++] = v;
				}
			}
		}
		return dis[ed] != -1;
	}
	int DFS(int u, int flow)
	{
		if(u == ed || flow == 0) return flow;
		int rec = flow;
		for(int &i = cur[u]; ~i; i = G[i].nex)
		{
			int v = G[i].to;
			if(dis[v] == dis[u] + 1)
			{
				int d = DFS(v, min(flow, G[i].cap - G[i].flow));
				G[i].flow += d;
				G[i ^ 1].flow -= d;
				flow -= d;
				if(flow == 0) break;
			}
		}
		return rec - flow;
	}
	int maxflow()
	{
		int flow = 0;
		while(BFS())
		{
			memcpy(cur, head, sizeof(head));
			flow += DFS(st, inf);
		}
		return flow;
	}
}

