const int N = 105;
int n, m, A[N][N], cnt[N], val[N], p[N], bel[N], ibel[N];
bool edge[N][N], vis[N];
bool find(int x) {
	for (int i = 0; i < n; ++i) if (!vis[i] && edge[x][i]) {
		vis[i] = 1;
		if (!~bel[i] || find(bel[i])) {
			bel[i] = x; return 1;
		}
	}
	return 0;
}
void solve(int col) {
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < n; ++j) edge[i][j] = 0;
	for (int i = 0; i < n; ++i) {
		for (int j = col; j < m; ++j)
			edge[i][A[i][j] / m] = 1;
		bel[i] = -1;
	}
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) vis[j] = 0;
		assert(find(i));
	}
	for (int i = 0; i < n; ++i) ibel[bel[i]] = i;
	for (int i = 0; i < n; ++i)
		for (int j = col; j < m; ++j)
			if (A[i][j] / m == ibel[i])
				std::swap(A[i][j], A[i][col]);
}
int main() {
	std::ios::sync_with_stdio(0), std::cin.tie(0);
	std::cin >> n >> m;
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j) std::cin >> A[i][j], --A[i][j];
	for (int i = 0; i < m; ++i) solve(i);
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j)
			std::cout << A[i][j] + 1 << " \n"[j == m - 1];
	for (int i = 0; i < m; ++i)
		for (int j = 0; j < n; ++j)
			for (int k = j + 1; k < n; ++k)
				if (A[j][i] > A[k][i]) std::swap(A[j][i], A[k][i]);
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j)
			std::cout << A[i][j] + 1 << " \n"[j == m - 1];
	return 0;
}

