using namespace std;

vector<int> Match(const vector<vector<int>> &g) {
    int n = g.size();
    vector<int> match(n, -1), used(n);

    function<bool(int)> Dfs = [&](int x) {
        for (int u : g[x]) {
            if (used[u]++) continue;
            if (match[u] == -1 || Dfs(match[u])) {
                match[u] = x;
                return true;
            }
        }
        return false;
    };

    for (int i = 0; i < n; ++i) {
        fill(used.begin(), used.end(), 0);
        Dfs(i);
    }
    return match;
}

