struct edge
{
	int from, to, flow, cap;
	edge() { }
	edge(int _1, int _2, int _3, int _4) : from(_1), to(_2), flow(_3), cap(_4) { }
};


struct Dinic
{
	edge edges[M];
	int head[N], nxt[M], tot;

	inline void init()
	{
		memset(head, -1, sizeof(head));
		tot = 0;
	}

	inline void add_edge(int x, int y, int z)
	{
		edges[tot] = edge(x, y, 0, z);
		nxt[tot] = head[x];
		head[x] = tot++;
		edges[tot] = edge(y, x, 0, 0);
		nxt[tot] = head[y];
		head[y] = tot++;
	}

	int s, t, L, R;

	int cur[N];

	int d[N];

	bool bfs()
	{
		memset(d + L, -1, sizeof(int) * (R-L+1));

		queue <int> q;
		q.push(s);
		d[s] = 0;

		while (!q.empty())
		{
			int x = q.front(); q.pop();
			cur[x] = head[x];
			for (int i = head[x]; ~i; i = nxt[i])
			{
				edge & e = edges[i];
				if (d[e.to] == -1 && e.flow < e.cap)
				{
					d[e.to] = d[x] + 1;
					q.push(e.to);
				}
			}
		}

		return d[t] != -1;
	}

	int dfs(int x, int a)
	{
		if (x == t || a == 0) return a;

		int flow = 0, f = 0;
		for (int &i = cur[x]; ~i; i = nxt[i])
		{
			edge & e = edges[i];
			if (d[e.to] == d[x] + 1 && (f = dfs(e.to, min(a, e.cap - e.flow))) > 0)
			{
				e.flow += f;
				edges[i^1].flow -= f;
				a -= f;
				flow += f;
				if (!a) break;
			}
		}

		return flow;
	}

	inline int maxflow(int s, int t)
	{
		this->s = s;
		this->t = t;
		int flow = 0;
		while (bfs()) flow += dfs(s, INF);
		return flow;
	}
} dinic;


