namespace flow{
int d[N<<1],cur[N<<1];
bool bfs(int vs)
{
	memset(d,-1,sizeof d);
	memset(cur,0,sizeof cur);
	d[vs]=0;cur[vs]=head[vs];
	static queue<int>q;while(!q.empty())q.pop();
	q.push(vs);
	while(!q.empty()){
		int u=q.front();q.pop();
		fe(i,u){
			int v=e[i].v,f=e[i].f;
			if(!~d[v]&&f){
				d[v]=d[u]+1;cur[v]=head[v];
				if(v==vt)return 1;
				q.push(v);
			}
		}
	}
	return 0;
}
int dfs(int u,int a)
{
	if(u==vt||!a)return a;
	int ans=0;
	fee(i,u){
		int v=e[i].v,f=e[i].f;
		if(f&&d[v]==d[u]+1){
			f=dfs(v,min(f,a));
			if(!f)continue;
			e[i].f-=f;e[i^1].f+=f;
			a-=f;ans+=f;if(!a)break;
		}
	}
	return ans;
}
