template<class T>
struct fixedSizeDeque{
	int n, L, R;
	T * arr;
	fixedSizeDeque(int n) : n(n){
		arr = new T[2 * n + 10];
		L = n + 5;
		R = L - 1;
	}

	void push_back(T x){
		arr[++R] = x; 
	}

	void push_front(T x){
		arr[--L] = x;
	}

	T front(){
		return arr[L];
	}

	T back(){
		return arr[R];
	}

	T pop_front(){
		// if(L > R){
		// 	throw runtime_error("empty queue access");
		// 	return T();
		// }
		return arr[L++];
	}

	T pop_back(){
		// if(L > R){
		// 	throw runtime_error("empty queue access");
		// 	return T();
		// }
		return arr[R--];
	}

	void re_init_indices(){
		L = n + 5;
		R = L - 1;
	}

	bool empty(){
		return L > R;
	}
	~fixedSizeDeque(){
		delete [] arr;
	}
};


struct graph {
  int L, R;
  vector<vector<int>> adj;
  set<pii> edges;
  graph(int L, int R) : L(L), R(R), adj(L+R) { }
  void add_edge(int u, int v) {

	  pii X = {u, v};
	  if(edges.count(X)) return;
	  edges.insert(X);
    adj[u].push_back(v+L);
    adj[v+L].push_back(u);

  }
  vector<int> maximum_matching() {
    vector<int> level(L), mate(L+R, -1);
    fixedSizeDeque<int> Q(L);
    function<bool(void)> levelize = [&]() { // BFS
      Q.re_init_indices();
      for (int u = 0; u < L; ++u) {
        level[u] = -1;
        if (mate[u] < 0) {
          level[u] = 0;
          Q.push_back(u); 
        }
      }
      while (!Q.empty()) {
        int u = Q.pop_front();
        for (int w: adj[u]) {
          int v = mate[w];
          if (v < 0) return true;
          if (level[v] < 0) {
            level[v] = level[u] + 1;
            Q.push_back(v); 
          }
        }
      }
      return false;
    };
    function<bool(int)> augment = [&](int u) { // DFS
      for (int w: adj[u]) {
        int v = mate[w];
        if (v < 0 || (level[v] > level[u] && augment(v))) {
          mate[u] = w;
          mate[w] = u;
          return true;
        }
      }
      return false;
    };
    int match = 0;
    while (levelize()) 
      for (int u = 0; u < L; ++u) 
        if (mate[u] < 0 && augment(u)) 
          ++match;
    return mate;
  }
};
