void step1(matrix& a) {
  int n = a.size();
  int m = a[0].size();
  for (auto& ai: a) std::sort(ai.rbegin(), ai.rend());
  matrix b(n, std::vector<int>(m));
  size_t k = 0;
  for (int i = 0; i < n*m; i += m) {
    std::queue<std::pair<size_t, int>> q;
    for (size_t j = 0; j < a.size(); ++j) {
      while (!a[j].empty() && a[j].back() <= i+m) {
        q.emplace(j, a[j].back());
        a[j].pop_back();
      }
    }
    for (size_t j = 0; j < b.size(); ++j) {
      size_t j0;
      int v;
      while (!q.empty()) {
        std::tie(j0, v) = q.front();
        if (j0 != j) break;
        q.pop();
        while (b[j][k] != 0) {
          ++k;
          k %= m;
        }
        b[j][k] = v;
        if (!q.empty()) {
          ++k;
          k %= m;
        }
      }
    }
  }
  a = std::move(b);

  print(a);
}

void step2(matrix& a) {
  int n = a.size();
  int m = a[0].size();

  matrix b(m, std::vector<int>(n));
  for (size_t i = 0; i < a.size(); ++i)
    for (size_t j = 0; j < a[i].size(); ++j)
      b[j][i] = a[i][j];

  for (size_t j = 0; j < b.size(); ++j)
    std::sort(b[j].begin(), b[j].end());

  for (size_t i = 0; i < a.size(); ++i)
    for (size_t j = 0; j < a[i].size(); ++j)
      a[i][j] = b[j][i];

  print(a);
}

