		REP(j,n){
			int pt=0;
			REP(k,m)if(!b[j][k]&&!Flow::cap[id[j][k]])b[j][k]=val[j][i][pt++];
		}
	}
	REP(i,m){
		vector<int>tmp;
		REP(j,n)tmp.pb(b[j][i]);
		sort(tmp.begin(),tmp.end());
		REP(j,n)c[j][i]=tmp[j-1];
	}
	REP(i,n)REP(j,m)printf("%d%c",b[i][j],j==m?'\n':' ');
	REP(i,n)REP(j,m)printf("%d%c",c[i][j],j==m?'\n':' ');
	return 0;
}

