int n, m, A[N][N], B[N][N], C[N][N], col[N][N];
int use[N][N], eid[N][N], sor[N];

void Match(int c) {
	mset(first, 0);
	eCnt = 1;
	S = n + n + 1, T = S + 1;
	for (int i = 1; i <= n; ++i) {
		Add(S, i, 1);
		Add(n + i, T, 1);
		for (int j = 1; j <= m; ++j) {
			if (use[i][j]) continue;
			eid[i][j] = eCnt + 1;
			Add(i, n + col[i][j], 1);
		}
	}
	Dinic();
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= m; ++j) {
			if (use[i][j]) continue;
			if (e[eid[i][j]].w == 0) {
				B[i][c] = A[i][j];
				use[i][j] = 1;
				break;
			}
		}
	}
}

void init() {
	read(n); read(m);
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= m; ++j) {
			read(A[i][j]);
			col[i][j] = (A[i][j] - 1) / m + 1;
		}
	}
}

void solve() {
	for (int i = 1; i <= m; ++i) {
		Match(i);
	}
	for (int j = 1; j <= m; ++j) {
		for (int i = 1; i <= n; ++i) {
			sor[i] = B[i][j];
		}
		sort(sor + 1, sor + n + 1);
		for (int i = 1; i <= n; ++i) {
			C[i][j] = sor[i];
		}
	}
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= m; ++j) {
			printf("%d ", B[i][j]);
		}
		puts("");
	}
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= m; ++j) {
			printf("%d ", C[i][j]);
		}
		puts("");
	}
}

int main() {
	init();
	solve();
	return 0;
}

