#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N=205,M=20005,inf=0x3f3f3f3f,INF=0x7fffffff;
int read(){
	int f=1,g=0;
	char ch=getchar();
	for (;!isdigit(ch);ch=getchar()) if (ch=='-') f=-1;
	for (;isdigit(ch);ch=getchar()) g=g*10+ch-'0';
	return f*g;
}
int n,m,cnt,S,T,ans,a[N][N],b[N],col[N*N];
int siz,fir[M],firr[M],dist[M],que[M],gap[M];
struct edge{int u,v,fl,nex;}e[M*2];
void add(int u,int v,int fl){
	e[++siz]=(edge){u,v,fl,fir[u]};fir[u]=siz;
	e[++siz]=(edge){v,u,0,fir[v]};fir[v]=siz;
}
bool bfs(){
	dist[que[1]=T]=1;int r=1;gap[1]=0;
	for (int l=1;l<=r;l++){
		int x=que[l];firr[x]=fir[x];gap[dist[x]]++;
		for (int i=fir[x];i;i=e[i].nex)
		if (!dist[e[i].v])
			dist[que[++r]=e[i].v]=dist[x]+1;
	}
	return (dist[S]!=inf);
}
int dfs(int x,int flow){
	if (x==T) return flow;
	int fl=0,t;
	for (int &i=firr[x];i;i=e[i].nex)
	if (e[i].fl&&(dist[e[i].v]+1==dist[x])&&(t=dfs(e[i].v,min(flow,e[i].fl)))){
		e[i].fl-=t;e[i^1].fl+=t;
		fl+=t;
		if (!(flow-=t)) return fl;
	}
	if(!(--gap[dist[x]])) dist[S]=cnt+1;
	++gap[++dist[x]];firr[x]=fir[x];
	return fl;
}
int dinic(){
	memset(dist,0,sizeof(dist));
	int flow=0;
	for (bfs();dist[S]<=cnt;flow+=dfs(S,INF));
//	cerr<<dist[S]<<' '<<flow<<endl;
	return flow;
}
int main(){
	n=read();m=read();
	for (int i=1;i<=n;i++)
	for (int j=1;j<=m;j++) a[i][j]=read(),col[++cnt]=i;
	for (int k=1;k<=m;k++){
		S=0;T=cnt=n*2+1;
		siz=1;memset(fir,0,sizeof(fir));
		for (int i=1;i<=n;i++){
			add(S,i,1);
			add(i+n,T,1);
			for (int j=k;j<=m;j++)
			add(i,n+col[a[i][j]],1);
		}
		assert(dinic()==n);
		for (int i=2;i<siz;i+=2)
		if ((e[i].u<=n)&&(e[i].v>n)&&e[i^1].fl) b[e[i].u]=e[i].v-n;
		for (int i=1;i<=n;i++)
		for (int j=k;j<=m;j++)
		if (col[a[i][j]]==b[i]) swap(a[i][j],a[i][k]);
	}
	for (int i=1;i<=n;i++){
		for (int j=1;j<=m;j++) printf("%d ",a[i][j]);
		printf("\n");
	}
	for (int j=1;j<=m;j++){
		for (int i=1;i<=n;i++) b[col[a[i][j]]]=a[i][j];
		for (int i=1;i<=n;i++) a[i][j]=b[i];
	}
	for (int i=1;i<=n;i++){
		for (int j=1;j<=m;j++) printf("%d ",a[i][j]);
		printf("\n");
	}
	return 0;
}

