			have[i][targx[A[i][j]]].push_back(A[i][j]);
		}
}

void work()
{
	for(int i=1; i<=m; i++)
	{
		G.init();
		for(int x=1; x<=n; x++)
			for(int y=1; y<=n; y++)
				if(have[x][y].size())
					G.addeg(x, n+y, 1), G.addeg(n+y, x, 0);
		for(int x=1; x<=n; x++)
		{
			G.addeg(n*2+1, x, 1);
			G.addeg(x, n*2+1, 0);
			G.addeg(n+x, n*2+2, 1);
			G.addeg(n*2+2, n+x, 0);
		}
		int f = G.mxflow(n*2+1, n*2+2);
		for(int x=1; x<=n; x++)
		{
			for(int e=G.fst[x]; ~e; e=G.nxt[e])
			{
				if(G.v[e]>n && G.v[e]<=n*2 && !G.w[e])
				{
					assert(have[x][G.v[e]-n].size());
					B[x][i] = have[x][G.v[e]-n].back();
					have[x][G.v[e]-n].pop_back();
				}
			}
		}
	}
	for(int i=1; i<=n; i++)
		for(int j=1; j<=m; j++)
