		flow.fill(s,t);
		for(int k=0;k<flow.es.size();k++){
			Edge& e=flow.es[k];
			if(e.f)
			{
				if(e.ob){
					b[e.a][j]=e.ob;
					c[e.b-N][j]=e.ob;
					e.f=0;
					e.c=0;
				}
				else{
					e.f=0;
					e.c=1;
				}
			}
		}
	}

