int main() {
    setIO();

    const string C = "RBG";

    int N; re(N); string S; re(S);

    vvi apps(3);
    F0R (i, 3 * N) apps[C.find(S[i])].pb(i);

    vb middle(3 * N);
    F0R (i, N) {
        vi locs{apps[0][i], apps[1][i], apps[2][i]};
        sort(all(locs));
        middle[locs[1]] = true;
    }

    mn ans = mn::fact(N);

    F0R (rep, 2) {
        int r = 0, g = 0, b = 0;
        F0R (i, 3 * N) {
            if (S[i] == 'R') {
                if (middle[i]) {
                    if (g > 0) ans *= g--, b--;
                    if (b > 0) ans *= b--, g--;
                } else r++;
            } else if (S[i] == 'G') {
                if (middle[i]) {
                    if (b > 0) ans *= b--, r--;
                    if (r > 0) ans *= r--, b--;
                } else g++;
            } else {
                if (middle[i]) {
                    if (g > 0) ans *= g--, r--;
                    if (r > 0) ans *= r--, g--;
                } else b++;
            }
        }
        reverse(all(middle));
        reverse(all(S));
    }

    ps(ans);

    return 0;
}

