const int N = 1e2+10;
#define fr(i,low,up,st) for(int i = low;i <= (int)up;i += st)
#define nfr(i,low,up,st) for(int i = low;i >= (int)up;i -= st)
#define sz(a) a.siz()
#define clr(a) memset(a,0,sizeof a)

vector<int> e[N];
int y[N],vis[N],a[N][N];

bool solve(int x){
   fr(i,0,e[x].size()-1,1){
      int w = e[x][i];
      if(!vis[w]){
         vis[w] = 1;
         if(!y[w] || solve(y[w])){
            y[w] = x;
            return true;
         }
      }
   }
   return false;
}

int n,m,t;
int mk[N][N];
int ivis[N][N];
