bool try_kuhn (int v, vector<bool> &used, vector<vector<int>> &g, vector<int> &mt) {
    if (used[v])  return false;
    used[v] = true;
    for (size_t i=0; i<g[v].size(); ++i) {
        int to = g[v][i];
        if (mt[to] == -1 || try_kuhn (mt[to], used, g, mt)) {
            mt[to] = v;
            return true;
        }
    }
    return false;
}

vector<int> matching(vector<vector<int>> &G)
{
    vector<int> mt(n, -1);
    vector<bool> used(n, false);
    for (int v=0; v<n; ++v) {
        used.assign (n, false);
        try_kuhn (v, used, G, mt);
    }
    vector<int> answer(n, -1);
    for (int i = 0; i<n; i++) if (mt[i]!=-1) answer[i] = mt[i];
    return answer;
}



