	Qu.push(s);
	while (!Qu.empty())
	{
		int u = Qu.front();
		Qu.pop();
		for (int i = head[u]; i; i = edge[i].nxt)
		{
			int to = edge[i].to;
			if (edge[i].w && to != s && !dis[to])
				dis[to] = dis[u] + 1, Qu.push(to);
		}
	}
	return (bool)dis[t];
}
int dfs(int u, int mini)
{
	if (u == t || !mini) return mini;
	int w, used = 0;
	for (int &i = cur[u]; i; i = edge[i].nxt)
	{
		int to = edge[i].to;
		if (dis[to] == dis[u] + 1 && edge[i].w)
		{
			w = dfs(to, min(edge[i].w, mini - used));
			edge[i].w -= w, edge[((i - 1) ^ 1) + 1].w += w, used += w;
		}
	}
	return used;
}
void dinic(void)
{
	while (bfs())
	{
		memcpy(cur, head, sizeof(cur));
		dfs(s, 0x3f3f3f3f);
	}
}
