bool check(int cur)
{
    for (int i = 1; i <= n; ++i) {
        if (!sum[cur][i] || vis[i]) continue;
        vis[i] = 1;
        if (!co[i] || check(co[i])) {
            co[i] = cur;
            return true;
        }
    }
    return false;
}

int main()
{
