    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            cin >> a[i][j];
            int group = (a[i][j]-1)/m+1;
            ++sum[i][group];
        }
    }
    // phase 1
    for (int j = 1; j <= m; ++j) {
        memset(co, 0, sizeof co);
        for (int i = 1; i <= n; ++i) {
