void solve() {
  int n, m; cin >> n >> m;
  Graph<int> a(n, vi(m)); cin >> a;

  vi pos(n*m+1);
  rep(i,n) rep(j,m) pos[a[i][j]] = i;

  vector<set<int>> column(n), num(n);
  rep(i,n) for (auto &v : a[i]) column[i].emplace(v);
  rep(i,n) rep1eq(j,m) num[i].emplace(i*m + j);

  Graph<int> b(n, vi(m));

  rep(j,m) {
    auto s = column;
    auto t = num;
    set<int> rest;
    rep(i,n) rest.emplace(i);
    queue<int> only;

    while (!rest.empty()) {
      only.emplace(*begin(s[*begin(rest)]));

      while (!only.empty()) {
        while (!only.empty()) {
          int v = only.front(); only.pop();
          if (pos[v] == -1) continue;
          b[pos[v]][j] = v;

          for (auto &u : s[pos[v]]) {
            t[(u-1) / m].erase(u);
          }
          s[pos[v]].clear();
          column[pos[v]].erase(v);

          for (auto &u : t[(v-1) / m]) {
            s[pos[u]].erase(u);
          }
          t[(v-1) / m].clear();
          num[(v-1) / m].erase(v);

          rest.erase(pos[v]);
          pos[v] = -1;
        }

        for (auto &x : s) {
          if (x.empty()) continue;
          int MIN = (*begin(x) - 1) / m;
          int MAX = (*rbegin(x) - 1) / m;
          if (MIN == MAX) only.emplace(*begin(x));
        }

        for (auto &x : t) {
          if (x.size() == 1) only.emplace(*begin(x));
        }
      }
    }
  }

  Graph<int> c(n, vi(m));

  rep(j,m) {
    rep(i,n) {
      c[(b[i][j] - 1) / m][j] = b[i][j];
    }
  }

  cout << b << endl;
  cout << c << endl;
}


