int DFS(int x, int minVal)
{
    if(x==T) return minVal;

    for(int i = startInd[x];i<graph[x].size();i++)
    {
        edge e = graph[x][i];
        if(dist[e.v]==dist[x]+1 && cap[e.edgeInd]>0)
        {
            int flow = DFS(e.v, min(minVal, cap[e.edgeInd]));
            if(flow>0)
            {
                //cout << x << " -> " << e.v << '\n';

                cap[e.edgeInd] -= flow;
                cap[e.edgeInd^1] += flow;

                return flow;
            }
        }

        startInd[x]++;
    }

    return 0;
}

int Dinic()
{
    int maxFlow = 0;
    while(true)
    {
        BFS();
        if(dist[T]==0) break;

        memset(startInd, 0, sizeof(startInd));
        while(true)
        {
            int flow = DFS(S, 1);
            if(flow==0) break;

            //cout << "---- += " << flow << '\n';
            maxFlow += flow;
        }
    }

    return maxFlow;
}

