void Kuhn(const vector<vector<int>> &gr, vector<int> &rd)
{
	vector<bool> matched(gr.size());

	bool loop = true;

	while (loop)
	{
		loop = false;

		vector<bool> used(gr.size());

		for (int i = 0; i < gr.size(); i++)
			if (!matched[i])
				loop |= matched[i] = dfs(gr, used, rd, i);
	}
}


void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n, m;

	cin >> n >> m;

	vector<vector<int>> matr(n, vector<int>(m));

	for (auto &row : matr)
		for (auto &it : row)
		{
			cin >> it;
			it--;
		}


	vector<vector<int>> gr(n);


	for (int r = 0; r < n; r++)
		for (auto it : matr[r])
			gr[r].push_back(it / m);


	vector<vector<int>> transpone(m, vector<int> (n));

	for (auto &col : transpone)
	{
		vector<int> rd(n, -1);

		Kuhn(gr, rd);

		for (int i = 0; i < rd.size(); i++)
		{
			col[rd[i]] = i;

			gr[rd[i]].erase(find(gr[rd[i]].begin(), gr[rd[i]].end(), i));
		}
	}

	for (int r = 0; r < n; r++)
		for (int c = 0; c < m; c++)
		{
			int pos = 0;

			while (pos < matr[r].size() && matr[r][pos] / m != transpone[c][r])
				pos++;

			assert(pos < matr[r].size());

			transpone[c][r] = matr[r][pos];

			swap(matr[r][pos], matr[r].back());
			matr[r].pop_back();
		}


	for (int i = 0; i < n; i++)
	{
		for (const auto &row : transpone)
			cout << row[i] + 1 << ' ';
		cout << endl;
	}

	for (auto &row : transpone)
		sort(row.begin(), row.end());

	for (int i = 0; i < n; i++)
	{
		for (const auto &row : transpone)
			cout << row[i] + 1 << ' ';
		cout << endl;
	}
}


