#include <bits/stdc++.h>
using namespace std;
#define pb push_back
const int N=105;
int a[N][N],n,m;
bool was[N][N];
void rot(int x)
{
	int tmp=a[x][1];
	for(int i=2;i<=m;i++) a[x][i-1]=a[x][i];
	a[x][m]=tmp;
}
void SolveRow(int x)
{
	sort(a[x]+1,a[x]+1+m);
	int cnt=0;
	while(1)
	{
		bool ok=1;
		for(int i=1;i<=m;i++) if(was[i][(a[x][i]-1)/m]){ ok=0;break;}
		if(ok) break;
		rot(x);
		cnt++;
		assert(cnt!=m);
	}
	for(int i=1;i<=m;i++) was[i][(a[x][i]-1)/m]=1;
}
void SortCol(int y)
{
	vector<int> tmp;
	for(int i=1;i<=n;i++) tmp.pb(a[i][y]);
	sort(tmp.begin(),tmp.end());
	for(int i=1;i<=n;i++) a[i][y]=tmp[i-1];
}
int cnt[N][N];
vector<int> my[N][N];
bool use[N],cws[N];
struct Edge
{
	int u,v,c;
	Edge(){}
	Edge(int a, int b, int d):u(a),v(b),c(d){}
};
vector<Edge> edges;
int s,t;
const int M=2*N;
vector<int> G[M];
void AddEdge(int u, int v)
{
	G[u].pb(edges.size());
	edges.pb(Edge(u,v,1));
	G[v].pb(edges.size());
	edges.pb(Edge(v,u,0));
}
int go[M];
bool bfs_was[M];
bool BFS()
{
	for(int i=s;i<=t;i++) bfs_was[i]=0;
	bfs_was[s]=1;
	queue<int> q;
	q.push(s);
	while(q.size())
	{
		int u=q.front();
		q.pop();
		for(int e:G[u])
		{
			int v=edges[e].v;
			int c=edges[e].c;
			if(c && !bfs_was[v])
			{
				bfs_was[v]=1;
				q.push(v);
				go[v]=e;
			}
		}
	}
	return bfs_was[t];
}
vector<int> Matching()
{
	int Flow=0;
	while(BFS())
	{
		for(int i=t;i!=s;i=edges[go[i]].u)
		{
			edges[go[i]].c--;
			edges[go[i]^1].c++;
		}
		Flow++;
	}
	if(Flow!=n)
	{
		while(clock()<15*CLOCKS_PER_SEC) n++;
	}
	vector<int> ans(n,0);
	for(Edge E:edges)
	{
		if(E.u==s || E.v==t) continue;
		if(E.u<=n && E.v>n && E.c==0) ans[E.u-1]=E.v-n-1;
	}
	return ans;
}
void Clear()
{
	for(int i=s;i<=t;i++) G[i].clear();
	edges.clear();
}
