using namespace std;
//ruogu_alter
const int N=105;
int n,m,s,t,a[N][N],dis[N<<1],iter[N<<1],px[N*N],py[N*N],res[N][N];
queue<int>qu;
vector<int>v[N][N];
struct edge{
	int to,val,rev;
};
vector<edge>g[N<<1];
//
inline void addedge(int x,int y,int val){
	g[x].push_back((edge){y,val,g[y].size()});
	g[y].push_back((edge){x,0,g[x].size()-1});
}
bool bfs(){
	memset(dis,-1,sizeof(dis));
	dis[s]=0;qu.push(s);
	while(!qu.empty()){
		int u=qu.front();qu.pop();
		rep(i,g[u].size()){
			edge &e=g[u][i];
			if(e.val&&dis[e.to]==-1){
				dis[e.to]=dis[u]+1;
				qu.push(e.to);
			}
		}
	}
	return dis[t]>=0;
}
int dfs(int x,int val){
	if(x==t)return val;
	while(iter[x]<g[x].size()){
		edge &e=g[x][iter[x]];
		if(dis[e.to]>dis[x]&&e.val){
			int ans=dfs(e.to,min(val,e.val));
			if(ans){
				e.val-=ans;
				g[e.to][e.rev].val+=ans;
				return ans;
			}
		}
		iter[x]++;
	}
	return 0;
}
int dinic(){
	int ans=0;
	while(bfs()){
		int f;
		memset(iter,0,sizeof(iter));
		while(f=dfs(s,INF))ans+=f;
	}
	return ans;
}
void P(){
	rep(i,n*m)res[px[i]][py[i]]=i;
	rep(i,n){
		rep(j,m)printf("%d ",res[i][j]+1);
		printf("\n");
	}
}
int main(){
	//freopen(".in","r",stdin);
	//freopen(".out","w",stdout);
	n=getint();m=getint();s=2*n;t=s+1;
	rep(i,n)rep(j,m){
		a[i][j]=getint()-1;
		v[i][a[i][j]/m].push_back(a[i][j]);
	}
	memset(px,-1,sizeof(px));
	memset(py,-1,sizeof(py));
	rep(x,m){
		rep(i,2*n+2)g[i].clear();
		rep(i,n)rep(j,n)if(v[i][j].size())addedge(i,j+n,1);
		rep(i,n)addedge(s,i,1),addedge(i+n,t,1);
		assert(dinic()==n);
		rep(i,n)rep(j,g[i].size())if(!g[i][j].val){
			int y=g[i][j].to-n,id=v[i][y].back();
			v[i][y].pop_back();
			px[id]=i;py[id]=x;
		}
	}
	P();
	rep(i,n*m)px[i]=i/m;
	P();
	return 0;
}

