namespace NetFlow
{
    const int N = 202;
    const int M = 40400;
    const int INF = 1e7;
    struct Edge
    {
        int v,w,nxt,rev;
    } e[(M<<1)+3];
    int fe[N+3];
    int te[N+3];
    int dep[N+3];
    int que[N+3];
    int n,en;
    void addedge(int u,int v,int w)
    {
//      printf("addedge%d %d %d\n",u,v,w);
        en++; e[en].v = v; e[en].w = w;
        e[en].nxt = fe[u]; fe[u] = en; e[en].rev = en+1;
        en++; e[en].v = u; e[en].w = 0;
        e[en].nxt = fe[v]; fe[v] = en; e[en].rev = en-1;
    }
    bool bfs()
    {
        for(int i=1; i<=n; i++) dep[i] = 0;
        int head = 1,tail = 1; que[tail] = 1; dep[1] = 1;
        while(head<=tail)
        {
            int u = que[head]; head++;
            for(int i=fe[u]; i; i=e[i].nxt)
            {
                if(dep[e[i].v]==0 && e[i].w>0)
                {
                    dep[e[i].v] = dep[u]+1;
                    tail++; que[tail] = e[i].v;
                }
            }
        }
        return dep[2]!=0;
    }
    int dfs(int u,int cur)
    {
        if(u==2) {return cur;}
        int rst = cur;
        for(int i=te[u]; i; i=e[i].nxt)
        {
            if(dep[e[i].v]==dep[u]+1 && e[i].w>0 && rst>0)
            {
                int flow = dfs(e[i].v,min(rst,e[i].w));
                if(flow>0)
                {
                    e[i].w-=flow; e[e[i].rev].w += flow; rst-=flow;
                    if(e[i].w>0) {te[u] = i;}
                    if(rst==0) {return cur;}
                }
            }
        }
        if(cur==rst) {dep[u] = 0;}
        return cur-rst;
    }
    void dinic(int _n)
    {
        n = _n;
        int ret = 0;
        while(bfs())
        {
            for(int i=1; i<=n; i++) te[i] = fe[i];
            ret += dfs(1,INF);
        }
//      printf("ret=%d\n",ret);
    }
    void clear()
    {
        for(int i=1; i<=en; i++) e[i].v = e[i].w = e[i].nxt = e[i].rev = 0;
        for(int i=1; i<=n; i++) dep[i] = fe[i] = que[i] = te[i] = 0;
        n = en = 0;
    }
}
