    vector <pii> t;
    REP(j, m) t.pb({p[i][j] % m, p[i][j]});
    sort(all(t));
    REP(j, m) p[i][j] = t[j].sec;
  }

  if (p1 != p) ans1.pb(p);
  if (p != kraj) ans1.pb(kraj);

  if (ans.empty() || ans1.size() < ans.size()) ans = ans1;

  return true;
}

void solve() {
  scanf("%d %d",&n,&m);
  init();
  REP(i, n) {
    REP(j, m) {
      kraj[i][j] = i * m + j;
      scanf("%d",&p[i][j]);
      p[i][j]--;
      cnt_col[j][p[i][j] / m]++;
    }
  }


  if (p == kraj) {
    puts("0");
    return;
  }

  bool ok = 1;
  REP(i, n) {
    REP(j, m) {
      if (cnt_col[i][j] != 1) ok = 0;
    }
  }

  mat last = p;
  if (ok) {
    mat p1 = p;
    REP(j, m) {
      vector <int> tu;
      REP(i, n) tu.pb(p[i][j]);
      sort(all(tu));
      REP(i, n) p[i][j] = tu[i];
    }
    if (p != p1) ans.pb(p);
    if (p != kraj) ans.pb(kraj);
  }
  p = last;

  if (check2() || ok) {
    //printf("%d\n",(int)ans.size());
    for (auto &t : ans) print(t);
    return;
  }

  p = last;

  mat pom;
  pom.resize(n, vector<int>(m, 0));


  REP(col, m) {
    M.init(n, n);
    set <int> fiks;
    REP(i, n) if (kraj[i][col] == p[i][col]) fiks.insert(i);
    REP(i, n) {
      vector <int> color(n, -1);
      if (fiks.count(i)) {
        M.edge(i, p[i][col] / m);
        pom[i][col] = p[i][col];
        continue;
      }
      REP(j, m) {
        if (uzet[i][j] || color[p[i][j] / m] != -1 || kraj[i][j] == p[i][j]) continue;
        color[p[i][j] / m] = p[i][j];
        M.edge(i, p[i][j] / m);
      }
    }
    auto par = M.run();
    REP(i, n) {
      vector <int> color(n, -1);
      if (fiks.count(i)) continue;
      REP(j, m) {
        if (uzet[i][j] || color[p[i][j] / m] != -1 || kraj[i][j] == p[i][j]) continue;
        if (par[p[i][j]/m+n] != i) continue;
        color[p[i][j] / m] = p[i][j];
        pom[i][col] = p[i][j];
        uzet[i][j] = 1;
      }
    }
  }

  ans.pb(pom);
  mat p1 = pom;
  REP(j, m) {
    vector <int> tu;
    REP(i, n) tu.pb(pom[i][j]);
    sort(all(tu));
    REP(i, n) pom[i][j] = tu[i];
  }
  if (p1 != pom) ans.pb(pom);
  if (pom != kraj) ans.pb(kraj);
  //printf("%d\n",(int)ans.size());
  for (auto &t : ans) print(t);
}

int main() {
  int t;
  //scanf("%d",&t);
  t = 1;
  while (t--) solve();
  return 0;
}

