struct BipartiteMatching {
  vector<vector<int>> graph;
  vector<int> match,used;

  BipartiteMatching(int n):graph(n),used(n, 0),match(n, -1){}

  void add_edge(int u,int v){
    graph[u].push_back(v);
    graph[v].push_back(u);
  }

  bool dfs(int now){
    used[now]=1;
    for(auto to:graph[now]){
      int to_match=match[to];
      if(to_match==-1||(!used[to_match]&&dfs(to_match))){
        match[now]=to;
        match[to]=now;
        return true;
      }
    }
    return false;
  }

  int bipartite_matching(){
    int res=0;
    for(int i=0;i<graph.size();i++){
      if(match[i]==-1){
        for(int j=0;j<graph.size();j++) used[j]=0;
        if(dfs(i)) res++;
      }
    }
    return res;
  }
};

int N,M;
int A[101][101];

set<int> se[101];
int B[101][101];
int C[101][101];

void solve(int col){
  BipartiteMatching BG(2*N+1);
  for(int i=0;i<N;i++){
    vector<int> used(N+1,0);
    for(auto val:se[i]){
      int t=(val-1)/M;
      if(used[t]) continue;
      used[t]=true;
      BG.add_edge(i,N+t);
    }
  }

  int m=BG.bipartite_matching();

  for(int i=0;i<N;i++){
    int tar=BG.match[i]-N;
    auto itr=se[i].lower_bound(tar*M+1);

    B[i][col]=*itr;
    se[i].erase(itr);
  }
  return;
}


int main(){
  cin>>N>>M;
  for(int i=0;i<N;i++){
    for(int j=0;j<M;j++){
      cin>>A[i][j];
      se[i].insert(A[i][j]);
    }
  }

  for(int i=0;i<M;i++) solve(i);

  for(int i=0;i<M;i++){
    vector<int> v;
    for(int j=0;j<N;j++) v.push_back(B[j][i]);
    sort(v.begin(),v.end());
    for(int j=0;j<N;j++) C[j][i]=v[j];
  }

  for(int i=0;i<N;i++){
    for(int j=0;j<M;j++) cout<<B[i][j]<<" ";
    cout<<endl;
  }

  for(int i=0;i<N;i++){
    for(int j=0;j<M;j++) cout<<C[i][j]<<" ";
    cout<<endl;
  }

  return 0;
}

