}

const int N=105;
namespace G{
	int f[N][N],x[N],y[N],vis[N],n,tim;
	inline void init(int _n){
		n=_n,tim=1;
		memset(f,0,sizeof f);
		memset(vis,0,sizeof vis);
		memset(x,0,sizeof x);
		memset(y,0,sizeof y);
	}
	int dfs(int u){
		vis[u]=tim;
		rep(v,1,n)
			if(f[u][v]){
				if(!y[v]||vis[y[v]]!=tim&&dfs(y[v])){
					y[v]=u,x[u]=v;
					return 1;
				}
			}
		return 0;
	}
	inline void solve(){
		rep(i,1,n)
			if(!x[i]){
				assert(dfs(i));
				tim++;
			}
		// cerr<<tim<<endl;
	}
}
