const int N = 102;

int n, m;
int a[N][N];
int p[N * 2];
int vis;
int used[N];
vector<int> edge[N];

bool dfs(int i) {
	if (used[i] == vis) return false;
	used[i] = vis;
	for (auto j : edge[i]) {
		if (p[j] == -1 || dfs(p[j])) {
			p[i] = j;
			p[j] = i;
			return true;
		}
	}
	return false;
}

