int n,m;

int if_swap(int i, int x, int y){
    int p = a[i][x]/m, q = a[i][y]/m;
    if(p==q)return 0;
    int diff = 0;
    diff += -cnt[x][p];
    diff += cnt[x][q];
    diff += -cnt[y][q];
    diff += cnt[y][p];
    return diff+2;
}

int do_swap(int i, int x, int y){
    int p = a[i][x]/m, q = a[i][y]/m;
    if(p==q)return 0;
    --cnt[x][p];++cnt[x][q];
    --cnt[y][q];++cnt[y][p];
    swap(a[i][x], a[i][y]);
    return 0;
}
struct Xor128{
    unsigned x,y,z,w;

    Xor128(unsigned w_=88675123):x(123456789),y(362436069),z(521288629),w(w_){};

    inline unsigned xor128(){
        unsigned t;
        t = x^(x<<11);
        x = y;
        y = z;
        z = w;
        return w = (w^(w>>19))^(t^(t>>8));
    }

    int nextInt(int x,int y){
        if(x>y)swap(x,y);
        return xor128()%(y-x)+x;
    }

    double nextDouble(double a,double b){
        return (double)(xor128()&0xffff)/0xffff*(b-a)+a;
    }

};

