	void insert(int a,int b,int c){
		int T1=++tot,T2=++tot,T3=++tot;
		T[hang[a+1]].D=T1,T[hang[b+1]].D=T2,T[hang[c+1]].D=T3;
		T[T1].U=hang[a+1],T[T2].U=hang[b+1],T[T3].U=hang[c+1];
		T[T1].D=a+1,T[T2].D=b+1,T[T3].D=c+1;
