		T[T[now].L].R=T[now].R;
		T[T[now].R].L=T[now].L;
		for (int i=T[now].D;i!=now;i=T[i].D){
			for (int j=T[i].R;j!=i;j=T[j].R){
				T[T[j].U].D=T[j].D;
				T[T[j].D].U=T[j].U;
			}
		}
	}
	void recover(int now){
		for (int i=T[now].D;i!=now;i=T[i].D){
			for (int j=T[i].R;j!=i;j=T[j].R){
				T[T[j].U].D=j;
				T[T[j].D].U=j;
			}
		}
		T[T[now].L].R=now;
		T[T[now].R].L=now;
	}

