	public:
		PR(int n) {
			g.assign(n,vector<Edge>());
			ec.assign(n,0);
			cur.assign(n,nullptr);
			hs.assign(2*n,vi());
			H.assign(n,0);
		}
		void add(int s, int t, Flow cap, Flow rcap=0) {
			if(s == t) return;
			Edge a = {t,int(g[t].size()),0,cap};
			Edge b = {s,int(g[s].size()),0,rcap};
			g[s].push_back(a);
			g[t].push_back(b);
		}
		void addf(Edge& e, Flow f) {
			Edge& back = g[e.dest][e.back];
			if(!ec[e.dest] && f) {hs[H[e.dest]].push_back(e.dest);}
			e.f += f;e.c -= f;
			ec[e.dest] += f;
			back.f -= f;
			back.c += f;
			ec[back.dest] -= f;
		}
		Flow maxflow(int s, int t) {
			int v = g.size();
			H[s] = v;ec[t] = 1;
			vi co(2*v);
			co[0] = v-1;
			for(int i=0;i<v;i++) {cur[i] = g[i].data();}
			for(auto& e: g[s]) {
				addf(e,e.c);
			}
			for(int hi = 0;;) {
				while(hs[hi].empty()) {if(!hi--) return -ec[s];}
				int u = hs[hi].back();hs[hi].pop_back();
				while(ec[u] > 0) {
					if(cur[u] == g[u].data() + g[u].size()) {
						H[u] = 1e9;
						for(auto& e: g[u]) {
							if(e.c && H[u] > H[e.dest]+1) {
								H[u] = H[e.dest]+1;cur[u] = &e;
							}
						}
						if(++co[H[u]],!--co[hi] && hi < v) {
							for(int i=0;i<v;i++) {
								if(hi < H[i] && H[i] < v) {--co[H[i]];H[i] = v+1;}
							}
						}
						hi = H[u];
					} else if(cur[u] -> c && H[u] == H[cur[u]->dest]+1) {
						addf(*cur[u],min(ec[u],cur[u]->c));
					} else {
						++cur[u];
					}
				}
			}
			return -1;
		}
		bool leftMinCut(int a) {
			return H[a] >= g.size();
		}
		int find(int u) {
			for(int i=0;i<g[u].size();i++) {
				Edge& e = g[u][i];
				if(e.f == 1) {return e.dest;}
			}
			return -1;
		}
};
