        int cnt[105] = {};

        for (int j = 0; j < m; j++) {
            ll r = (a[i][j] - 1) / m;

            for (int k = 0; k < m; k++) {
                if (!used[k][r]) cnt[j]++;
            }
        }

        for (int j = 0; j < m; j++) {
            ll mpos = 0;

            for (int k = 1; k < m; k++) {
                if (cnt[mpos] > cnt[k]) {
                    mpos = k;
                }
            }

            ll r = (a[i][mpos] - 1) / m;
            for (int k = 0; k < m; k++) {
                if (!used[k][r]) {
                    swap(a[i][k], a[i][mpos]);
                    used[k][r] = true;
                    break;
                }
            }

            cnt[mpos] = 1 << 27;
        }
    }

    if (!ok(n - 1)) return 1;

    //1.out
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m - 1; j++) {
            cout << a[i][j] << ' ';
        }
        cout << a[i][m - 1] << endl;
    }

    //2.
    for (int k = 0; k < m; k++) {
        for (int i = 0; i < n; i++) {
            int mpos = i;
            for (int j = i + 1; j < n; j++) {
                if (a[j][k] < a[mpos][k]) {
                    mpos = j;
                }
            }
            swap(a[mpos][k], a[i][k]);
        }
    }

    //2.out
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m - 1; j++) {
            cout << a[i][j] << ' ';
        }
        cout << a[i][m - 1] << endl;
    }

    return 0;
}

void roll(ll a[]) {
    ll tmp = a[0];
    for (int i = 0; i < m - 1; i++) {
        a[i] = a[i + 1];
    }
    a[m - 1] = tmp;
}

bool ok(ll k) {
    int used[105][105] = {};

    for (int i = 0; i <= k; i++) {
        for (int j = 0; j < m; j++) {
            ll r = (a[i][j] - 1) / m;

            if (used[j][r]) return false;
            used[j][r] = true;
        }
    }

    return true;
}

