struct BPM {
    vi adj[MAXN];
    int l, r, dist[MAXN], match[MAXN];

    void init(int l1, int r1) {
        l = l1, r = r1;
    }

    void addEdge(int u, int v) {
        adj[u].pb(v + l);
        adj[v + l].pb(u);
    }

    void reset() {
        for (int i = 0; i <= l + r; i++)
            adj[i].clear();
        l = 0, r = 0;
    }

    bool dfs(int u) {
        if (u == 0) return 1;
        for (int v: adj[u]) {
            if (dist[match[v]] == dist[u] + 1 && dfs(match[v])) {
                match[v] = u;
                match[u] = v;
                return 1;
            }
        }
        dist[u] = INF;
        return 0;
    }

    bool bfs() {
        deque<int> pq;
        for (int i = 1; i <= l; i++) {
            if (match[i] == 0) {
                dist[i] = 0;
                pq.pb(i);
            } else
                dist[i] = INF;
        }
        dist[0] = INF;
        while (!pq.empty()) {
            int u = pq.front(); pq.pop_front();
            if (u == 0) continue;
            for (int v: adj[u]) {
                if (dist[match[v]] == INF) {
                    dist[match[v]] = dist[u] + 1;
                    pq.pb(match[v]);
                }
            }
        }
        if (dist[0] == INF)
            return 0;
        return 1;
    }

    // runtime: O(sqrt(V)E)
	// l nodes left, r nodes right
    int matching() {
        int ret = 0;
        memset(match, 0, sizeof match);
        while (bfs())
            for (int i = 1; i <= l; i++)
                if (match[i] == 0 && dfs(i))
                    ret++;
        return ret;
    }
