	}
}
bool used[MAXN];
int par[MAXN];

int k;
vector <int> graph[MAXN];
int tr[MAXN];

bool try_kuhn(int p)
{
	if(used[p]) return false;
	used[p] = true;

	int z = graph[p].size();
	for(int i = 0; i < z; i++)
	{
		int to = graph[p][i];
		if(par[to] == -1 || try_kuhn(par[to]))
		{
			par[to] = p;
			tr[p] = to;
			return true;
		}
	}
	return false;
}

bool mark[MAXN][MAXN];
int b1[MAXN][MAXN], b2[MAXN][MAXN];

void solve()
{
	bool fl = true;
	for(int z = 0; z < m; z++)
	{
        memset(par, -1, sizeof(par));

		for(int i = 0; i < n; i++)
        {
            graph[i].clear();
            for(int j = 0; j < m; j++)
            {
                if(!mark[i][j])
                {
                    int temp = a[i][j] / m;
                    graph[i].push_back(temp);
                }
            }
        }

		for(int j = 0; j < n; j++)
		{
			memset(used, 0, sizeof(used));
			fl &= try_kuhn(j);
		}
		for(int i = 0; i < n; i++)
		{
			int temp = tr[i];

			for(int j = 0; j < m; j++)
            {
                if(a[i][j] / m == temp && !mark[i][j])
                {
                    mark[i][j] = true;
                    b1[i][z] = a[i][j];
                    break;
                }
            }
		}
	}

