class DinicMethod{
public:
	struct Edge{ ll to, cap, rev; };
	vector<vector<Edge>> G;
private:
	vll level;
	vll iter;
public:
	DinicMethod(ll nodeNum): G(nodeNum){}

	void Link(ll v, ll u, ll cap, ll rcap = 0){//v→uに重みcapで張る、逆辺も張る
		this->G[v].push_back({u,  cap, (ll)this->G[u].size()});
		this->G[u].push_back({v, rcap, (ll)this->G[v].size()-1});
	}

	ll MaxFlow(ll s, ll t){//s→tの最大流を求める
		ll f, flow = 0;
		while (true){
			this->BfsLevelRenew(s);
			if (this->level[t] < 0) return flow;
			iter.assign(this->G.size(), 0);
			while ((f = this->DfsFindPath(s, t, INF)) > 0) { flow += f; }
		}
	}

private:
	void BfsLevelRenew(ll s) {
		this->level.assign(this->G.size(), -1);
		this->level[s] = 0;
		queue<ll> que;
		que.push(s);
		while (!que.empty()){
			ll from = que.front(); que.pop();
			EACH(e, this->G[from]){
				if (e.cap > 0 && this->level[e.to] < 0){
					this->level[e.to] = this->level[from] + 1;
					que.push(e.to);
				}
			}
		}
	}

	ll DfsFindPath(ll v, ll t, ll f){
		if (v == t) return f;

		for (ll &i = iter[v]; i < (ll)this->G[v].size(); i++){
			Edge &e = this->G[v][i];
			if (e.cap > 0  &&  this->level[v] < this->level[e.to]){
				ll d = this->DfsFindPath(e.to, t, min(f, e.cap));
				if (d > 0){
					e.cap -= d;
					this->G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};

class DinicMatching{
private:
	DinicMethod dm;
	ll sNum, tNum, s, t;
public:
	DinicMatching(ll sNum, ll tNum): dm(sNum+tNum+2), sNum(sNum), tNum(tNum),
		s(sNum+tNum), t(sNum+tNum+1)
	{
		REP(i, sNum){ dm.Link(this->s, i, 1); }
		REP(i, tNum){ dm.Link(i+sNum, this->t, 1); }
	}

	void Link(ll sIdx, ll tIdx){ dm.Link(sIdx, tIdx + this->sNum, 1); }

	vector<pair<ll, ll>> GetMatch(){ //最大マッチングを得る
		ll matchNum = dm.MaxFlow(this->s, this->t);
		vector<pair<ll, ll>> matches;
		REP(v, this->sNum){//ソース側ノードをなめる
			EACH(e, dm.G[v]){
				if (e.cap == 0 && e.to != this->s){
					matches.emplace_back(v, e.to - sNum);
					break;
				}
			}
		}
		return move(matches);
	}
};


