int for_row[MAXN][MAXN];
bool used[MAXN];
int timer;
int par[MAXN];

int k;

bool try_kuhn(int p)
{
	if(used[p] == timer) return false;
	used[p] = timer;
	int j = a[k][p] / m;
	for(int i = 0; i < m; i++)
	{
		if(par[i] == -1 && for_row[i][j] == 0)
		{
			par[i] = p;
			for_row[i][j] = true;
			return true;
		}
		if(for_row[i][j] == 0)
		{
			int prev = a[k][par[i]] / m;
			if(try_kuhn(par[i]))
			{
				for_row[i][prev] = false;
				par[i] = p;
				for_row[i][j] = true;
				return true;
			}
		}
	}
	return false;
}

int b1[MAXN][MAXN], b2[MAXN][MAXN];

void solve()
{
	bool fl = true;
	for(int i = 0; i < n; i++)
	{
		k = i;
		memset(par, -1, sizeof(par));
		for(int j = 0; j < m; j++)
		{
			timer++;
			fl &= try_kuhn(j);
		}
		for(int j = 0; j < m; j++)
		{
			//printf("~%d ", par[j]);
			b1[i][j] = par[j];
		}
		//printf("\n");
	}
	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < m; j++)
		{
			if(j != m - 1)
			printf("%d ", a[i][b1[i][j]] + 1);
			b2[j][i] = a[i][b1[i][j]] + 1;
		}
		printf("%d\n", a[i][b1[i][m - 1]] + 1);
	}
	for(int i = 0; i < m; i++)
	{
		sort(b2[i], b2[i] + n);
	}

	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < m - 1; j++)
		{
			printf("%d ", b2[j][i]);
		}
		printf("%d\n", b2[m - 1][i]);
	}

	//printf("%d\n", fl);
}
