            REP(i2, N) if(B[i2][j] / M == i){
                C[i][j] = B[i2][j];
                break;
            }
        }
    }


    REP(i, N){
        REP(j, M){
            cout << C[i][j] + 1 << ' ';
        }
        cout << endl;
    }


    return 0;
}

