int n, m;

bool match(int p)
{
	chk1[p] = true;

	for(pii &t: V[p]){
		if(M[t.first] == -1 || (!chk1[M[t.first]] && match(M[t.first]))){
			M[t.first] = p; return 1;
		}
	}

	return 0;
}

int main()
{
	int i, j, k, f;

	scanf("%d%d", &n, &m);

	for(i=0; i<n; i++){
		for(j=0; j<m; j++){
			scanf("%d", A[i] + j);
			A[i][j] --;
			V[i].emplace_back(A[i][j] / m, A[i][j]);
		}
	}

	for(i=0; i<m; i++){
		for(j=0; j<n; j++){
			chk2[j] = false; M[j] = -1;
		}

