using namespace std;

struct BipartiteMatching {
  int n, m;
  vector<vector<int>> graph;
  vector<int> matched, match;
  vector<int> edgeview;
  vector<int> level;
  vector<int> reached[2];
  BipartiteMatching(int n, int m) : n(n), m(m), graph(n), matched(m, -1), match(n, -1) {}

  bool assignLevel() {
    bool reachable = false;
    level.assign(n, -1);
    reached[0].assign(n, 0);
    reached[1].assign(m, 0);
    queue<int> q;
    for (int i = 0; i < n; i++) {
      if (match[i] == -1) {
        level[i] = 0;
        reached[0][i] = 1;
        q.push(i);
      }
    }
    while (!q.empty()) {
      auto cur = q.front(); q.pop();
      for (auto adj : graph[cur]) {
        reached[1][adj] = 1;
        auto next = matched[adj];
        if (next == -1) {
          reachable = true;
        } else if (level[next] == -1) {
          level[next] = level[cur] + 1;
          reached[0][next] = 1;
          q.push(next);
        }
      }
    }
    return reachable;
  }

  int findpath(int nod) {
    for (int &i = edgeview[nod]; i < graph[nod].size(); i++) {
      int adj = graph[nod][i];
      int next = matched[adj];
      if (next >= 0 && level[next] != level[nod] + 1) continue;
      if (next == -1 || findpath(next)) {
        match[nod] = adj;
        matched[adj] = nod;
        return 1;
      }
    }
    return 0;
  }

  int solve() {
    int ans = 0;
    while (assignLevel()) {
      edgeview.assign(n, 0);
      for (int i = 0; i < n; i++)
        if (match[i] == -1)
          ans += findpath(i);
    }
    return ans;
  }
};

int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  vector<vector<int>> dat(n, vector<int>(m));
  BipartiteMatching bp(n, n);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      scanf("%d", &dat[i][j]);
      dat[i][j]--;
      int row = dat[i][j] / m;
      bp.graph[row].push_back(i);
    }
  }
  for (int col = 0; col < m; col++) {
    bp.solve();
    for (int row = 0; row < n; row++) {
      int i = bp.match[row];
      for (int j = col; j < m; j++) {
        if (dat[i][j] / m == row) {
          if (j != col) swap(dat[i][j], dat[i][col]);
          break;
        }
      }
      bp.graph[row].erase(find(bp.graph[row].begin(), bp.graph[row].end(), i));
    }
    bp.match.assign(n, -1);
    bp.matched.assign(n, -1);
  }
  vector<vector<int>> B = dat;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      printf("%d%c", B[i][j] + 1, " \n"[j + 1 == m?1:0]);
    }
  }
  vector<vector<int>> C(n, vector<int>(m));
  for (int j = 0; j < m; j++) {
    for (int i = 0; i < n; i++) {
      C[B[i][j] / m][j] = B[i][j];
    }
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      printf("%d%c", C[i][j] + 1, " \n"[j + 1 == m ? 1 : 0]);
    }
  }
  return 0;
}

