struct graph {
  bool mark[N];
  int mat[N][N];
  int match[N];
  int n;

  graph(int x = 0) {
    n = x;
    memset(mat, 0, sizeof mat);
  }

  void add_edge(int u, int v) {
    ++mat[u][v];
    ++mat[v][u];
  }

  void remove_edge(int u, int v) {
    --mat[u][v];
    --mat[v][u];
  }

  bool dfs(int u) {
    mark[u] = true;
    for (int i = 0; i < n; i++) {
      if (!mat[u][i]) {
        continue;
      }
      if (match[i] == -1 || (!mark[match[i]] && dfs(match[i]))) {
        match[u] = i;
        match[i] = u;
        return true;
      }
    }
    return false;
  }

  vector<int> matching(int upper_size) {
    memset(match, -1, sizeof match);
    while (true) {
      memset(mark, false, sizeof mark);
      bool found = false;
      for (int i = 0; i < upper_size; i++) {
        if (match[i] == -1) {
          found |= dfs(i);
        }
      }
      if (!found) {
        break;
      }
    }
    vector<int> res;
    for (int i = 0; i < upper_size; i++) {
      assert(~match[i]);
      res.push_back(match[i] - upper_size);
    }
    return res;
  }
};

