        }
    }
    for (int i = 1; i <= M; i++) {
        Dinic::Node *S = new Dinic::Node(), *T = new Dinic::Node(), *L[MAX_N], *R[MAX_N];
        for (int j = 1; j <= N; j++) {
            L[j] = new Dinic::Node();
            R[j] = new Dinic::Node(j);
