		}
	}
	// find M perfect matches
	for(int rep = 0; rep < m; rep++) {
		Dinic<int> graph(n+n+2);
		int src = n+n;
		int sink = src+1;
		for(int i = 0; i < n; i++) {
			for(int j = rep; j < m; j++) {
				graph.addEdge(i, n+(a[i][j]/m), 1);
			}
		}
		for(int i = 0; i < n; i++) {
			graph.addEdge(src, i, 1);
			graph.addEdge(n+i, sink, 1);
