	}
	// sort columns
	for(int j = 0; j < m; j++) {
		std::vector<int> ha(n);
		for(int i = 0; i < n; i++) {
			ha[i] = a[i][j];
		}
		std::sort(ha.begin(), ha.end());
		for(int i = 0; i < n; i++) {
			a[i][j] = ha[i];
		}
	}
	// print
	for(int i = 0; i < n; i++) {
		for(int j = 0; j < m; j++) {
			std::cout << a[i][j]+1 << (j + 1 == m ? '\n' : ' ');
		}
	}
}

