bool find(int i)
{
	for(int j = 1;j <= n;j ++)
		if(!vis[j] && E[i][j])
		{
			vis[j] = 1;
			if(!bel[j] || find(bel[j]))
			{
				bel[j] = i;
				return 1;
			}
		}
	return 0;
}
