#include <stdio.h>
#include <stdlib.h>

int H, W;

int g(int id) {
	return (id - 1) / W;
}

int cmp(const void* x, const void* y) {
	int a = *(const int*)x;
	int b = *(const int*)y;
	if (a < b) return -1;
	return a > b;
}

int A[128][128];
int B[128][128];
int C[128][128];

int main(void) {
	int i, j, k;
	if (scanf("%d%d", &H, &W) != 2) return 1;
	for (i = 0; i < H; i++) {
		for (j = 0; j < W; j++) {
			if (scanf("%d", &A[i][j]) != 1) return 1;
		}
	}

	/* コピー */
	for (i = 0; i < H; i++) {
		for (j = 0; j < W; j++) {
			B[i][j] = A[i][j];
		}
	}
	/* 順番に構築する */
	for (j = 0; j < W; j++) {
		int thisCount[128] = {0};
		int ttl = H * 10;
		for (i = 0; i < H; i++) {
			thisCount[g(B[i][j])]++;
		}
		for (;;) {
			int found = 0;
			int proceed = 0;
			for (i = 0; i < H; i++) {
				if (thisCount[g(B[i][j])] > 1) {
					found = 1;
					for (k = j + 1; k < W; k++) {
						if (thisCount[g(B[i][k])] == 0) {
							int t = B[i][j];
							B[i][j] = B[i][k];
							B[i][k] = t;
							thisCount[g(B[i][j])]++;
							thisCount[g(B[i][k])]--;
							proceed = 1;
							break;
						}
					}
				}
			}
			if (!found) break;
			if (!proceed) {
				for (i = 0; i < H; i++) {
					for (k = j + 1; k < W; k++) {
						if (thisCount[g(B[i][k])] == 0) {
							int t = B[i][j];
							B[i][j] = B[i][k];
							B[i][k] = t;
							thisCount[g(B[i][j])]++;
							thisCount[g(B[i][k])]--;
							proceed = 1;
							break;
						}
					}
				}
			}
			if (!proceed || --ttl <= 0) {
				if (ttl > 0) {
					puts("error! (not found)");
				} else {
					puts("error! (TTL expired)");
				}
				if (W <= 26) {
					for (i = 0; i < H; i++) {
						printf("%c", 'A' + g(B[i][0]));
						for (j = 1; j < W; j++) {
							printf(" %c", 'A' + g(B[i][j]));
						}
						putchar('\n');
					}
				}
				return 1;
			}
		}
	}

	/* コピー */
	for (i = 0; i < H; i++) {
		for (j = 0; j < W; j++) {
			C[j][i] = B[i][j];
		}
	}
	/* ソート */
	for (j = 0; j < W; j++) {
		qsort(C[j], H, sizeof(int), cmp);
	}

	/* 出力 */
	for (i = 0; i < H; i++) {
		printf("%d", B[i][0]);
		for (j = 1; j < W; j++) {
			printf(" %d", B[i][j]);
		}
		putchar('\n');
	}
	for (i = 0; i < H; i++) {
		printf("%d", C[0][i]);
		for (j = 1; j < W; j++) {
			printf(" %d", C[j][i]);
		}
		putchar('\n');
	}

	return 0;
}

