    if(g[x[vst].st+ptr[vst]].cap>0 && dist[vst] < dist[g[x[vst].st+ptr[vst]].fi]){
      d=rep(g[x[vst].st+ptr[vst]].fi,vfi,llmin(nf,g[x[vst].st+ptr[vst]].cap),g,x,dist,ptr);
      if(d>0){
        g[x[vst].st+ptr[vst]].cap-=d;
