public class Main implements Runnable{

	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * AGC037 D問題
		 * 考察メモ
		 * 2回目の操作が終わった時点で、列についてMで割った値(端数切り上げ)では全て同じ値になる
		 * これを満たすためにはどのような操作が必要か考える
		 * 1回目の操作が終わった時点で、各行ではNで割った値が等しくならないようにしたい
		 * そのような操作を最初の操作で行えるように下準備をしたいわけだ
		 * これは可能であり、上の列に注目する(以降割った値で表記)
		 * 1 1 2 2 ⇒ 1 1 2 2
		 * 2 2 3 4 ⇒ 2 2 3 4
		 * 1 1 3 4 ⇒ 3 4 1 1
		 * 3 3 4 4 ⇒ 4 3 4 3
		 * とか考えたとして、性質上まだ使ってない数は必ずあるし、適当に取っても矛盾は起きない(多分)
		 * あとは、これを順列にしていくのは簡単なので割愛
		 *
		 * さて、具体的に上を実装するにはどうすれば良いか？
		 * サイクルソートのようなものを考えると上手くいきそう？
		 *
		 */
		int N = io.nextInt(), M = io.nextInt();
		int[][] A = io.nextInt(M, N);
		// ここから1回目の操作
		BitSet[] use = new BitSet[M];
		for (int i = 0;i < M;++ i) use[i] = new BitSet(N+1);
		for (int y = 0;y < N;++ y) {
			for (int x = 0;x < M;++ x) {
				if (use[x].get((A[y][x] - 1) / M)) {
					for (int k = x + 1;k < M;++ k) {
						if (!use[x].get((A[y][k] - 1) / M)) {
							int tmp = A[y][x];
							A[y][x] = A[y][k];
							A[y][k] = tmp;
							break;
						}
					}
					if (use[x].get((A[y][x] - 1) / M)) {
						for (int k = 0;k < M;++ k) {
							if (!use[x].get((A[y][k] - 1) / M) && !use[k].get((A[y][x] - 1) / M)) {
								use[k].flip((A[y][x] - 1) / M);
								use[k].flip((A[y][k] - 1) / M);
								use[x].flip((A[y][x] - 1) / M);
								int tmp = A[y][x];
								A[y][x] = A[y][k];
								A[y][k] = tmp;
								break;
							}
						}
					}
				}
				use[x].set((A[y][x] - 1) / M);
			}
		}
		io.println(A, "\n", " ");
		// ここから2回目の操作
		for (int x = 0;x < M;++ x) {
			for (int y = 0;y < N;++ y) {
				int tmp = A[y][x];
				A[y][x] = A[(tmp - 1) / M][x];
				A[(tmp - 1) / M][x] = tmp;
			}
		}
		io.println(A, "\n", " ");

	}

