    static class TaskD {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            int[][] a = in.readIntTable(n, m);
            MiscUtils.decreaseByOne(a);
            IntQueue[][] qty = new IntQueue[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    qty[i][j] = new IntArrayQueue();
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j : a[i]) {
                    qty[i][j / m].add(j + 1);
                }
            }
            int[][] b = new int[n][m];
            int[][] id = new int[n][n];
            for (int i = 0; i < m; i++) {
                ArrayUtils.fill(id, -1);
                Graph graph = new Graph(2 * n + 2);
                int source = 2 * n;
                int sink = source + 1;
                for (int j = 0; j < n; j++) {
                    graph.addFlowEdge(source, j, 1);
                    graph.addFlowEdge(j + n, sink, 1);
                    for (int k = 0; k < n; k++) {
                        if (!qty[j][k].isEmpty()) {
                            id[j][k] = graph.addFlowEdge(j, n + k, 1);
                        }
                    }
                }
                long flow = MaxFlow.dinic(graph, source, sink);
                if (flow != n) {
                    throw new RuntimeException();
                }
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if (id[j][k] != -1 && graph.flow(id[j][k]) > 0) {
                            b[j][i] = qty[j][k].poll();
                            break;
                        }
                    }
                }
            }
            for (int[] row : b) {
                out.printLine(row);
            }
            int[] column = new int[n];
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    column[j] = b[j][i];
                }
                ArrayUtils.sort(column);
                for (int j = 0; j < n; j++) {
                    b[j][i] = column[j];
                }
            }
            for (int[] row : b) {
                out.printLine(row);
            }
        }

    }

