    public void doSolve(OutputWriter out, int n, int m, int[][] a) {
      int[][] ind = new int[n][n];
      boolean[][] g = new boolean[n][n];
      for (int col = 0; col < m; ++col) {
        for (int i = 0; i < n; ++i) {
          Arrays.fill(g[i], false);
          for (int j = col; j < m; ++j) {
            g[i][a[i][j] / m] = true;
            ind[i][a[i][j] / m] = j;
          }
        }
        int[] matching = new int[n];
        MaxMatching.maxMatching(g, matching);
        for (int i = 0; i < n; ++i) {
          int row = matching[i];
          int pos = ind[row][i];
          {
            int t = a[row][pos];
            a[row][pos] = a[row][col];
            a[row][col] = t;
          }
        }
      }
      for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
          out.print((a[i][j] + 1) + " ");
        }
        out.printLine();
      }
      while (true) {
        boolean ch = false;
        for (int i = 0; i < n; ++i) {
          for (int j = 0; j < m; ++j) {
            int row = a[i][j] / m;
            if (row != i) {
              int t = a[i][j];
              a[i][j] = a[row][j];
              a[row][j] = t;
              ch = true;
            }
          }
        }
        if (!ch) {
          break;
        }
      }
