    public static class Task implements Runnable {
        final FastIO io;
        final Debug debug;
        int inf = (int) 1e8;

        public Task(FastIO io, Debug debug) {
            this.io = io;
            this.debug = debug;
        }

        @Override
        public void run() {
            solve();
        }

        int n;
        int m;

        public void solve() {
            n = io.readInt();
            m = io.readInt();
            int[][] mat = new int[n][m];
            int[][] first = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    mat[i][j] = io.readInt();
                }
            }

            for (int i = 0; i < n; i++) {
                Randomized.randomizedArray(mat[i], 0, m);
            }

            KMAlgo kmAlgo = new KMAlgo(m, m);


            int[][] pos = new int[m][2];
            for (int i = 0; i < n; i++) {
                int valSeqWpos = 0;
                kmAlgo.reset();
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < m; k++) {
                        if (rowIdOf(mat[j][k]) != i) {
                            continue;
                        }
                        pos[valSeqWpos][0] = j;
                        pos[valSeqWpos][1] = k;
                        for (int t = 0; t < m; t++) {
                            kmAlgo.edges[valSeqWpos][t] = first[j][t] == 0;
                        }
                        valSeqWpos++;
                    }
                }
                debug.assertTrue(valSeqWpos == m);
                for (int j = 0; j < m; j++) {
                    if (!kmAlgo.matchLeft(j)) {
                        throw new IllegalStateException();
                    }
                }
                for (int j = 0; j < m; j++) {
                    int col = kmAlgo.leftSides[j].partner.id;
                    first[pos[j][0]][col] = mat[pos[j][0]][pos[j][1]];
                }
                debug.debug("first", first);
            }

            int[][] second = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int row = rowIdOf(first[i][j]);
                    second[row][j] = first[i][j];
                }
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    io.cache.append(first[i][j]).append(' ');
                }
                io.cache.append('\n');
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    io.cache.append(second[i][j]).append(' ');
                }
                io.cache.append('\n');
            }
        }

        public int rowIdOf(int x) {
            return (x - 1) / m;
        }
    }


    public static class KMAlgo {
        public static class Node {
            int visited;
            Node partner;
            int id;

            @Override
            public String toString() {
                return "" + id;
            }
        }

        Node[] leftSides;
        Node[] rightSides;
        int version;

        boolean[][] edges;
        int l;
        int r;

        public KMAlgo(int l, int r) {
            this.l = l;
            this.r = r;
            leftSides = new Node[l];
            for (int i = 0; i < l; i++) {
                leftSides[i] = new Node();
                leftSides[i].id = i;
            }
            rightSides = new Node[r];
            for (int i = 0; i < r; i++) {
                rightSides[i] = new Node();
                rightSides[i].id = i;
            }

            edges = new boolean[l][r];
        }

        public void reset() {
            for (int i = 0; i < l; i++) {
                leftSides[i].partner = null;
            }
            for (int j = 0; j < r; j++) {
                rightSides[j].partner = null;
            }
        }

        private void init() {
            version++;
        }

        /**
         * Determine can we find a partner for a left node to enhance the matching degree.
         */
        public boolean matchLeft(int id) {
            if (leftSides[id].partner != null) {
                return false;
            }
            init();
            return findPartner(leftSides[id]);
        }

        private boolean findPartner(Node src) {
            if (src.visited == version) {
                return false;
            }
            src.visited = version;
            for (int i = 0; i < r; i++) {
                if (!edges[src.id][i]) {
                    continue;
                }
                Node node = rightSides[i];
                if (!tryRelease(node)) {
                    continue;
                }
                node.partner = src;
                src.partner = node;
                return true;
            }
            return false;
        }

        private boolean tryRelease(Node src) {
            if (src.visited == version) {
                return false;
            }
            src.visited = version;
            if (src.partner == null) {
                return true;
            }
            if (findPartner(src.partner)) {
                src.partner = null;
                return true;
            }
            return false;
        }

        @Override
        public String toString() {
            StringBuilder builder = new StringBuilder();
            for (int i = 1; i < leftSides.length; i++) {
                if (leftSides[i].partner == null) {
                    continue;
                }
                builder.append(leftSides[i].id).append(" - ").append(leftSides[i].partner.id).append(" || ");
            }
            if (builder.length() > 0) {
                builder.setLength(builder.length() - 4);
            }
            return builder.toString();
        }
    }

