	public void stepAll(int N, int M, int A[][],int Z[][]){
		int B[][] = new int[N + 1][M + 1];
		int C[][] = new int[N + 1][M + 1];
		for(int i = 1 ; i <= N ; i ++) {
			for(int j = 1 ; j <= M ; j ++) {
				if(Z[i][j] != 0 ) {
