				int m = num % M;
				if(m==0) {
					m = M ;
				}
				//縦位置を求める
				int n = (num-1)/M + 1;

				if(B[i][m] == 0) {
					B[i][m] = num ;
					if(C[n][m] == 0) {
						C[n][m] = num ;
					}else {
						for(int k = 1; k <= N ; k ++) {
							if(C[n][k] == 0) {
								C[n][k] = num ;
								break ;
							}
						}
					}
				}else {
					for(int k = 1; k <= M ; k ++) {
						if(B[i][k] == 0 && C[n][k] == 0) {
							B[i][k] = num ;
							C[n][k] = num ;
							break ;
						}
					}
				}
			}
		}
		for(int i = 1 ; i <= N ; i ++) {
			for(int j = 1 ; j <= M ; j ++) {
				if(Z[i][j] != 1 ) {
					continue ;
				}
				//横に動く
				int num = A[i][j] ;
				//横位置を見つける
				int m = num % M;
				if(m==0) {
					m = M ;
				}
				//縦位置を求める
				int n = (num-1)/M + 1;

				if(B[i][m] == 0) {
					B[i][m] = num ;
					if(C[n][m] == 0) {
						C[n][m] = num ;
					}else {
						for(int k = 1; k <= N ; k ++) {
							if(C[n][k] == 0) {
								C[n][k] = num ;
								break ;
							}
						}
					}
				}else {
					for(int k = 1; k <= M ; k ++) {
						if(B[i][k] == 0 && C[n][k] == 0) {
							B[i][k] = num ;
							C[n][k] = num ;
							break ;
						}
					}
				}
			}
		}
		for(int i = 1 ; i <= N ; i ++) {
			for(int j = 1 ; j <= M ; j ++) {
				if(Z[i][j] != 2 ) {
					continue ;
				}
				//横に動く
				int num = A[i][j] ;
				//横位置を見つける
				int m = num % M;
				if(m==0) {
					m = M ;
				}
				//縦位置を求める
				int n = (num-1)/M + 1;

				if(B[i][m] == 0) {
					B[i][m] = num ;
					if(C[n][m] == 0) {
						C[n][m] = num ;
					}else {
						for(int k = 1; k <= N ; k ++) {
							if(C[n][k] == 0) {
								C[n][k] = num ;
								break ;
							}
						}
					}
				}else {
					for(int k = 1; k <= M ; k ++) {
						if(B[i][k] == 0 && C[n][k] == 0) {
							B[i][k] = num ;
							C[n][k] = num ;
							break ;
						}
					}
				}
			}
		}


		for(int i = 1 ; i <= N ; i ++) {
			for(int j = 1 ; j <= M ; j ++) {
				System.out.print(B[i][j] + " ");
			}
			System.out.println();
		}
		for(int i = 1 ; i <= N ; i ++) {
			for(int j = 1 ; j <= M ; j ++) {
				System.out.print(C[i][j] + " ");
			}
			System.out.println();
		}
	}
}

import java.util.*;
import java.io.*;

public class Main {

	public static void main (String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] first = br.readLine().split(" ", 2);
		int h = Integer.parseInt(first[0]);
		int w = Integer.parseInt(first[1]);
		int[][] field = new int[h][w];
		for (int i = 0; i< h; i++) {
			String[] line = br.readLine().split(" ", w);
			for (int j = 0; j < w; j++) {
				field[i][j] = Integer.parseInt(line[j]);
			}
		}
		int[][] next = new int[w][h];
		int[] idxes = new int[h];
		int count = 0;
		while (count < h * w) {
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					int x = field[i][j];
					if (x == 0) {
						continue;
					}
					int y = (x - 1) / w;
					if (next[idxes[y]][i] == 0) {
						next[idxes[y]][i] = x;
						field[i][j] = 0;
						count++;
						idxes[y]++;
					}
				}
			}
		}
		StringBuilder sb = new StringBuilder();
		display(next, sb);
		for (int i = 0; i < w; i++) {
			Arrays.sort(next[i]);
		}
		display(next, sb);
		System.out.print(sb);
	}

	static void display(int[][] field, StringBuilder sb) {
		for (int i = 0; i < field[0].length; i++) {
			for (int j = 0; j < field.length; j++) {
				if (j != 0) {
					sb.append(" ");
				}
				sb.append(field[j][i]);
			}
			sb.append("\n");
		}
	}
}

