	public static int[] doBipartiteMatching(boolean[][] g)
	{
		int n = g.length;
		if(n == 0)return new int[0];
		int m = g[0].length;
		if(m == 0){
			int[] ret = new int[n];
			Arrays.fill(ret, -1);
			return ret;
