		if w == -1 || !b.used[w] && b.dfs(w) {
			b.match[u] = v
			b.match[v] = u
			return true
		}
	}

	return false
}

func (b *BipartiteMatching) matching() int {
	res := 0

	for v := 0; v < len(b.edges); v++ {
		if b.match[v] == -1 {
