// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()
	M := io.NextInt()

	mat := make([][]int, N)
	for i := range mat {
		mat[i] = make([]int, M)

		for j := 0; j < M; j++ {
			mat[i][j] = io.NextInt()
		}
	}

	filledA := make([][]bool, N)
	for i := range filledA {
		filledA[i] = make([]bool, M)
	}

	matA := make([][]int, N)
	for i := range matA {
		matA[i] = make([]int, M)
	}

	// col := val - M*row - 1

