		bp.init(M * 2)

		for j, val := range mat[i] {
			row := (val - 1) / M

			for k := 0; k < M; k++ {
				if !filledA[row][k] {
					bp.add(j, k+M)
				}
			}
		}

		bp.matching()

		for j, val := range mat[i] {
			row := (val - 1) / M
			k := bp.match[j] - M
			matA[i][k] = val
			filledA[row][k] = true
		}
	}

	for i := range matA {
		io.PrintInts(matA[i])
	}

	matB := make([][]int, N)
	for i := range matB {
