	for i := 0; i < M; i++ {
		tmp := make([]int, N)

		for j := 0; j < N; j++ {
			tmp[j] = matA[j][i]
		}

		sort.Ints(tmp)

		for j := 0; j < N; j++ {
			matB[j][i] = tmp[j]
		}
	}

	for i := range matB {
		io.PrintInts(matB[i])
	}
}

