type BipartiteMatching struct {
	edges [][]int
	match []int
	used  []bool
}

func (b *BipartiteMatching) init(n int) {
	b.edges = make([][]int, n)
	b.match = make([]int, n)

	for i := range b.match {
		b.match[i] = -1
	}
}

func (b *BipartiteMatching) add(from, to int) {
	b.edges[from] = append(b.edges[from], to)
	b.edges[to] = append(b.edges[to], from)
}

func (b *BipartiteMatching) dfs(v int) bool {
	b.used[v] = true

	for _, u := range b.edges[v] {
		w := b.match[u]
		if w == -1 || !b.used[w] && b.dfs(w) {
			b.match[u] = v
			b.match[v] = u
			return true
		}
	}

	return false
}

func (b *BipartiteMatching) exec() int {
	res := 0

	for v := 0; v < len(b.edges); v++ {
		if b.match[v] == -1 {
			b.used = make([]bool, len(b.edges))

			if b.dfs(v) {
				res++
			}
		}
	}

	return res
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()
	M := io.NextInt()

	mat := make([][]int, N)
	for i := range mat {
		mat[i] = make([]int, M)

		for j := 0; j < M; j++ {
			mat[i][j] = io.NextInt()
		}
	}

	filledA := make([][]bool, N)
	for i := range filledA {
		filledA[i] = make([]bool, M)
	}

	matA := make([][]int, N)
	for i := range matA {
		matA[i] = make([]int, M)
	}

	for i := range mat {
		bp := BipartiteMatching{}
		bp.init(M * 2)

		for j, val := range mat[i] {
			row := (val - 1) / M

			for k := 0; k < M; k++ {
				if !filledA[row][k] {
					bp.add(j, k+M)
				}
			}
		}

		bp.exec()

		for j, val := range mat[i] {
			row := (val - 1) / M
			if bp.match[j] == -1 {
				return
			}
			k := bp.match[j] - M

			matA[i][k] = val
			filledA[row][k] = true
		}
	}

	for i := range matA {
		io.PrintInts(matA[i])
	}

	matB := make([][]int, N)
	for i := range matB {
		matB[i] = make([]int, M)
	}

	// 縦でソートして埋める
	for i := 0; i < M; i++ {
		tmp := make([]int, N)

		for j := 0; j < N; j++ {
			tmp[j] = matA[j][i]
		}

		sort.Ints(tmp)

		for j := 0; j < N; j++ {
			matB[j][i] = tmp[j]
		}
	}

	for i := range matB {
		io.PrintInts(matB[i])
	}
}

