int head[N],Top=1;
inline void add(int u,int v){
	e[++Top].to=v;
	e[Top].nxt=head[u];
	head[u]=Top;
	e[Top].f=1;

	e[++Top].to=u;
	e[Top].nxt=head[v];
	head[v]=Top;
	e[Top].f=0;
}
#define min(a,b) ((a)<(b)?(a):(b))
#define id(x) (((x)-1)/m+1)
int S,T,cur[N],dep[N];
int dfs(int u,int flw){
	if(u==T) return flw;
//	printf("** %d\n",u);
	for(int &i=cur[u],v;i;i=e[i].nxt){
		v=e[i].to;
		if(e[i].f<=0||dep[v]!=dep[u]+1)continue;
		int flow=dfs(v,min(flw,e[i].f));
		if(flow){
			e[i].f-=flow;
			e[i^1].f+=flow;
			return flow;
		}
	}
}
std::queue<int> q;
bool bfs(){
	for(int i=1;i<=T;++i)
		dep[i]=0;
	dep[S]=1;
	q.push(S);
	while(!q.empty()){
		int u=q.front();q.pop();
//		printf("** %d\n",u);
		for(int i=head[u],v;i;i=e[i].nxt){
			v=e[i].to;
			if(dep[v]==0&&e[i].f>0){
				dep[v]=dep[u]+1;
				q.push(v);
			}
		}
	}
	return dep[T];
}
