# saidai flow
# Ford-Fulkerson
proc fulkerson(N:int, capFromTo:seq[seq[int]], siten:int, shuuten:int): seq[seq[int]] =
  var flowFromTo = newSeq2[int](N,N)
  var rsdCapFromTo = newSeq2[int](N,N)
  for src in 0..<N:
    for dst in 0..<N:
      rsdCapFromTo[src][dst] = capFromTo[src][dst]

  while true:
    var isIkeru = newSeq[bool](N)
    isIkeru.fill(false)
    var predOf = newSeq[int](N)
    var que = newSeq[int]()

    isIkeru[siten] = true
    predOf[siten] = -1
    que.add siten
    while que.len != 0:
      let src = que.pop()
      for dst in 0..<N:
        if rsdCapFromTo[src][dst] > 0:
          if not isIkeru[dst]:
            isIkeru[dst] = true
            predOf[dst] = src
            que.add dst
            if dst == shuuten:
              break

    if not isIkeru[shuuten]:
      break

    var b = shuuten
    while b != siten:
      var a = predOf[b]
      flowFromTo[a][b] += 1
      flowFromTo[b][a] -= 1
      rsdCapFromTo[a][b] -= 1
      rsdCapFromTo[b][a] += 1
      b = a


  return flowFromTo





