        F[0][i] = 0
        G[N + i][2 * N + 1] = 1
        F[N + i][2 * N + 1] = 0

    for t2 in range(N):
        queue = deque([0])
        searched = [0] * (2 * N + 2)
        searched[0] = 1
        parent = [0] * (2 * N + 2)

        while len(queue) > 0:
            p = queue.pop()
            for q in G[p].keys():
                if (G[p][q] > 0 or F[q][p] > 0) and searched[q] == 0:
                    parent[q] = p
                    searched[q] = 1
                    queue.append(q)
            if searched[2 * N + 1] == 1:
                break
        path = [2 * N + 1]
        while True:
            path.append(parent[path[-1]])
            if path[-1] == 0:
