                    match[i] = E[(i, j)].pop()
                    reserved[j%N] = True
                    nmatch += 1
                    i = j
                    break
        else:
            for j in range(N):
                if match[j]:
                    continue
                if V[j][i] > 0:
                    i = j
                    break
            else:
                i = 0
    return match

