fn main() {
    input!{
        n: usize,
        m: usize,
        a: [[usize; m]; n]
    }
    let mut es = vec![vec![vec![]; n]; n];
    for i in 0..n {
        for j in 0..m {
            es[i][(a[i][j] - 1) / m].push(a[i][j]);
        }
    }
    let mut b = vec![vec![0; m]; n];
    let mut c = vec![vec![0; m]; n];
    for i in 0..m {
        let mut g = vec![HashSet::new(); 2 * n + 2];
        for i in 0..n {
            for j in 0..n {
                if !es[i][j].is_empty() {
                    g[i].insert(n + j);
                }
            }
            g[2 * n].insert(i);
            g[n + i].insert(2 * n + 1);
        }
        let fpath = max_flow(2 * n, 2 * n + 1, &g);
        for &(u, v) in &fpath {
            if u < n {
                b[u][i] = es[u][v - n].pop().unwrap();
            }
        }
    }
    for i in 0..n {
        for j in 0..m {
            c[(b[i][j] - 1) / m][j] = b[i][j];
        }
    }
    print_tab(&b);
    print_tab(&c);
}

fn max_flow(s: usize, t: usize, g: &Vec<HashSet<usize>>) -> Vec<(usize, usize)> {
    let mut res = g.clone();
    let mut set = HashSet::new();
    while let Some(p) = bfs(s, t, &res) {
        for &(u, v) in &p {
            if set.contains(&(v, u)) {
                set.remove(&(v, u));
            } else {
                set.insert((u, v));
            }
            res[u].remove(&v);
            res[v].insert(u);
        }
    }
    set.iter().cloned().collect()
}

fn bfs(s: usize, t: usize, g: &Vec<HashSet<usize>>) -> Option<Vec<(usize, usize)>> {
    let n = g.len();
    let mut pre = vec![n; n];
    let mut q = VecDeque::new();
    q.push_back(s);
    while let Some(u) = q.pop_front() {
        if u == t {
            break;
        }
        for &v in g[u].iter() {
            if pre[v] == n {
                pre[v] = u;
                q.push_back(v);
            }
        }
    }
    if pre[t] == n {
        None
    } else {
        let mut ret = vec![];
        let mut p = t;
        while p != s {
            ret.push((pre[p], p));
            p = pre[p];
        }
        ret.reverse();
        Some(ret)
    }
}

