struct Matching {
    n: usize,
    graph: Vec<Vec<Vec<usize>>>,
    deg: Vec<usize>,
    itr: Vec<usize>,
    lvl: Vec<i32>,
}

impl Matching {
    fn new(n: usize) -> Self {
        Matching {
            n: n,
            graph: vec![vec![]; n],
            deg: vec![0; n],
            itr: vec![0; n],
            lvl: vec![0; n]
        }
    }

    fn add_edge(&mut self, u: usize, v: usize, cap: usize, label: usize) {
        let udeg = self.deg[u];
        let vdeg = self.deg[v];
        self.graph[u].push(vec![v, cap, vdeg, label]);
        self.graph[v].push(vec![u, 0, udeg, label]);
        self.deg[u] += 1;
        self.deg[v] += 1;
    }

    fn dfs(&mut self, v: usize, t: usize, f: usize) -> usize {
        if v == t {
            return f;
        }
        let mut it = self.itr[v];
        while it < self.graph[v].len() {
            self.itr[v] = it;

            let to = self.graph[v][it][0];
            let left_cap = self.graph[v][it][1];
            let rev_idx = self.graph[v][it][2];
            if left_cap > 0 && self.lvl[v] < self.lvl[to] {
                let d = self.dfs(to, t, min(left_cap, f));
                if d > 0 {
                    self.graph[v][it][1] -= d;
                    self.graph[to][rev_idx][1] += d;
                    return d;
                }
            }
            it += 1;
        }
        0
    }

    fn bfs(&mut self, s: usize) {
        for i in 0..self.n {
            self.lvl[i] = -1;
        }
        self.lvl[s] = 0;

        let mut queue = VecDeque::new();
        queue.push_back(s);
        while queue.len() >= 1 {
            let v = queue.pop_front().unwrap();
            let lv = self.lvl[v];
            let en = self.graph[v].len();
            for i in 0..en {
                let to = self.graph[v][i][0];
                let cap = self.graph[v][i][1];
                if cap > 0 && self.lvl[to] < 0 {
                    self.lvl[to] = lv + 1;
                    queue.push_back(to);
                }
            }
        }
    }

    fn max_flow(&mut self, s: usize, t: usize) -> usize {
        let mut flow = 0;
        loop {
            self.bfs(s);
            if self.lvl[t] < 0 {
                return flow;
            }
            for i in 0..self.n {
                self.itr[i] = 0;
            }
            loop {
                let f = self.dfs(s, t, 100000);
                if f == 0 {
                    break;
                }
                flow += f;
            }
        }
    }
}

fn main() {
    input! {
        n: usize, m: usize,
        a: [[usize1; m]; n]
    };

    let mut a = a;
    // let mut a = gen(n, m);
    // print_table(&a);

    let mut pmap = dvec!(0; n*m, 2);
    for i in 0..n {
        for j in 0..m {
            pmap[a[i][j]][0] = i;
            pmap[a[i][j]][1] = j;
        }
    }

    let mut b = dvec!(INF; n, m);
    for wj in 0..m {
        let mut mat = Matching::new(n*2+2);
        let source = n+n;
        let sink = n+n+1;
        for j in 0..n {
            mat.add_edge(source, j, 1, INF);
            mat.add_edge(n+j, sink, 1, INF);
        }
        for z in 0..n*m {
            let fi = pmap[z][0];
            if fi == INF {
                continue;
            }
            mat.add_edge(z / m, n + fi, 1, z);
        }

        let flow = mat.max_flow(source, sink);
        for fi in 0..n {
            for e in &mat.graph[fi] {
                if e[1] == 0 && n <= e[0] && e[0] < 2*n {
                    // used
                    b[(e[0])-n][wj] = e[3];
                    pmap[e[3]][0] = INF;
                    break;
                }
            }
        }
    }

    let mut c = dvec!(INF; n, m);
    for j in 0..m {
        for i in 0..n {
            c[b[i][j]/m][j] = b[i][j];
        }
    }
    print_table(&b);
    print_table(&c);
}

