struct BipartiteMatchingResult {
    left_to_right: Vec<Option<usize>>,
    right_to_left: Vec<Option<usize>>,
    num_matches: usize
}

fn hopcroft_karp(adj: &Vec<Vec<usize>>, num_r_vs: usize) -> BipartiteMatchingResult {
    use std::collections::VecDeque;

    let num_l_vs = adj.len();
    let mut usd = vec![false; num_l_vs];
    let mut mat = vec![num_l_vs; num_r_vs];

    fn augment(
        l: usize,
        adj: &Vec<Vec<usize>>,
        lev: &Vec<i32>,
        vis: &mut Vec<bool>,
        mat: &mut Vec<usize>,
    ) -> bool {
        let num_l_vs = adj.len();
        if l == num_l_vs {
            return true;
        }
        if vis[l] {
            return false;
        }
        vis[l] = true;
        for &r in adj[l].iter() {
            let l2 = mat[r];
            if lev[l2] > lev[l] && augment(l2, adj, lev, vis, mat) {
                mat[r] = l;
                return true;
            }
        }
        return false;
    }

    loop {
        let mut lev: Vec<i32> = vec![-1; num_l_vs + 1];
        lev[num_l_vs] = num_r_vs as i32;
        let mut que: VecDeque<usize> = VecDeque::new();

        for l in 0..num_l_vs {
            if !usd[l] {
                que.push_back(l);
                lev[l] = 0;
            }
        }

        while let Some(l) = que.pop_front() {
            for &r in adj[l].iter() {
                let l2 = mat[r];
                if lev[l2] < 0 {
                    lev[l2] = lev[l] + 1;
                    que.push_back(l2);
                }
            }
        }

        let mut vis = vec![false; num_l_vs];
        let mut update = false;
        for l in 0..num_l_vs {
            if !usd[l] && augment(l, adj, &lev, &mut vis, &mut mat) {
                usd[l] = true;
                update = true;
            }
        }

        if !update {
            break;
        }
    }

    // Generate result
    let mut left_to_right = vec![None; num_l_vs];
    let mut right_to_left = vec![None; num_r_vs];
    let mut num_matches = 0;
    for r in 0..num_r_vs {
        if mat[r] == num_l_vs {
            continue;
        }
        left_to_right[mat[r]] = Some(r);
        right_to_left[r] = Some(mat[r]);
        num_matches += 1;
    }
    BipartiteMatchingResult {
        left_to_right: left_to_right,
        right_to_left: right_to_left,
        num_matches: num_matches
    }
}

