        assert_eq!(place.len(), m);
        for i in 0..m {
            let row = place[i].0;
            for j in 0..m {
                if !occ[row][j] {
                    graph[i].push(j);
                }
            }
        }
        let (ans, matching) = hopcroft_karp(&graph, m);
        assert_eq!(ans, m);
        for j in 0..m {
            if matching[j] == m {
                continue;
            }
            let (x, y) = place[j];
            debugln!("{} {} {} -> {}", i, x, y, j);
            perm[x][y] = matching[j];
            occ[x][matching[j]] = true;
        }
    }
    for i in 0..n {
        debugln!("{:?}", perm[i]);
    }
    perm
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, m: usize,
        a: [[usize; m]; n],
    }
    let mut trans = vec![vec![0; m]; n];
    for i in 0..n {
        for j in 0..m {
            trans[i][j] = (a[i][j] - 1) / m;
        }
    }
    let perm = calc(&trans);
    let mut b = vec![vec![0; m]; n];
    for i in 0..n {
        for j in 0..m {
            b[i][perm[i][j]] = a[i][j];
        }
        for j in 0..m {
            puts!("{} ", b[i][j]);
        }
        puts!("\n");
    }
    let mut c = vec![vec![0; m]; n];
    for j in 0..m {
        let mut col = vec![0; n];
        for i in 0..n {
            col[i] = b[i][j];
        }
        col.sort();
        for i in 0..n {
            c[i][j] = col[i];
        }
    }
    for i in 0..n {
        for j in 0..m {
            puts!("{} ", c[i][j]);
        }
        puts!("\n");
    }
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

