fn main() {
    let h: usize = read();
    let w: usize = read();
    let a: Vec<Vec<usize>> = (0..h)
        .map(|_| (0..w).map(|_| read::<usize>() - 1).collect())
        .collect();

    // first step
    let mut b = vec![vec![!0; w]; h];
    {
        let mut usd = vec![vec![false; h]; w];

        for y in 0..h {
            let mut done = vec![false; w];

            for _ in 0..w {
                let mut cnt = vec![0; w];

                for x in 0..w {
                    if done[x] {
                        cnt[x] = 1000000000;
                        continue;
                    }
                    for tx in 0..w {
                        if b[y][tx] != !0 || usd[tx][a[y][x] / w] {
                            continue;
                        }
                        cnt[x] += 1;
                    }
                }

                let x = (0..w).min_by_key(|&x| cnt[x]).unwrap();
                if cnt[x] == 0 {
                    panic!();
                }

                for tx in 0..w {
                    if b[y][tx] != !0 || usd[tx][a[y][x] / w] {
                        continue;
                    }
                    b[y][tx] = a[y][x];
                    usd[tx][a[y][x] / w] = true;
                    break;
                }
                done[x] = true;
            }
        }
    }
    let b = b;
    show(&b);

    // second step
    let mut t: Vec<Vec<usize>> = transpose(&b);
    for row in t.iter_mut() {
        row.sort();
    }
    let c = transpose(&t);
    show(&c);
}

