struct XorShift {
    x: usize,
    y: usize,
    z: usize,
    w: usize
}

impl XorShift {
    fn new() -> XorShift {
        XorShift {
            x: 123456789,
            y: 362436069,
            z: 521288629,
            w: 88675123
        }
    }

    fn rotate(&mut self) {
        let t = self.x ^ (self.x << 11);
        self.x = self.y;
        self.y = self.z;
        self.z = self.w;
        self.w = (self.w ^ (self.w >> 19)) ^ (t ^ (t >> 8));
    }

    fn next_int(&mut self, n: usize) -> usize {
        self.rotate();
        let r = (self.w as i32) % (n as i32);
        if r < 0 {
            (r + n as i32) as usize
        } else {
            r as usize
        }
    }
}


fn gen(n: usize, m: usize) -> Vec<Vec<usize>> {
    let mut x = XorShift::new();
    let mut aw = vec![0; n*m];
    for i in 0..n {
        for j in 0..m {
            aw[i*m+j] = i*m+j;
        }
    }
    for i in 1..n*m {
        let w = x.next_int(i);
        let t = aw[i];
        aw[i] = aw[w];
        aw[w] = t;
    }

    let mut a = vec![vec![0; m]; n];
    for i in 0..n {
        for j in 0..m {
            a[i][j] = aw[i*m+j];
        }
    }
    a

}

fn main() {
    input! {
        n: usize, m: usize,
        a: [[usize1; m]; n]
    };

    let mut a = a;
    // let mut a = gen(n, m);
    for i in 0..n  {
        a[i].sort();
    }
    // print_table(&a);

    let mut pmap = dvec!(0; n*m, 2);
    for i in 0..n {
        for j in 0..m {
            pmap[a[i][j]][0] = i;
            pmap[a[i][j]][1] = j;
        }
    }

    let mut b = dvec!(INF; n, m);
    let mut xs = XorShift::new();
    while true {
        for i in 0..n {
            for j in 0..m {
                b[i][j] = INF;
            }
        }
        let mut iord = vec![0; n];
        for i in 0..n {
            iord[i] = i;
        }
        for i in 1..n {
            let j = xs.next_int(i);
            let t = iord[i];
            iord[i] = iord[j];
            iord[j] = t;
        }

        let mut comp = true;
        for zzi in 0..n {
            let i = iord[zzi];
            let mut vacant = vec![true; m];
            let mut ns = vec![vec![]; n];
            for j in 0..m {
                ns[pmap[i*m+j][0]].push(i*m+j);
            }

            let mut done = vec![false; n];
            let mut ngl = false;
            while true {
                if ngl {
                    comp = false;
                    break;
                }
                let mut sppz = vec![0; m];
                for ti in 0..n {
                    if done[ti] {
                        continue;
                    }
                    for j in 0..m {
                        if b[ti][j] == INF && vacant[j] {
                            sppz[j] += 1;
                        }
                    }
                }

                let mut bestn = n;
                let mut space = n+1;
                for ti in 0..n {
                    if done[ti] {
                        continue;
                    }
                    let mut ts = n;
                    for j in 0..m {
                        if b[ti][j] == INF {
                            ts = min(ts, sppz[j]);
                        }
                    }
                    if space > ts {
                        space = ts;
                        bestn = ti;
                    }
                }
                if bestn == n {
                    break;
                }
                let mut ng = false;
                for &ni in &ns[bestn] {
                    let mut bestj = m;
                    let mut bestv = n+10;
                    for j in 0..m {
                        if vacant[j] && b[bestn][j] == INF {
                            if bestv > sppz[j] {
                                bestj = j;
                                bestv = sppz[j];
                            }
                        }
                    }
                    if bestj == m {
                        ng = true;
                        break;
                    }
                    b[bestn][bestj] = ni;
                    vacant[bestj] = false;
                }
                if ng {
                    ngl = true;
                    break;
                }
                done[bestn] = true;
            }
        }
        if comp {
            break;
        }
    }


    // print_table(&b);


    let mut c = dvec!(INF; n, m);
    for j in 0..m {
        for i in 0..n {
            c[b[i][j]/m][j] = b[i][j];
        }
    }
    print_table(&b);
    print_table(&c);
}

